--
-- Name: can_access_assigned_waybill("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."can_access_assigned_waybill"("p_waybill_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.tms_waybill w
    where w.id = p_waybill_id
      and w.tenant_id = (select app_private.current_user_tenant_id())
      and w.driver_id = (select app_private.current_user_driver_id())
  );
$$;


