--

--
-- Name: cancel_workflow_instance("uuid", "text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."cancel_workflow_instance"("p_instance_id" "uuid", "p_comment" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_instance public.wf_instance;
  v_actor_name text;
  v_existing_instance_id uuid;
  v_comment text := btrim(coalesce(p_comment, ''));
begin
  if (select auth.uid()) is null or v_user_id is null
     or not (select app_private.is_platform_super()) then
    raise exception '仅平台超级管理员可以终止审批流程' using errcode = '42501';
  end if;
  if char_length(v_comment) < 4 then raise exception '终止原因至少填写4个字符'; end if;
  if char_length(v_comment) > 500 then raise exception '终止原因不能超过500个字符'; end if;

  select * into v_instance
  from public.wf_instance i
  where i.id = p_instance_id
  for update;
  if not found then raise exception '流程实例不存在或无权访问'; end if;

  if nullif(p_idempotency_key, '') is not null then
    select a.instance_id into v_existing_instance_id
    from public.wf_action a
    where a.tenant_id = v_instance.tenant_id
      and a.idempotency_key = p_idempotency_key;
    if found then
      if v_existing_instance_id <> p_instance_id then raise exception '幂等键已被其他流程使用'; end if;
      return p_instance_id;
    end if;
  end if;

  if v_instance.status <> 'running' then raise exception '流程已结束，不能再次终止'; end if;

  select coalesce(nullif(nick_name, ''), nullif(user_name, ''), user_email, id::text)
  into v_actor_name
  from public.sys_user
  where id = v_user_id;

  update public.wf_task
  set status = 'cancelled',
      handled_at = now(),
      comment = '流程管理员终止：' || v_comment
  where instance_id = p_instance_id and status = 'pending';

  update public.wf_instance
  set status = 'cancelled',
      current_node_key = null,
      current_node_name = null,
      finished_at = now(),
      finish_comment = v_comment,
      row_version = row_version + 1
  where id = p_instance_id;

  insert into public.wf_action(
    instance_id, action, actor_user_id, actor_name_snapshot, comment,
    metadata, idempotency_key, tenant_id
  ) values (
    p_instance_id, 'cancel', v_user_id, v_actor_name, v_comment,
    jsonb_build_object('source', 'workflow_monitor', 'operatorType', 'platform_super'),
    nullif(p_idempotency_key, ''), v_instance.tenant_id
  );

  perform app_private.apply_workflow_business_status(
    v_instance.business_type, v_instance.business_id, 'cancelled', v_actor_name, v_comment
  );
  return p_instance_id;
end;
$$;


ALTER FUNCTION "app_private"."cancel_workflow_instance"("p_instance_id" "uuid", "p_comment" "text", "p_idempotency_key" "text") OWNER TO "postgres";

--

--
-- Name: capture_ai_security_event(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."capture_ai_security_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'app_private', 'pg_temp'
    AS $$
declare haystack text; detected_type text; detected_severity text;
begin
  if tg_table_name='ai_feedback' then
    if coalesce(new.correction->>'issueType','')<>'unsafe' then return new; end if;
    insert into public.ai_security_event
      (tenant_id,run_id,feedback_id,event_type,severity,decision,status,title,detail,evidence,detected_at)
    values (new.tenant_id,new.run_id,new.id,'unsafe_output','high','observed','open',
      '不安全 AI 结果待复核',nullif(new.comment,''),jsonb_build_object('rating',new.rating,'correction',new.correction),new.create_time)
    on conflict (feedback_id,event_type) where feedback_id is not null
    do update set detail=excluded.detail,evidence=excluded.evidence,update_time=now();
    return new;
  end if;
  if tg_table_name='ai_tool_call' then
    if new.status<>'failed' then return new; end if;
    haystack:=lower(coalesce(new.error_message,''));
    detected_type:=case when haystack~'(prompt.?injection|jailbreak)' then 'prompt_injection'
      when haystack~'(sensitive|secret|credential|pii|privacy)' then 'sensitive_data'
      when haystack~'(denied|forbidden|permission|unauthori[sz]ed|policy)' then 'access_denied'
      else 'tool_failure' end;
    detected_severity:=case when detected_type in ('prompt_injection','sensitive_data') then 'high' else 'medium' end;
    insert into public.ai_security_event
      (tenant_id,run_id,tool_call_id,event_type,severity,decision,status,title,detail,evidence,detected_at)
    values (new.tenant_id,new.run_id,new.id,detected_type,detected_severity,
      case when detected_type in ('prompt_injection','sensitive_data','access_denied') then 'blocked' else 'observed' end,
      case when detected_type in ('prompt_injection','sensitive_data','access_denied') then 'blocked' else 'open' end,
      case detected_type when 'prompt_injection' then '提示词注入已识别' when 'sensitive_data' then '敏感数据调用已阻断'
        when 'access_denied' then '越权工具调用已拒绝' else 'AI 工具调用失败' end,
      nullif(new.error_message,''),jsonb_build_object('toolName',new.tool_name,'latencyMs',new.latency_ms),new.create_time)
    on conflict (tool_call_id,event_type) where tool_call_id is not null
    do update set severity=excluded.severity,decision=excluded.decision,status=excluded.status,detail=excluded.detail,evidence=excluded.evidence,update_time=now();
    return new;
  end if;
  if tg_table_name='ai_run' then
    if new.status not in ('failed','limited') then return new; end if;
    haystack:=lower(concat_ws(' ',new.error_code,new.error_message));
    detected_type:=case when haystack~'(prompt.?injection|jailbreak)' then 'prompt_injection'
      when haystack~'(sensitive|secret|credential|pii|privacy)' then 'sensitive_data'
      when haystack~'(denied|forbidden|permission|unauthori[sz]ed|policy)' then 'access_denied'
      else 'model_failure' end;
    detected_severity:=case when detected_type in ('prompt_injection','sensitive_data') then 'high' else 'medium' end;
    insert into public.ai_security_event
      (tenant_id,run_id,event_type,severity,decision,status,title,detail,evidence,detected_at)
    values (new.tenant_id,new.id,detected_type,detected_severity,
      case when detected_type in ('prompt_injection','sensitive_data','access_denied') then 'blocked' else 'observed' end,
      case when detected_type in ('prompt_injection','sensitive_data','access_denied') then 'blocked' else 'open' end,
      case detected_type when 'prompt_injection' then '提示词注入已识别' when 'sensitive_data' then '敏感数据输出已阻断'
        when 'access_denied' then '越权 AI 请求已拒绝' else 'AI 模型运行失败' end,
      nullif(new.error_message,''),jsonb_build_object('errorCode',new.error_code,'feature',new.feature,'model',new.model),new.started_at)
    on conflict (run_id,event_type) where run_id is not null and tool_call_id is null and feedback_id is null
    do update set severity=excluded.severity,decision=excluded.decision,status=excluded.status,detail=excluded.detail,evidence=excluded.evidence,update_time=now();
    return new;
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."capture_ai_security_event"() OWNER TO "postgres";

--

--
-- Name: create_workflow_delegation("uuid", timestamp with time zone, timestamp with time zone, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."create_workflow_delegation"("p_delegate_user_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_delegator_user_id uuid := (select app_private.current_app_user_id());
  v_actor_name text;
  v_delegate_name text;
  v_delegation_id uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_task record;
begin
  if (select auth.uid()) is null or v_delegator_user_id is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;
  if p_delegate_user_id = v_delegator_user_id then raise exception '不能委托给自己'; end if;
  if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
    raise exception '委托结束时间必须晚于开始时间';
  end if;
  if p_ends_at > p_starts_at + interval '180 days' then
    raise exception '单次委托不能超过 180 天';
  end if;
  if char_length(v_reason) not between 4 and 300 then
    raise exception '委托原因需填写 4 至 300 个字符';
  end if;

  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_actor_name
  from public.sys_user
  where id = v_delegator_user_id and tenant_id = v_tenant_id and status = '1';

  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_delegate_name
  from public.sys_user
  where id = p_delegate_user_id and tenant_id = v_tenant_id and status = '1';

  if v_actor_name is null or v_delegate_name is null then
    raise exception '委托人或受托人不存在、已停用或不属于当前租户';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('workflow-delegation:' || v_tenant_id::text || ':' || v_delegator_user_id::text, 91312)
  );

  if exists (
    select 1 from public.wf_delegation delegation
    where delegation.tenant_id = v_tenant_id
      and delegation.delegator_user_id = v_delegator_user_id
      and delegation.revoked_at is null
      and tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(p_starts_at, p_ends_at, '[)')
  ) then
    raise exception '该时间段已存在有效委托，请先调整或撤销原委托';
  end if;

  insert into public.wf_delegation(
    tenant_id, delegator_user_id, delegate_user_id, starts_at, ends_at, reason
  ) values (
    v_tenant_id, v_delegator_user_id, p_delegate_user_id, p_starts_at, p_ends_at, v_reason
  ) returning id into v_delegation_id;

  if p_starts_at <= now() and p_ends_at > now() then
    perform 1
    from public.wf_instance instance
    where instance.id in (
      select task.instance_id
      from public.wf_task task
      where task.tenant_id = v_tenant_id
        and task.assignee_user_id = v_delegator_user_id
        and task.status = 'pending'
    )
    order by instance.id
    for update;

    for v_task in
      select task.*, instance.business_type, instance.business_id, instance.business_title
      from public.wf_task task
      join public.wf_instance instance on instance.id = task.instance_id
      where task.tenant_id = v_tenant_id
        and task.assignee_user_id = v_delegator_user_id
        and task.status = 'pending'
      order by task.id
      for update of task
    loop
      update public.wf_task
      set assignee_user_id = p_delegate_user_id,
          assignee_name_snapshot = v_delegate_name,
          assignment_source = 'delegation',
          delegation_id = v_delegation_id,
          last_assigned_by = v_delegator_user_id,
          assignment_reason = v_reason
      where id = v_task.id;

      insert into public.wf_action(
        instance_id, task_id, node_key, node_name, action,
        actor_user_id, actor_name_snapshot, comment, metadata, tenant_id
      ) values (
        v_task.instance_id, v_task.id, v_task.node_key, v_task.node_name, 'delegate',
        v_delegator_user_id, v_actor_name, v_reason,
        jsonb_build_object(
          'delegationId', v_delegation_id,
          'fromUserId', v_delegator_user_id,
          'fromUserName', v_actor_name,
          'toUserId', p_delegate_user_id,
          'toUserName', v_delegate_name
        ), v_tenant_id
      );

      perform app_private.enqueue_user_notification(
        p_delegate_user_id, v_tenant_id, 'todo', '收到委托审批',
        v_actor_name || '将“' || v_task.business_title || '”委托给你审批：' || v_reason,
        'warning', 'workflow_delegation', v_task.id,
        v_task.business_type, v_task.business_id, v_task.instance_id,
        '/workflow/workbench', jsonb_build_object('tab','pending','instanceId',v_task.instance_id)
      );
    end loop;
  end if;

  return v_delegation_id;
end;
$$;


ALTER FUNCTION "app_private"."create_workflow_delegation"("p_delegate_user_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";

