    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.id
  from public.sys_user u
  join public.tms_driver d
    on d.tenant_id = u.tenant_id
   and d.phone = u.user_phone
   and d.enabled
  where u.auth_user_id = (select auth.uid())
    and u.status = '1'
  order by d.create_time desc
  limit 1;
$$;


