--

--
-- Name: delete_workflow_definition("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."delete_workflow_definition"("p_definition_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程删除权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    and (v_is_platform_super or d.tenant_id = v_current_tenant_id)
  for update;

  if not found then
    raise exception '流程不存在或无权删除';
  end if;

  if exists (
    select 1
    from public.wf_instance i
    where i.definition_id = p_definition_id
  ) then
    raise exception '流程已有审批记录，不能删除，只能停用';
  end if;

  if not v_is_platform_super and v_definition.current_version_id is not null then
    raise exception '普通租户管理员只能删除未发布流程';
  end if;

  delete from public.wf_definition
  where id = p_definition_id;
end;
$$;


ALTER FUNCTION "app_private"."delete_workflow_definition"("p_definition_id" "uuid") OWNER TO "postgres";

--

--
-- Name: document_number_period_key("text", timestamp with time zone, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."document_number_period_key"("p_reset_cycle" "text", "p_now" timestamp with time zone, "p_timezone" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_reset_cycle
    when 'year' then to_char(p_now at time zone p_timezone, 'YYYY')
    when 'month' then to_char(p_now at time zone p_timezone, 'YYYYMM')
    when 'day' then to_char(p_now at time zone p_timezone, 'YYYYMMDD')
    else ''
  end
$$;


ALTER FUNCTION "app_private"."document_number_period_key"("p_reset_cycle" "text", "p_now" timestamp with time zone, "p_timezone" "text") OWNER TO "postgres";

--

--
-- Name: enforce_enabled_dictionary_fields(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_enabled_dictionary_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_index integer;
  v_column_name text;
  v_type_code text;
  v_field_label text;
  v_raw_value text;
  v_normalized_value text;
  v_old_value text;
begin
  if tg_nargs = 0 or tg_nargs % 3 <> 0 then
    raise exception '字典字段守卫配置无效' using errcode = '22023';
  end if;

  v_index := 0;
  while v_index < tg_nargs loop
    v_column_name := tg_argv[v_index];
    v_type_code := tg_argv[v_index + 1];
    v_field_label := tg_argv[v_index + 2];
    v_raw_value := to_jsonb(new)->>v_column_name;

    if v_raw_value is not null then
      v_normalized_value := btrim(v_raw_value);
      if v_normalized_value = '' then
        raise exception '%不能为空', v_field_label using errcode = '22023';
      end if;

      v_old_value := case
        when tg_op = 'UPDATE' then btrim(to_jsonb(old)->>v_column_name)
        else null
      end;

      if not app_private.is_enabled_dictionary_value(v_type_code, v_normalized_value)
        and not (tg_op = 'UPDATE' and v_old_value = v_normalized_value) then
        raise exception '%无效或已停用', v_field_label using errcode = '22023';
      end if;

      new := jsonb_populate_record(
        new,
        jsonb_build_object(v_column_name, v_normalized_value)
      );
    end if;

    v_index := v_index + 3;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_enabled_dictionary_fields"() OWNER TO "postgres";

--

--
-- Name: enforce_platform_super_user(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_platform_super_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_platform_tenant_id uuid;
  v_super_role_code text;
  v_is_platform_tenant boolean;
  v_has_super_role boolean;
  v_old_is_protected boolean;
begin
  select t.id
  into v_platform_tenant_id
  from public.sys_tenant t
  where t.builtin_type = 'platform'
  limit 1;

  select r.role_code
  into v_super_role_code
  from public.sys_role r
  where r.builtin_type = 'platform_super'
  limit 1;

  if v_platform_tenant_id is null or v_super_role_code is null then
    raise exception '平台租户或平台超级角色缺失';
  end if;

  if tg_op = 'DELETE' then
    v_old_is_protected :=
      lower(old.user_email) = 'platform-owner@example.com'
      or (
        old.tenant_id = v_platform_tenant_id
        and v_super_role_code = any(coalesce(old.user_roles, array[]::text[]))
      );

    if v_old_is_protected then
      raise exception '平台超级管理员账号不可删除';
    end if;

    return old;
  end if;

  v_is_platform_tenant := new.tenant_id = v_platform_tenant_id;
  v_has_super_role := v_super_role_code = any(coalesce(new.user_roles, array[]::text[]));

  if v_is_platform_tenant and lower(new.user_email) <> 'platform-owner@example.com' then
    raise exception '平台租户只允许系统超级管理员账号';
  end if;

  if v_has_super_role and (
    not v_is_platform_tenant
    or lower(new.user_email) <> 'platform-owner@example.com'
  ) then
    raise exception '平台超级角色只能分配给平台租户的系统超级管理员';
  end if;

  if tg_op = 'UPDATE' then
    v_old_is_protected :=
      lower(old.user_email) = 'platform-owner@example.com'
      or (
        old.tenant_id = v_platform_tenant_id
        and v_super_role_code = any(coalesce(old.user_roles, array[]::text[]))
      );

    if v_old_is_protected and (
      new.tenant_id is distinct from old.tenant_id
      or lower(new.user_email) is distinct from lower(old.user_email)
      or not (v_super_role_code = any(coalesce(new.user_roles, array[]::text[])))
      or new.status is distinct from '1'
    ) then
      raise exception '平台超级管理员的租户、邮箱、角色和启用状态受系统保护';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_platform_super_user"() OWNER TO "postgres";

--

--
-- Name: enforce_sys_user_tenant_rules(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_sys_user_tenant_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'app_private'
    AS $$
declare
  v_user_email text;
  v_tenant_code text;
  v_invalid_role_codes text[];
begin
  select lower(u.user_email)
    into v_user_email
  from public.sys_user u
  where u.id = new.user_id;

  if v_user_email is null then
    raise exception 'User not found';
  end if;

  select lower(t.tenant_code)
    into v_tenant_code
  from public.sys_tenant t
  where t.id = new.tenant_id;

  if v_tenant_code is null then
    raise exception 'Tenant not found';
  end if;

  if v_tenant_code = 'platform' and v_user_email <> 'platform-owner@example.com' then
    raise exception 'Only 869123771@qq.com can be assigned to platform tenant';
  end if;

  if 'R_SUPER' = any(coalesce(new.role_codes, array[]::text[]))
     and (v_tenant_code <> 'platform' or v_user_email <> 'platform-owner@example.com') then
    raise exception 'R_SUPER can only be assigned to 869123771@qq.com in platform tenant';
  end if;

  select array_agg(role_code)
    into v_invalid_role_codes
  from unnest(coalesce(new.role_codes, array[]::text[])) as selected(role_code)
  where not exists (
    select 1
    from public.sys_role r
    where r.tenant_id = new.tenant_id
      and r.role_code = selected.role_code
      and r.enabled = true
  );

  if coalesce(array_length(v_invalid_role_codes, 1), 0) > 0 then
    raise exception 'Invalid role codes for tenant: %', array_to_string(v_invalid_role_codes, ',');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_sys_user_tenant_rules"() OWNER TO "postgres";

--

--
-- Name: enforce_system_organization_rules(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_system_organization_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.is_system is true then
      raise exception '系统预置根组织“%”不可删除', old.organization_name;
    end if;
    return old;
  end if;

  if old.is_system is true then
    if new.is_system is not true
      or new.tenant_id is distinct from old.tenant_id
      or new.parent_id is distinct from old.parent_id
      or new.organization_code is distinct from old.organization_code
      or new.organization_type is distinct from old.organization_type
      or new.status is distinct from '1'
    then
      raise exception '系统预置根组织的身份、租户、父级、编码、类型和启用状态不可修改';
    end if;
  elsif new.is_system is true then
    raise exception '不能将普通组织改为系统预置根组织';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_system_organization_rules"() OWNER TO "postgres";

--

--
-- Name: enforce_system_role_rules(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_system_role_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_builtin_type text;
  v_configured_as_default boolean := false;
begin
  if tg_op = 'DELETE' then
    if old.builtin_type is not null then
      raise exception '系统预置角色“%”不可删除', old.role_name;
    end if;

    select exists (
      select 1
      from public.sys_param p
      where p.param_key = 'registration.default_role_id'
        and p.enabled is true
        and p.param_value = old.id::text
    ) into v_configured_as_default;

    if v_configured_as_default then
      raise exception '角色“%”正在作为默认注册角色使用，请先修改注册策略', old.role_name;
    end if;

    return old;
  end if;

  select t.builtin_type
  into v_tenant_builtin_type
  from public.sys_tenant t
  where t.id = new.tenant_id;

  if new.builtin_type = 'platform_super' and v_tenant_builtin_type is distinct from 'platform' then
    raise exception '平台超级角色只能属于平台租户';
  end if;

  if new.builtin_type = 'default_register'
    and v_tenant_builtin_type is distinct from 'public_register'
  then
    raise exception '默认注册角色只能属于注册公共租户';
  end if;

  if new.builtin_type is not null and new.enabled is false then
    raise exception '系统预置角色不可停用';
  end if;

  if tg_op = 'UPDATE' then
    if old.builtin_type is not null then
      if new.builtin_type is distinct from old.builtin_type then
        raise exception '系统预置角色身份不可修改';
      end if;
      if new.tenant_id is distinct from old.tenant_id then
        raise exception '系统预置角色所属租户不可修改';
      end if;
      if new.role_code is distinct from old.role_code then
        raise exception '系统预置角色编码不可修改';
      end if;
      if new.enabled is false then
        raise exception '系统预置角色不可停用';
      end if;
    elsif new.builtin_type is not null then
      raise exception '不能将普通角色改为系统预置角色';
    end if;

    select exists (
      select 1
      from public.sys_param p
      where p.param_key = 'registration.default_role_id'
        and p.enabled is true
        and p.param_value = old.id::text
    ) into v_configured_as_default;

    if v_configured_as_default and (
      new.tenant_id is distinct from old.tenant_id
      or new.role_code is distinct from old.role_code
      or new.enabled is false
    ) then
      raise exception '当前角色正在作为默认注册角色使用，不能改租户、改编码或停用';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_system_role_rules"() OWNER TO "postgres";

--

--
-- Name: enforce_tms_transport_sensitive_writes(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enforce_tms_transport_sensitive_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_resource_key text := case tg_table_name when 'tms_order' then 'tms.order' else 'tms.waybill' end;
  v_owner_id uuid := old.created_by_user_id;
begin
  if tg_op <> 'UPDATE' or (select auth.uid()) is null or app_private.is_platform_super() then
    return new;
  end if;

  if tg_table_name = 'tms_order' then
    if new.shipping_contact_phone is distinct from old.shipping_contact_phone
       and app_private.resolve_field_access(v_resource_key, 'shipperContact', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for shipper contact' using errcode = '42501'; end if;
    if new.receiving_contact_phone is distinct from old.receiving_contact_phone
       and app_private.resolve_field_access(v_resource_key, 'receiverContact', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for receiver contact' using errcode = '42501'; end if;
    if (new.shipping_address_detail, new.shipping_address_id, new.shipping_longitude, new.shipping_latitude)
       is distinct from
       (old.shipping_address_detail, old.shipping_address_id, old.shipping_longitude, old.shipping_latitude)
       and app_private.resolve_field_access(v_resource_key, 'shipperAddress', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for shipper address' using errcode = '42501'; end if;
    if (new.receiving_address_detail, new.receiving_address_id, new.receiving_longitude, new.receiving_latitude)
       is distinct from
       (old.receiving_address_detail, old.receiving_address_id, old.receiving_longitude, old.receiving_latitude)
       and app_private.resolve_field_access(v_resource_key, 'receiverAddress', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for receiver address' using errcode = '42501'; end if;
    if app_private.tms_cargo_price_projection(new.cargo_items)
       is distinct from app_private.tms_cargo_price_projection(old.cargo_items)
       and app_private.resolve_field_access(v_resource_key, 'cargoPricing', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for cargo pricing' using errcode = '42501'; end if;
    if (new.transport_fee, new.delivery_fee, new.unloading_fee, new.collect_payment_fee,
        new.transfer_fee, new.insurance_fee, new.package_fee, new.other_fee, new.total_fee)
       is distinct from
       (old.transport_fee, old.delivery_fee, old.unloading_fee, old.collect_payment_fee,
        old.transfer_fee, old.insurance_fee, old.package_fee, old.other_fee, old.total_fee)
       and app_private.resolve_field_access(v_resource_key, 'freightAmounts', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for freight amounts' using errcode = '42501'; end if;
    if (new.declared_value, new.cash_amount, new.collect_amount, new.monthly_amount,
        new.cod_amount, new.handling_fee, new.payment_total, new.signed_cod_amount)
       is distinct from
       (old.declared_value, old.cash_amount, old.collect_amount, old.monthly_amount,
        old.cod_amount, old.handling_fee, old.payment_total, old.signed_cod_amount)
       and app_private.resolve_field_access(v_resource_key, 'settlementAmounts', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for settlement amounts' using errcode = '42501'; end if;
    if new.dispatch_driver_phone is distinct from old.dispatch_driver_phone
       and app_private.resolve_field_access(v_resource_key, 'driverPhone', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for driver phone' using errcode = '42501'; end if;
    if (new.image_urls, new.receipt_image_urls) is distinct from (old.image_urls, old.receipt_image_urls)
       and app_private.resolve_field_access(v_resource_key, 'proofAttachments', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for order proofs' using errcode = '42501'; end if;
    if (new.shipping_longitude, new.shipping_latitude, new.receiving_longitude, new.receiving_latitude)
       is distinct from
       (old.shipping_longitude, old.shipping_latitude, old.receiving_longitude, old.receiving_latitude)
       and app_private.resolve_field_access(v_resource_key, 'routeCoordinates', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for order coordinates' using errcode = '42501'; end if;
  else
    if new.shipper_phone is distinct from old.shipper_phone
       and app_private.resolve_field_access(v_resource_key, 'shipperContact', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for shipper contact' using errcode = '42501'; end if;
    if new.receiver_phone is distinct from old.receiver_phone
       and app_private.resolve_field_access(v_resource_key, 'receiverContact', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for receiver contact' using errcode = '42501'; end if;
    if (new.shipper_address, new.shipper_address_id, new.shipper_longitude, new.shipper_latitude)
       is distinct from (old.shipper_address, old.shipper_address_id, old.shipper_longitude, old.shipper_latitude)
       and app_private.resolve_field_access(v_resource_key, 'shipperAddress', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for shipper address' using errcode = '42501'; end if;
    if (new.receiver_address, new.receiver_address_id, new.receiver_longitude, new.receiver_latitude)
       is distinct from (old.receiver_address, old.receiver_address_id, old.receiver_longitude, old.receiver_latitude)
       and app_private.resolve_field_access(v_resource_key, 'receiverAddress', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for receiver address' using errcode = '42501'; end if;
    if new.freight_amount is distinct from old.freight_amount
       and app_private.resolve_field_access(v_resource_key, 'freightAmounts', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for waybill freight' using errcode = '42501'; end if;
    if (new.pickup_photos, new.delivery_photos, new.receipt_attachments)
       is distinct from (old.pickup_photos, old.delivery_photos, old.receipt_attachments)
       and app_private.resolve_field_access(v_resource_key, 'proofAttachments', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for waybill proofs' using errcode = '42501'; end if;
    if (new.route_points, new.shipper_longitude, new.shipper_latitude,
        new.receiver_longitude, new.receiver_latitude)
       is distinct from
       (old.route_points, old.shipper_longitude, old.shipper_latitude,
        old.receiver_longitude, old.receiver_latitude)
       and app_private.resolve_field_access(v_resource_key, 'routeCoordinates', v_owner_id) <> 'edit'
      then raise exception 'No edit permission for waybill coordinates' using errcode = '42501'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_tms_transport_sensitive_writes"() OWNER TO "postgres";

--

--
-- Name: enqueue_fms_posting_event("uuid", "text", "text", "uuid", "text", "date", "text", "jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."enqueue_fms_posting_event"("p_tenant_id" "uuid", "p_source_type" "text", "p_event_code" "text", "p_source_id" "uuid", "p_source_no" "text", "p_event_date" "date", "p_summary" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event_id uuid;
  v_account_set_id uuid;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text, 'system');
begin
  v_account_set_id := app_private.resolve_fms_posting_account_set(p_tenant_id);
  insert into public.fms_posting_event (
    tenant_id, account_set_id, source_type, event_code, source_id, source_no,
    event_date, summary, payload, status, create_by, update_by
  ) values (
    p_tenant_id, v_account_set_id, p_source_type, p_event_code, p_source_id,
    nullif(btrim(p_source_no), ''), p_event_date, btrim(p_summary),
    coalesce(p_payload, '{}'::jsonb),
    case when v_account_set_id is null then 'pending_configuration' else 'pending' end,
    v_actor, v_actor
  )
  on conflict (tenant_id, source_type, event_code, source_id) do update set
    account_set_id = coalesce(public.fms_posting_event.account_set_id, excluded.account_set_id),
    source_no = excluded.source_no,
    event_date = excluded.event_date,
    summary = excluded.summary,
    payload = excluded.payload,
    status = case
      when public.fms_posting_event.status in ('generated', 'reversed', 'ignored')
        then public.fms_posting_event.status
      when coalesce(public.fms_posting_event.account_set_id, excluded.account_set_id) is null
        then 'pending_configuration'
      else 'pending'
    end,
    update_by = excluded.update_by,
    update_time = now()
  returning id into v_event_id;
  perform app_private.process_fms_posting_event(v_event_id, false);
  return v_event_id;
end;
$$;


