CREATE OR REPLACE FUNCTION "app_private"."execute_workflow_business_callback_before_hr_p1"("p_business_type" "text", "p_business_id" "uuid", "p_status" "text", "p_actor" "text", "p_comment" "text") RETURNS "void"
