-- Name: is_platform_super(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."is_platform_super"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.sys_user u
    join public.sys_tenant t on t.id = u.tenant_id
    join public.sys_role r
      on r.tenant_id = u.tenant_id
     and r.builtin_type = 'platform_super'
     and r.role_code = any(coalesce(u.user_roles, array[]::text[]))
    where u.auth_user_id = auth.uid()
      and lower(u.user_email) = 'platform-owner@example.com'
      and t.builtin_type = 'platform'
      and u.status = '1'
      and r.enabled is true
  )
$$;


