--

--
-- Name: list_mdm_production_employees("uuid", integer, integer, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."list_mdm_production_employees"("p_id" "uuid", "p_from" integer, "p_to" integer, "p_keyword" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare tenant uuid:=app_private.current_user_tenant_id();
 contact boolean; identity boolean; payload jsonb;
begin
 if auth.uid() is null or not (
 app_private.has_permission('MdmProductionPersonnel:Add') or app_private.has_permission('MdmProductionPersonnel:Edit')
 or app_private.has_permission('MdmProductionPersonnel:View')) then
 raise exception '没有生产人员参选权限' using errcode='42501'; end if;
 contact:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','contactDetails',null) in ('read','edit');
 identity:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','identityDetails',null) in ('read','edit');
 with source as materialized (
  select e.id,e.tenant_id,e.employee_no,e.employee_name,e.avatar_url,e.job_title,e.employment_status,e.employment_type,
   case when contact then e.phone end as phone,case when identity then e.gender end as gender,
   e.hire_date,e.organization_id,o.organization_code,o.organization_name
  from public.mdm_employee e left join public.mdm_organization o on o.id=e.organization_id and o.tenant_id=e.tenant_id
  where app_private.tenant_in_current_read_scope(e.tenant_id) and e.employment_status in ('active','probation') and (p_id is null or e.id=p_id)
  and (nullif(btrim(p_keyword),'') is null or e.employee_no ilike '%'||p_keyword||'%' or e.employee_name ilike '%'||p_keyword||'%' or e.job_title ilike '%'||p_keyword||'%')
 ), page as (select * from source order by employee_name,employee_no,id offset greatest(coalesce(p_from,0),0) limit least(greatest(coalesce(p_to,9)-greatest(coalesce(p_from,0),0)+1,1),200))
 select jsonb_build_object('total',(select count(*) from source),'records',coalesce((select jsonb_agg(jsonb_build_object(
 'id',p.id,'tenant_id',p.tenant_id,'employee_no',p.employee_no,'employee_name',p.employee_name,
 'avatar_url',p.avatar_url,'job_title',p.job_title,'employment_status',p.employment_status,'employment_type',p.employment_type,
 'phone',p.phone,'gender',p.gender,'hire_date',p.hire_date,
 'organization',case when p.organization_id is null then null else jsonb_build_object('id',p.organization_id,'organization_code',p.organization_code,'organization_name',p.organization_name) end
 ) order by p.employee_name,p.employee_no,p.id) from page p),'[]'::jsonb),
 'field_access',jsonb_build_object('contactDetails',contact,'identityDetails',identity)) into payload;
 return payload;
end $$;


ALTER FUNCTION "app_private"."list_mdm_production_employees"("p_id" "uuid", "p_from" integer, "p_to" integer, "p_keyword" "text") OWNER TO "postgres";

--

--
-- Name: mark_header_notifications_read("text", "uuid"[]); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mark_header_notifications_read"("p_category" "text" DEFAULT NULL::"text", "p_notification_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_count integer;
begin
  if (select auth.uid()) is null or v_user_id is null or v_tenant_id is null then
    raise exception '当前登录用户未绑定业务账号' using errcode = '42501';
  end if;
  if p_category is not null and p_category not in ('notice', 'message') then
    raise exception '待办事项需完成审批后自动归档';
  end if;

  update public.sys_notification n
  set is_read = true,
      read_at = coalesce(n.read_at, now())
  where n.tenant_id = v_tenant_id
    and n.recipient_user_id = v_user_id
    and n.category in ('notice', 'message')
    and n.is_read = false
    and (p_category is null or n.category = p_category)
    and (p_notification_ids is null or n.id = any(p_notification_ids));

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "app_private"."mark_header_notifications_read"("p_category" "text", "p_notification_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: mask_permission_value("text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_length integer := char_length(coalesce(p_value, ''));
begin
  if p_value is null then
    return null;
  end if;

  return case p_strategy
    when 'phone' then
      case when v_length >= 7
        then left(p_value, 3) || repeat('*', greatest(v_length - 7, 4)) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'id_card' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'bank_account' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'address' then
      case when v_length > 6 then left(p_value, 6) || '***' else '***' end
    when 'amount' then '***'
    else '***'
  end;
end;
$$;


ALTER FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") OWNER TO "postgres";

--

--
-- Name: mdm_add_work_center_devices("uuid", "uuid"[], "uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid" DEFAULT NULL::"uuid", "p_point" "text" DEFAULT '无'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_target_tenant uuid;
  v_equipment_ids uuid[];
  v_inserted_count integer;
begin
  if auth.uid() is null
    or not app_private.has_permission('MdmWorkCenter:Devices')
  then
    raise exception '没有配置工作中心设备权限' using errcode = '42501';
  end if;

  select c.tenant_id
    into v_target_tenant
    from public.mdm_work_center c
   where c.id = p_work_center_id
     and app_private.tenant_in_current_read_scope(c.tenant_id);

  if v_target_tenant is null then
    raise exception '工作中心不存在或不在当前工作范围内';
  end if;

  if not app_private.is_platform_super()
    and v_target_tenant <> app_private.current_user_tenant_id()
  then
    raise exception '不能维护其他租户的工作中心设备' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct equipment_id), '{}'::uuid[])
    into v_equipment_ids
    from unnest(coalesce(p_equipment_ids, '{}'::uuid[])) as selected(equipment_id);

  if cardinality(v_equipment_ids) < 1 or cardinality(v_equipment_ids) > 100 then
    raise exception '请选择 1 至 100 台设备';
  end if;

  if p_point not in ('无', '投入点', '产出点') then
    raise exception '投入 / 产出点无效';
  end if;

  if p_main_equipment_id is not null
    and not (p_main_equipment_id = any(v_equipment_ids))
  then
    raise exception '主设备必须来自本次所选设备';
  end if;

  if p_main_equipment_id is not null
    and exists (
      select 1
        from public.mdm_work_center_device b
       where b.work_center_id = p_work_center_id
         and b.is_main
    )
  then
    raise exception '当前工作中心已经设置主设备';
  end if;

  if (
    select count(*)
      from public.mdm_equipment e
     where e.id = any(v_equipment_ids)
       and e.tenant_id = v_target_tenant
       and e.status = 'enabled'
       and not exists (
         select 1
           from public.mdm_work_center_device b
          where b.equipment_id = e.id
       )
  ) <> cardinality(v_equipment_ids)
  then
    raise exception '所选设备无效或已被其他工作中心关联';
  end if;

  insert into public.mdm_work_center_device (
    tenant_id,
    work_center_id,
    equipment_id,
    is_main,
    point
  )
  select
    v_target_tenant,
    p_work_center_id,
    equipment_id,
    equipment_id = p_main_equipment_id,
    p_point
  from unnest(v_equipment_ids) as selected(equipment_id);

  get diagnostics v_inserted_count = row_count;
  return v_inserted_count;
end
$$;


ALTER FUNCTION "app_private"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid", "p_point" "text") OWNER TO "postgres";

--

--
-- Name: mdm_bom_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_bom_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
begin
  if tg_op <> 'DELETE' then
    if new.group_id is not null and not exists(
      select 1 from public.mdm_master_group g
      where g.id=new.group_id and g.tenant_id=new.tenant_id and g.domain='bom' and g.enabled
    ) then
      raise exception '所选 BOM 分组不存在、已停用或不属于当前租户' using errcode='23503';
    end if;
    if new.base_quantity <= 0 or new.base_quantity <> trunc(new.base_quantity) then
      raise exception '基准数量必须为大于 0 的整数' using errcode='23514';
    end if;
  end if;
  if tg_op = 'INSERT' and new.status <> 'design' then
    raise exception '新建 BOM 必须处于设计状态' using errcode='22023';
  end if;
  if tg_op = 'UPDATE' and new.bom_code is distinct from old.bom_code then
    raise exception 'BOM 编码由系统生成，不允许修改' using errcode='22023';
  end if;
  if tg_op = 'UPDATE' and old.status <> new.status then
    v_permission := case
      when old.status in ('design','changing') and new.status='review' then 'MdmBomMaintenance:Submit'
      when old.status='review' and new.status='effective' then 'MdmBomMaintenance:Approve'
      when old.status='review' and new.status='design' then 'MdmBomMaintenance:Approve'
      when old.status='effective' and new.status='changing' then 'MdmBomMaintenance:Edit'
      when old.status in ('effective','changing') and new.status='archived' then 'MdmBomMaintenance:Archive'
      when old.status not in ('archived','void') and new.status='void' then 'MdmBomMaintenance:Archive'
      else null end;
    if v_permission is null then
      raise exception '不允许从 % 状态变更为 %', old.status, new.status using errcode='22023';
    end if;
    if not app_private.has_permission(v_permission) then
      raise exception '当前账号没有执行 BOM 状态变更的权限' using errcode='42501';
    end if;
  end if;
  if tg_op='DELETE' and old.status <> 'design' then
    raise exception '仅设计状态的 BOM 可以删除' using errcode='55000';
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$$;


ALTER FUNCTION "app_private"."mdm_bom_guard"() OWNER TO "postgres";

--

--
-- Name: mdm_bom_item_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_bom_item_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_bom public.mdm_bom%rowtype;
  v_cycle boolean;
begin
  select * into v_bom from public.mdm_bom where id=coalesce(new.bom_id, old.bom_id) and tenant_id=coalesce(new.tenant_id, old.tenant_id);
  if not found then raise exception 'BOM 不存在或不属于当前租户' using errcode='P0002'; end if;
  if v_bom.status not in ('design','changing') then raise exception '仅设计或变更中的 BOM 可以调整组件' using errcode='55000'; end if;
  if tg_op <> 'DELETE' then
    if new.component_material_id=v_bom.material_id then raise exception '父项物料不能作为自身组件' using errcode='23514'; end if;
    with recursive dependency(material_id, path) as (
      select child.material_id, array[v_bom.material_id, child.material_id]
      from public.mdm_bom child
      where child.tenant_id=v_bom.tenant_id and child.material_id=new.component_material_id and child.status <> 'void'
      union all
      select next_bom.material_id, dependency.path || next_bom.material_id
      from dependency
      join public.mdm_bom_item next_item on next_item.tenant_id=v_bom.tenant_id and next_item.bom_id in (
        select id from public.mdm_bom where tenant_id=v_bom.tenant_id and material_id=dependency.material_id and status <> 'void'
      )
      join public.mdm_bom next_bom on next_bom.tenant_id=v_bom.tenant_id and next_bom.material_id=next_item.component_material_id and next_bom.status <> 'void'
      where not next_bom.material_id=any(dependency.path)
    ) select exists(select 1 from dependency where material_id=v_bom.material_id) into v_cycle;
    if v_cycle then raise exception '该组件会形成循环 BOM' using errcode='23514'; end if;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


ALTER FUNCTION "app_private"."mdm_bom_item_guard"() OWNER TO "postgres";

--

--
-- Name: mdm_change_request_state_audit(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_change_request_state_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action text;
  v_comment text;
  v_actor_user_id uuid;
  v_actor_email text;
begin
  if tg_op = 'UPDATE' and new.state is not distinct from old.state then
    return new;
  end if;

  v_action := coalesce(
    nullif(current_setting('app.mdm_change_action', true), ''),
    case when tg_op = 'INSERT' then 'create' else 'system_transition' end
  );
  v_comment := nullif(current_setting('app.mdm_change_comment', true), '');

  begin
    v_actor_user_id := app_private.mdm_current_actor_user_id();
    v_actor_email := app_private.mdm_current_actor_email();
  exception when sqlstate '42501' then
    v_actor_user_id := null;
    v_actor_email := 'system';
  end;

  insert into public.mdm_change_request_event (
    tenant_id,
    request_id,
    from_state,
    to_state,
    action,
    actor_user_id,
    actor_email,
    comment,
    snapshot
  ) values (
    new.tenant_id,
    new.id,
    case when tg_op = 'UPDATE' then old.state else null end,
    new.state,
    v_action,
    v_actor_user_id,
    v_actor_email,
    v_comment,
    jsonb_build_object(
      'requestNo', new.request_no,
      'domainKey', new.domain_key,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'operation', new.operation,
      'version', new.version,
      'effectiveAt', new.effective_at,
      'beforeData', new.before_data,
      'proposedData', new.proposed_data
    )
  );

  perform app_private.mdm_emit_outbox_event(
    new.tenant_id,
    'change_request',
    new.id,
    'mdm.change-request.' || replace(new.state, '_', '-'),
    jsonb_build_object(
      'requestId', new.id,
      'requestNo', new.request_no,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'operation', new.operation,
      'state', new.state,
      'effectiveAt', new.effective_at,
      'beforeData', new.before_data,
      'proposedData', new.proposed_data
    )
  );

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_change_request_state_audit"() OWNER TO "postgres";

