--
-- Name: mdm_operational_master_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_operational_master_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_domain text; v_id uuid;
begin
 v_domain:=case tg_table_name when 'mdm_customer' then 'customer' when 'mdm_project' then 'project' when 'mdm_operation' then 'operation' else null end;
 if new.group_id is not null and not exists(select 1 from public.mdm_master_group g where g.id=new.group_id and g.tenant_id=new.tenant_id and g.domain=v_domain) then
  raise exception '所选分组不属于当前主数据或租户' using errcode='23503';
 end if;
 if tg_table_name='mdm_operation' then
  foreach v_id in array new.work_center_ids loop
   if not exists(select 1 from public.mdm_work_center c where c.id=v_id and c.tenant_id=new.tenant_id) then raise exception '工作中心不属于当前租户' using errcode='23503'; end if;
  end loop;
 end if;
 return new;
end $$;


ALTER FUNCTION "app_private"."mdm_operational_master_guard"() OWNER TO "postgres";

