--

--
-- Name: mdm_process_route_child_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_child_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant uuid;
  v_route uuid;
  v_sequence_type text;
  v_is_first boolean;
  v_is_last boolean;
  v_copying boolean := coalesce(current_setting('app.process_route_copy', true), '0') = '1';
begin
  if tg_table_name = 'mdm_process_route_sequence' then
    select tenant_id into v_tenant
    from public.mdm_process_route
    where id = new.route_id;

    if v_tenant is null then
      raise exception '工艺路线不存在' using errcode = '23503';
    end if;
    new.tenant_id := v_tenant;

    if new.sequence_type <> 'parallel'
       and (new.transfer_in_step_id is not null or new.transfer_out_step_id is not null) then
      raise exception '仅并行序列可维护转入、转出工序' using errcode = '23514';
    end if;

    if new.sequence_type = 'parallel'
       and new.transfer_in_step_id is null
       and new.transfer_out_step_id is null
       and not v_copying then
      raise exception '并行序列的转入、转出工序不能同时为空' using errcode = '23514';
    end if;

    if new.transfer_in_step_id is not null then
      select seq.sequence_type, step.is_last
      into v_sequence_type, v_is_last
      from public.mdm_process_route_step step
      join public.mdm_process_route_sequence seq on seq.id = step.sequence_id
      where step.id = new.transfer_in_step_id
        and step.tenant_id = v_tenant
        and step.route_id = new.route_id;

      if not found or v_sequence_type <> 'main' then
        raise exception '转入工序必须是当前路线的标准工序' using errcode = '23514';
      end if;
      if v_is_last then
        raise exception '转入工序不能是标准工序的末序' using errcode = '23514';
      end if;
    end if;

    if new.transfer_out_step_id is not null then
      select seq.sequence_type, step.is_first
      into v_sequence_type, v_is_first
      from public.mdm_process_route_step step
      join public.mdm_process_route_sequence seq on seq.id = step.sequence_id
      where step.id = new.transfer_out_step_id
        and step.tenant_id = v_tenant
        and step.route_id = new.route_id;

      if not found or v_sequence_type <> 'main' then
        raise exception '转出工序必须是当前路线的标准工序' using errcode = '23514';
      end if;
      if v_is_first then
        raise exception '转出工序不能是标准工序的首序' using errcode = '23514';
      end if;
    end if;
  else
    select tenant_id into v_tenant
    from public.mdm_process_route
    where id = new.route_id;

    select route_id into v_route
    from public.mdm_process_route_sequence
    where id = new.sequence_id
      and tenant_id = v_tenant;

    if v_tenant is null or v_route is distinct from new.route_id then
      raise exception '工序序列不属于当前工艺路线' using errcode = '23503';
    end if;
    new.tenant_id := v_tenant;
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_process_route_child_guard"() OWNER TO "postgres";

--

--
-- Name: mdm_process_route_create_default_sequence(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_create_default_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sequence_id uuid;
begin
  if coalesce(current_setting('app.process_route_copy', true), '0') = '1' then
    return new;
  end if;

  insert into public.mdm_process_route_sequence(
    tenant_id, route_id, sequence_no, sequence_type, remark
  )
  values (new.tenant_id, new.id, 1, 'main', '标准序列')
  returning id into v_sequence_id;

  insert into public.mdm_process_route_step(
    tenant_id, route_id, sequence_id, code, name, sort, is_first, is_last
  )
  values (new.tenant_id, new.id, v_sequence_id, '10', '待维护', 10, true, true);

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_process_route_create_default_sequence"() OWNER TO "postgres";

--

--
-- Name: mdm_process_route_prepare(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_prepare"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_next integer;v_unit uuid;begin
 if new.code is null or btrim(new.code)='' then perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':mdm_process_route',0));select coalesce(max(substring(code from '[0-9]+$')::integer),0)+1 into v_next from public.mdm_process_route where tenant_id=new.tenant_id and code~'^PR[0-9]+$';new.code:='PR'||lpad(v_next::text,4,'0');end if;
 if new.production_unit_id is null then select production_unit_id into v_unit from public.mdm_material where id=new.material_id and tenant_id=new.tenant_id;new.production_unit_id:=v_unit;end if;
 if new.group_id is not null and not exists(select 1 from public.mdm_master_group g where g.id=new.group_id and g.tenant_id=new.tenant_id and g.domain='process-route') then raise exception '工艺路线分组无效' using errcode='23503';end if;return new;end$_$;


ALTER FUNCTION "app_private"."mdm_process_route_prepare"() OWNER TO "postgres";

--

--
-- Name: mdm_process_route_references("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_references"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; result jsonb;
begin
  if auth.uid() is null or not app_private.has_permission('MdmProcessRoute:View') then
    raise exception '没有查看工艺路线权限' using errcode = '42501';
  end if;
  if app_private.is_platform_super() then
    v_tenant := p_tenant_id;
  else
    v_tenant := app_private.current_user_tenant_id();
  end if;

  select jsonb_build_object(
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', g.id, 'code', g.code, 'name', g.name, 'tenant_id', g.tenant_id
      ) order by g.sort, g.code)
      from public.mdm_master_group g
      where g.domain = 'process-route' and g.enabled
        and (v_tenant is null or g.tenant_id = v_tenant)
    ), '[]'::jsonb),
    'operations', coalesce((
      select jsonb_agg(jsonb_build_object('id', o.id, 'code', o.code, 'name', o.name) order by o.code)
      from public.mdm_operation o
      where o.enabled and (v_tenant is null or o.tenant_id = v_tenant)
    ), '[]'::jsonb),
    'control_codes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id,
        'code', c.control_code,
        'name', c.control_code_name,
        'processing_mode', c.processing_mode,
        'report_mode', c.report_mode,
        'inspection_mode', c.inspection_mode,
        'sequence_control', c.sequence_control,
        'rework_mode', c.rework_mode
      ) order by c.control_code)
      from public.mdm_operation_control_code c
      where c.enabled and (v_tenant is null or c.tenant_id = v_tenant)
    ), '[]'::jsonb),
    'units', coalesce((
      select jsonb_agg(jsonb_build_object('id', u.id, 'code', u.unit_code, 'name', u.unit_name) order by u.unit_code)
      from public.mdm_unit_of_measure u
      where v_tenant is null or u.tenant_id = v_tenant
    ), '[]'::jsonb),
    'departments', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'code', d.code, 'name', d.name) order by d.sort, d.code)
      from public.mdm_production_department d
      where d.enabled and (v_tenant is null or d.tenant_id = v_tenant)
    ), '[]'::jsonb),
    'work_centers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', w.id, 'code', w.code, 'name', w.name, 'department_id', w.department_id
      ) order by w.code)
      from public.mdm_work_center w
      where v_tenant is null or w.tenant_id = v_tenant
    ), '[]'::jsonb),
    'activity_formulas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'code', a.code, 'name', a.name,
        'plan_expression', a.plan_expression, 'report_expression', a.report_expression, 'activity_type', a.activity_type
      ) order by a.code)
      from public.mdm_activity_formula a
      where a.enabled and (v_tenant is null or a.tenant_id = v_tenant)
    ), '[]'::jsonb),
    'suppliers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'code', coalesce(s.supplier_code, ''), 'name', s.supplier_name
      ) order by s.supplier_code)
      from public.mdm_supplier s
      where v_tenant is null or s.tenant_id = v_tenant
    ), '[]'::jsonb),
    'esop_documents', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', e.id, 'code', e.document_code, 'name', e.document_name
      ) order by e.document_code)
      from public.mdm_esop_document e
      where v_tenant is null or e.tenant_id = v_tenant
    ), '[]'::jsonb)
  ) into result;
  return result;
end
$$;


ALTER FUNCTION "app_private"."mdm_process_route_references"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_process_route_resequence_flags(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_resequence_flags"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sequence_ids uuid[] := '{}'::uuid[];
  v_sequence_id uuid;
begin
  if tg_op <> 'INSERT' then
    v_sequence_ids := array_append(v_sequence_ids, old.sequence_id);
  end if;
  if tg_op <> 'DELETE' then
    v_sequence_ids := array_append(v_sequence_ids, new.sequence_id);
  end if;

  foreach v_sequence_id in array v_sequence_ids loop
    if v_sequence_id is null then continue; end if;

    with ranked as (
      select
        id,
        row_number() over (order by sort, code, id) as first_rank,
        row_number() over (order by sort desc, code desc, id desc) as last_rank
      from public.mdm_process_route_step
      where sequence_id = v_sequence_id
    )
    update public.mdm_process_route_step step
    set
      is_first = ranked.first_rank = 1,
      is_last = ranked.last_rank = 1
    from ranked
    where step.id = ranked.id
      and (
        step.is_first is distinct from (ranked.first_rank = 1)
        or step.is_last is distinct from (ranked.last_rank = 1)
      );

    if exists (
      select 1
      from public.mdm_process_route_sequence branch
      left join public.mdm_process_route_step transfer_in
        on transfer_in.id = branch.transfer_in_step_id
      left join public.mdm_process_route_step transfer_out
        on transfer_out.id = branch.transfer_out_step_id
      where branch.sequence_type = 'parallel'
        and (
          (transfer_in.sequence_id = v_sequence_id and transfer_in.is_last)
          or (transfer_out.sequence_id = v_sequence_id and transfer_out.is_first)
        )
    ) then
      raise exception '调整工序顺序后，并行序列的转入或转出工序落在了标准工序边界，请先调整并行序列'
        using errcode = '23514';
    end if;
  end loop;

  return null;
end
$$;


ALTER FUNCTION "app_private"."mdm_process_route_resequence_flags"() OWNER TO "postgres";

--

--
-- Name: mdm_process_route_standard_sequence_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_standard_sequence_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
     and old.sequence_type = 'main'
     and (
       new.sequence_type is distinct from old.sequence_type
       or new.sequence_no is distinct from 1
       or new.route_id is distinct from old.route_id
       or new.tenant_id is distinct from old.tenant_id
     ) then
    raise exception '标准序列是工艺路线的默认序列，不允许修改序号、类型或所属路线'
      using errcode = '23514';
  end if;

  if new.sequence_type = 'main' and new.sequence_no <> 1 then
    raise exception '标准序列的序号必须为 1'
      using errcode = '23514';
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_process_route_standard_sequence_guard"() OWNER TO "postgres";

