--

--
-- Name: mdm_production_reference_list("text", "text", integer, integer, "uuid", "uuid", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_production_reference_list"("p_kind" "text", "p_keyword" "text", "p_from" integer, "p_to" integer, "p_route_id" "uuid", "p_center_id" "uuid", "p_bound" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; tenant uuid:=app_private.current_user_tenant_id();term text:=replace(replace(replace(coalesce(p_keyword,''),'\','\\'),'%','\%'),'_','\_');
begin
 if auth.uid() is null or not(app_private.has_permission('MdmWorkCenter:View') or app_private.has_permission('MdmOperationTemplate:View') or app_private.has_permission('MdmProcessRoute:View')) then raise exception '没有查看生产配置权限' using errcode='42501';end if;
 if p_from<0 or p_to<p_from or p_to-p_from>999 then raise exception '分页范围无效';end if;
 if p_kind='routes' then
 with source as(select r.*,jsonb_build_object('id',m.id,'material_code',m.material_code,'material_name',m.material_name,'specification_model',m.specification_model) material from public.mdm_process_route r join public.mdm_material m on m.id=r.material_id and m.tenant_id=r.tenant_id where app_private.tenant_in_current_read_scope(r.tenant_id) and r.name ilike '%'||term||'%'),page as(select * from source order by create_time desc limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 elsif p_kind='steps' then
 with source as(select s.*,jsonb_build_object('id',r.id,'name',r.name,'material',jsonb_build_object('id',m.id,'material_code',m.material_code,'material_name',m.material_name,'specification_model',m.specification_model)) route,
 case when t.id is not null then jsonb_build_object('id',t.id,'name',t.name,'total_score',t.total_score) end template,
 case when c.id is not null then jsonb_build_object('id',c.id,'code',c.code,'name',c.name) end work_center
 from public.mdm_process_route_step s join public.mdm_process_route r on r.id=s.route_id and r.tenant_id=s.tenant_id join public.mdm_material m on m.id=r.material_id and m.tenant_id=s.tenant_id left join public.mdm_operation_template t on t.id=s.template_id and t.tenant_id=s.tenant_id left join public.mdm_work_center c on c.id=s.work_center_id and c.tenant_id=s.tenant_id
 where app_private.tenant_in_current_read_scope(s.tenant_id) and (p_route_id is null or s.route_id=p_route_id) and (p_center_id is null or s.work_center_id=p_center_id) and (p_bound is null or (s.template_id is not null)=p_bound) and (s.code ilike '%'||term||'%' or s.name ilike '%'||term||'%' or m.material_code ilike '%'||term||'%' or m.material_name ilike '%'||term||'%' or m.specification_model ilike '%'||term||'%' or r.name ilike '%'||term||'%' or t.name ilike '%'||term||'%')),page as(select * from source order by sort,code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 elsif p_kind='devices' and app_private.has_permission('MdmWorkCenter:View') then
 select jsonb_build_object('records',coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('equipment',jsonb_build_object('id',e.id,'equipment_code',e.equipment_code,'equipment_name',e.equipment_name))),'[]'),'total',count(*)) into result from public.mdm_work_center_device d join public.mdm_equipment e on e.id=d.equipment_id and e.tenant_id=d.tenant_id where app_private.tenant_in_current_read_scope(d.tenant_id) and d.work_center_id=p_center_id;
 else raise exception '未知生产配置查询';end if;return result;
end $$;


ALTER FUNCTION "app_private"."mdm_production_reference_list"("p_kind" "text", "p_keyword" "text", "p_from" integer, "p_to" integer, "p_route_id" "uuid", "p_center_id" "uuid", "p_bound" boolean) OWNER TO "postgres";

--

--
-- Name: mdm_production_reference_options("text", "text", integer, integer); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_production_reference_options"("p_kind" "text", "p_keyword" "text", "p_from" integer, "p_to" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;tenant uuid:=app_private.current_user_tenant_id();term text:=replace(replace(replace(coalesce(p_keyword,''),'\','\\'),'%','\%'),'_','\_');
begin
 if auth.uid() is null or not ((p_kind='material' and app_private.has_permission('MdmProcessRoute:View')) or (p_kind='equipment' and app_private.has_permission('MdmWorkCenter:View'))) then raise exception '没有查看生产参选数据权限' using errcode='42501';end if;
 if p_from<0 or p_to<p_from or p_to-p_from>999 then raise exception '分页范围无效';end if;
 if p_kind='material' then
 with source as(select id,material_code,material_name,specification_model from public.mdm_material where app_private.tenant_in_current_read_scope(tenant_id) and (material_code ilike '%'||term||'%' or material_name ilike '%'||term||'%')), page as(select * from source order by material_code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 else
 with source as(select id,equipment_code,equipment_name from public.mdm_equipment where app_private.tenant_in_current_read_scope(tenant_id) and (equipment_code ilike '%'||term||'%' or equipment_name ilike '%'||term||'%')), page as(select * from source order by equipment_code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 end if;return result;
end $$;


ALTER FUNCTION "app_private"."mdm_production_reference_options"("p_kind" "text", "p_keyword" "text", "p_from" integer, "p_to" integer) OWNER TO "postgres";

--

--
-- Name: mdm_project_assign_code(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_project_assign_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_period text;
  v_next integer;
begin
  if tg_op = 'UPDATE' then
    if new.project_code is distinct from old.project_code then
      raise exception '项目编号由系统统一生成，不允许修改' using errcode = '22023';
    end if;
    return new;
  end if;

  v_period := pg_catalog.to_char(
    pg_catalog.clock_timestamp() at time zone 'Asia/Shanghai',
    'YYYYMM'
  );

  insert into app_private.mdm_project_month_sequence as sequence_row (
    tenant_id,
    month_key,
    current_value
  )
  values (new.tenant_id, v_period, 1)
  on conflict (tenant_id, month_key)
  do update set current_value = sequence_row.current_value + 1
  returning current_value into v_next;

  if v_next > 999 then
    raise exception '本月项目编号已达到 999 个上限，请联系管理员'
      using errcode = '22003';
  end if;

  new.project_code := 'PJ' || v_period || pg_catalog.lpad(v_next::text, 3, '0');
  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_project_assign_code"() OWNER TO "postgres";

--

--
-- Name: mdm_quality_issue_state_audit(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_quality_issue_state_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action text;
  v_comment text;
  v_actor_user_id uuid;
  v_actor_email text;
begin
  if tg_op = 'UPDATE' and new.state is not distinct from old.state then
    return new;
  end if;

  v_action := coalesce(
    nullif(current_setting('app.mdm_issue_action', true), ''),
    case when tg_op = 'INSERT' then 'detected' else 'system_reassessment' end
  );
  v_comment := nullif(current_setting('app.mdm_issue_comment', true), '');

  begin
    v_actor_user_id := app_private.mdm_current_actor_user_id();
    v_actor_email := app_private.mdm_current_actor_email();
  exception when sqlstate '42501' then
    v_actor_user_id := null;
    v_actor_email := 'system';
  end;

  insert into public.mdm_quality_issue_event (
    tenant_id,
    issue_id,
    from_state,
    to_state,
    action,
    actor_user_id,
    actor_email,
    comment,
    event_data
  ) values (
    new.tenant_id,
    new.id,
    case when tg_op = 'UPDATE' then old.state else null end,
    new.state,
    v_action,
    v_actor_user_id,
    v_actor_email,
    v_comment,
    jsonb_build_object(
      'observedStatus', new.observed_status,
      'severity', new.severity,
      'detectionCount', new.detection_count
    )
  );

  perform app_private.mdm_emit_outbox_event(
    new.tenant_id,
    'quality_issue',
    new.id,
    'mdm.quality-issue.' || replace(new.state, '_', '-'),
    jsonb_build_object(
      'issueId', new.id,
      'ruleId', new.rule_id,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'state', new.state,
      'observedStatus', new.observed_status,
      'dueAt', new.due_at
    )
  );

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_quality_issue_state_audit"() OWNER TO "postgres";

--

--
-- Name: mdm_reference_tenant("text", "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_reference_tenant"("p_kind" "text", "p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result uuid; tenant uuid:=app_private.current_user_tenant_id();
begin
 if auth.uid() is null then return null;end if;
 if p_kind='material' and app_private.has_permission('MdmProcessRoute:View') then select tenant_id into result from public.mdm_material where id=p_id and app_private.tenant_in_current_read_scope(tenant_id);
 elsif p_kind='equipment' and app_private.has_permission('MdmWorkCenter:View') then select tenant_id into result from public.mdm_equipment where id=p_id and app_private.tenant_in_current_read_scope(tenant_id);end if;
 return result;
end $$;


ALTER FUNCTION "app_private"."mdm_reference_tenant"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_refresh_process_route_path("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_refresh_process_route_path"("p_route_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with next_path as (
    select coalesce(
      string_agg(
        coalesce(nullif(btrim(step.name), ''), step.code),
        '→'
        order by step.sort, step.code, step.id
      ),
      ''
    ) as value
    from public.mdm_process_route_step step
    where step.route_id = p_route_id
  )
  update public.mdm_process_route route
  set path = next_path.value
  from next_path
  where route.id = p_route_id
    and route.path is distinct from next_path.value
$$;


ALTER FUNCTION "app_private"."mdm_refresh_process_route_path"("p_route_id" "uuid") OWNER TO "postgres";

