CREATE OR REPLACE FUNCTION "app_private"."mdm_require_esop_write"("p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception '请先登录后再维护 ESOP' using errcode = '42501';
  end if;

  if not app_private.has_permission(p_permission) then
    raise exception '当前账号没有此 ESOP 操作权限' using errcode = '42501';
  end if;
end;
$$;


