--
-- Name: mdm_shift_schedule_range("date", "date"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_shift_schedule_range"("p_start" "date", "p_end" "date") RETURNS "daterange"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$ select daterange(p_start,coalesce(p_end,'infinity'::date),'[]') $$;


ALTER FUNCTION "app_private"."mdm_shift_schedule_range"("p_start" "date", "p_end" "date") OWNER TO "postgres";

--

--
-- Name: mdm_sync_material_category_code_prefix(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_sync_material_category_code_prefix"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$
begin
 if nullif(btrim(new.code_prefix),'') is null then new.code_prefix:=btrim(new.category_code);
 elsif tg_op='UPDATE' and btrim(old.code_prefix)=btrim(old.category_code)
   and new.code_prefix is not distinct from old.code_prefix
   and new.category_code is distinct from old.category_code then new.code_prefix:=btrim(new.category_code);
 else new.code_prefix:=btrim(new.code_prefix); end if;
 return new;
end; $$;


ALTER FUNCTION "app_private"."mdm_sync_material_category_code_prefix"() OWNER TO "postgres";

--

--
-- Name: mdm_sync_process_route_path(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_sync_process_route_path"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    perform app_private.mdm_refresh_process_route_path(old.route_id);
  elsif tg_op = 'UPDATE' and new.route_id is distinct from old.route_id then
    perform app_private.mdm_refresh_process_route_path(old.route_id);
    perform app_private.mdm_refresh_process_route_path(new.route_id);
  else
    perform app_private.mdm_refresh_process_route_path(new.route_id);
  end if;
  return null;
end
$$;


ALTER FUNCTION "app_private"."mdm_sync_process_route_path"() OWNER TO "postgres";

--

--
-- Name: mdm_sync_process_step_work_centers(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_sync_process_step_work_centers"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_normalized uuid[];
begin
  if cardinality(coalesce(new.work_center_ids, '{}'::uuid[])) = 0
     and new.work_center_id is not null then
    new.work_center_ids := array[new.work_center_id];
  end if;

  select coalesce(array_agg(item_id order by first_ordinal), '{}'::uuid[])
  into v_normalized
  from (
    select item_id, min(ordinality) as first_ordinal
    from unnest(coalesce(new.work_center_ids, '{}'::uuid[]))
      with ordinality as selected(item_id, ordinality)
    group by item_id
  ) deduplicated;

  new.work_center_ids := v_normalized;
  new.work_center_id := new.work_center_ids[1];

  if exists (
    select 1
    from unnest(new.work_center_ids) selected(item_id)
    left join public.mdm_work_center center on center.id = selected.item_id
    where center.id is null or center.tenant_id <> new.tenant_id
  ) then
    raise exception '工作中心不存在或不属于当前租户' using errcode = '23503';
  end if;

  if new.department_id is not null and exists (
    select 1
    from unnest(new.work_center_ids) selected(item_id)
    join public.mdm_work_center center on center.id = selected.item_id
    where center.department_id <> new.department_id
  ) then
    raise exception '工作中心必须属于所选车间' using errcode = '23514';
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."mdm_sync_process_step_work_centers"() OWNER TO "postgres";

--

--
-- Name: mdm_update_accessory_processing_item_internal("uuid", "jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_update_accessory_processing_item_internal"("p_item_id" "uuid", "p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_list public.mdm_accessory_processing_list%rowtype;
  v_type uuid := nullif(p_payload->>'materialTypeId','')::uuid;
  v_unit uuid := nullif(p_payload->>'baseUnitId','')::uuid;
  v_category uuid := nullif(p_payload->>'categoryId','')::uuid;
  v_rule uuid := nullif(p_payload->>'codeRuleId','')::uuid;
  v_source text := p_payload->>'materialSource';
  v_sketch text := nullif(p_payload->>'sketchPath','');
  v_images jsonb := coalesce(p_payload->'imageUrls','[]'::jsonb);
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:Edit') then
    raise exception '当前账号没有编辑加工件的权限' using errcode='42501';
  end if;
  if jsonb_typeof(p_payload)<>'object' then
    raise exception '加工件内容无效' using errcode='22023';
  end if;
  select * into v_item from public.mdm_accessory_processing_item
  where id=p_item_id for update;
  if not found or not app_private.tenant_in_current_read_scope(v_item.tenant_id) then
    raise exception '加工件不存在或不在当前租户范围内' using errcode='42501';
  end if;
  select * into v_list from public.mdm_accessory_processing_list
  where id=v_item.list_id for update;
  if v_item.material_id is not null or exists(select 1 from public.mes_work_order
    where accessory_item_id=v_item.id and deleted_at is null) then
    raise exception '已生成物料或工单的加工件不可编辑' using errcode='22023';
  end if;
  if not exists(select 1 from public.mdm_material_type
    where id=v_type and tenant_id=v_item.tenant_id and status='enabled')
    or not exists(select 1 from public.mdm_unit_of_measure
    where id=v_unit and tenant_id=v_item.tenant_id and status='enabled')
    or not exists(select 1 from public.mdm_material_category
    where id=v_category and tenant_id=v_item.tenant_id and status='enabled')
    or (v_rule is not null and not exists(select 1 from public.mdm_material_code_rule
      where id=v_rule and tenant_id=v_item.tenant_id and status='enabled'))
    or v_source not in ('purchase','self_made','outsourcing') then
    raise exception '物料属性已失效，请重新选择' using errcode='22023';
  end if;
  if v_sketch is not null and (
    split_part(v_sketch,'/',1) <> v_item.tenant_id::text
    or split_part(v_sketch,'/',3) <> 'sketch'
    or (v_list.source_path is not null and split_part(v_sketch,'/',2) <>
      split_part(v_list.source_path,'/',2))
    or not exists(select 1 from storage.objects
      where bucket_id='mdm-accessory-processing' and name=v_sketch)
  ) then raise exception '加工草图无效' using errcode='22023'; end if;
  if jsonb_typeof(v_images)<>'array' then
    raise exception '加工件图片无效' using errcode='22023';
  end if;
  if jsonb_array_length(v_images)>5
     or exists(select 1 from jsonb_array_elements(v_images) as image(value)
       where jsonb_typeof(image.value)<>'string' or length(image.value #>> '{}')>2048
         or image.value #>> '{}' !~ '^https://') then
    raise exception '加工件图片无效' using errcode='22023';
  end if;
  update public.mdm_accessory_processing_item set
    row_no=(p_payload->>'rowNo')::integer,
    name=left(btrim(p_payload->>'name'),160),
    width_mm=nullif(p_payload->>'widthMm','')::numeric,
    length_m=(p_payload->>'lengthM')::numeric,
    quantity=(p_payload->>'quantity')::integer,
    material_color=left(coalesce(p_payload->>'materialColor',''),160),
    remark=left(coalesce(p_payload->>'remark',''),500),
    specification_model=left(coalesce(nullif(btrim(p_payload->>'specificationModel'),''),
      '展宽 '||coalesce(p_payload->>'widthMm','—')||' mm × 长度 '||
      (p_payload->>'lengthM')||' m'),120),
    base_unit_id=v_unit,material_type_id=v_type,material_source=v_source,
    category_id=v_category,code_rule_id=v_rule,sketch_path=v_sketch,image_urls=v_images
  where id=p_item_id;
end
$$;


ALTER FUNCTION "app_private"."mdm_update_accessory_processing_item_internal"("p_item_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_work_center_activities("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_work_center_activities"("p_center_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 if auth.uid() is null or not(app_private.has_permission('MdmWorkCenter:View') or app_private.has_permission('MdmWorkCenter:Edit')) then raise exception '没有查看工作中心活动权限' using errcode='42501';end if;
 if not exists(select 1 from public.mdm_work_center c where c.id=p_center_id and app_private.tenant_in_current_read_scope(c.tenant_id)) then raise exception '工作中心不存在或不在当前工作范围内';end if;
 select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('plan_formula',case when pf.id is null then null else jsonb_build_object('id',pf.id,'code',pf.code,'name',pf.name,'expression',pf.plan_expression) end,'report_formula',case when rf.id is null then null else jsonb_build_object('id',rf.id,'code',rf.code,'name',rf.name,'expression',rf.report_expression) end) order by a.sort,a.id),'[]'::jsonb) into result
 from public.mdm_work_center_activity a left join public.mdm_activity_formula pf on pf.id=a.plan_formula_id and pf.tenant_id=a.tenant_id left join public.mdm_activity_formula rf on rf.id=a.report_formula_id and rf.tenant_id=a.tenant_id where a.work_center_id=p_center_id;
 return result;
end$$;


ALTER FUNCTION "app_private"."mdm_work_center_activities"("p_center_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_work_center_reference_options("text", "uuid", "text", integer, integer, "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_work_center_reference_options"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT ''::"text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 9, "p_center_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  target_tenant uuid;
  term text := coalesce(p_keyword, '');
begin
  if auth.uid() is null
    or not (
      app_private.has_permission('MdmWorkCenter:View')
      or app_private.has_permission('MdmWorkCenter:Add')
      or app_private.has_permission('MdmWorkCenter:Edit')
      or app_private.has_permission('MdmWorkCenter:Copy')
      or app_private.has_permission('MdmWorkCenter:Devices')
    )
  then
    raise exception '没有查看工作中心参选数据权限' using errcode = '42501';
  end if;

  if p_from < 0 or p_to < p_from or p_to - p_from > 999 then
    raise exception '分页范围无效';
  end if;

  if p_center_id is not null then
    select c.tenant_id
      into target_tenant
      from public.mdm_work_center c
     where c.id = p_center_id
       and app_private.tenant_in_current_read_scope(c.tenant_id);
  end if;

  if target_tenant is null then
    target_tenant := case
      when app_private.is_platform_super() then p_tenant_id
      else app_private.current_user_tenant_id()
    end;
  end if;

  if target_tenant is null then
    raise exception '请先选择所属租户';
  end if;

  if not app_private.tenant_in_current_read_scope(target_tenant) then
    raise exception '所选租户不在当前工作范围内' using errcode = '42501';
  end if;

  if p_kind = 'control_code' then
    with source as (
      select i.id, i.control_code as code, i.control_code_name as name
        from public.mdm_operation_control_code i
       where i.tenant_id = target_tenant
         and i.enabled
         and (
           i.control_code ilike '%' || term || '%'
           or i.control_code_name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  elsif p_kind = 'activity_formula' then
    with source as (
      select i.id, i.code, i.name, i.activity_type, i.plan_expression, i.report_expression
        from public.mdm_activity_formula i
       where i.tenant_id = target_tenant
         and i.enabled
         and (
           i.code ilike '%' || term || '%'
           or i.name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  elsif p_kind = 'equipment' then
    with source as (
      select i.id, i.equipment_code as code, i.equipment_name as name
        from public.mdm_equipment i
       where i.tenant_id = target_tenant
         and i.status = 'enabled'
         and not exists (
           select 1 from public.mdm_work_center_device b where b.equipment_id = i.id
         )
         and (
           i.equipment_code ilike '%' || term || '%'
           or i.equipment_name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  else
    raise exception '未知工作中心参选类型';
  end if;

  return result;
end
$$;


ALTER FUNCTION "app_private"."mdm_work_center_reference_options"("p_kind" "text", "p_tenant_id" "uuid", "p_keyword" "text", "p_from" integer, "p_to" integer, "p_center_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mes_build_work_order_bom_snapshot("uuid", "uuid", numeric, "uuid", "date"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_build_work_order_bom_snapshot"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_order_quantity" numeric, "p_route_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with recursive root_bom as (
    select b.*
    from public.mdm_bom b
    where b.tenant_id=p_tenant_id and b.material_id=p_material_id
      and (b.project_id is null or b.status='effective')
      and (b.effective_from is null or b.effective_from<=coalesce(p_as_of,current_date))
      and (b.effective_to is null or b.effective_to>=coalesce(p_as_of,current_date))
    order by (b.process_route_id = p_route_id) desc nulls last, b.update_time desc
    limit 1
  ),
  exploded(
    item_id,component_material_id,sequence_no,source_quantity,basic_quantity,
    unit_id,position_no,operation_name,source_path,material_path,depth,
    expand_bom_id,virtual_unexpanded
  ) as (
    select
      item.id,item.component_material_id,item.sequence_no,item.quantity,
      item.quantity/nullif(root.base_quantity,0),item.unit_id,item.position_no,
      item.operation_name,array[component.material_code]::text[],
      array[p_material_id,item.component_material_id]::uuid[],1,child_bom.id,
      component.special_purchase_type='virtual_part' and child_bom.id is null
    from root_bom root
    join public.mdm_bom_item item
      on item.bom_id=root.id and item.tenant_id=root.tenant_id
    join public.mdm_material component
      on component.id=item.component_material_id and component.tenant_id=item.tenant_id
    left join lateral (
      select child.id
      from public.mdm_bom child
      where child.tenant_id=item.tenant_id
        and child.material_id=item.component_material_id
        and (child.project_id is null or child.status='effective')
        and component.special_purchase_type='virtual_part'
        and (child.effective_from is null or child.effective_from<=coalesce(p_as_of,current_date))
        and (child.effective_to is null or child.effective_to>=coalesce(p_as_of,current_date))
      order by child.update_time desc limit 1
    ) child_bom on true
    union all
    select
      item.id,item.component_material_id,item.sequence_no,item.quantity,
      parent.basic_quantity*item.quantity/nullif(child_root.base_quantity,0),
      item.unit_id,item.position_no,
      coalesce(nullif(btrim(item.operation_name),''),parent.operation_name),
      parent.source_path||component.material_code,
      parent.material_path||item.component_material_id,parent.depth+1,next_bom.id,
      component.special_purchase_type='virtual_part' and next_bom.id is null
    from exploded parent
    join public.mdm_bom child_root
      on child_root.id=parent.expand_bom_id and child_root.tenant_id=p_tenant_id
    join public.mdm_bom_item item
      on item.bom_id=child_root.id and item.tenant_id=child_root.tenant_id
    join public.mdm_material component
      on component.id=item.component_material_id and component.tenant_id=item.tenant_id
    left join lateral (
      select child.id
      from public.mdm_bom child
      where child.tenant_id=item.tenant_id
        and child.material_id=item.component_material_id
        and (child.project_id is null or child.status='effective')
        and component.special_purchase_type='virtual_part'
        and (child.effective_from is null or child.effective_from<=coalesce(p_as_of,current_date))
        and (child.effective_to is null or child.effective_to>=coalesce(p_as_of,current_date))
      order by child.update_time desc limit 1
    ) next_bom on true
    where parent.depth<20 and not item.component_material_id=any(parent.material_path)
  ),
  leaf_items as (
    select * from exploded where expand_bom_id is null
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',root.id,'bom_code',root.bom_code,'version',root.version,
    'status',root.status,'base_quantity',root.base_quantity,
    'items',coalesce((
      select jsonb_agg(to_jsonb(source_item) || jsonb_build_object(
        'id',leaf.item_id::text||':'||array_to_string(leaf.material_path,'/'),
        'source_item_id',leaf.item_id,
        'component_material_id',leaf.component_material_id,
        'component_material_code',component.material_code,
        'component_material_name',component.material_name,
        'component_specification',coalesce(component.specification_model,''),
        'sequence_no',leaf.sequence_no,'quantity',leaf.basic_quantity,
        'source_quantity',leaf.source_quantity,'basic_quantity',leaf.basic_quantity,
        'required_quantity',coalesce(p_order_quantity,0)*leaf.basic_quantity,
        'unit_id',leaf.unit_id,'unit_name',coalesce(unit.unit_name,unit.symbol,''),
        'position_no',leaf.position_no,'operation_name',leaf.operation_name,
        'source_path',to_jsonb(leaf.source_path),
        'virtual_unexpanded',leaf.virtual_unexpanded,
        'assigned_route_step_id',coalesce(matched.id,first_step.id),
        'assigned_operation_code',coalesce(matched.code,first_step.code),
        'assigned_operation_name',coalesce(matched.name,first_step.name),
        'assignment_source',case
          when matched.id is not null then 'configured'
          when first_step.id is not null then 'first_operation'
          else 'unassigned' end
      ) order by array_to_string(leaf.source_path,'/'),leaf.sequence_no,leaf.item_id)
      from leaf_items leaf
      join public.mdm_bom_item source_item
        on source_item.id=leaf.item_id and source_item.tenant_id=p_tenant_id
      join public.mdm_material component
        on component.id=leaf.component_material_id and component.tenant_id=p_tenant_id
      left join public.mdm_unit_of_measure unit
        on unit.id=leaf.unit_id and unit.tenant_id=p_tenant_id
      left join lateral (
        select step.id,step.code,step.name
        from public.mdm_process_route_step step
        where step.route_id=p_route_id and nullif(btrim(leaf.operation_name),'') is not null
          and lower(btrim(leaf.operation_name)) in (lower(btrim(step.code)),lower(btrim(step.name)))
        order by step.sort,step.code limit 1
      ) matched on true
      left join lateral (
        select step.id,step.code,step.name
        from public.mdm_process_route_step step
        where step.route_id=p_route_id
        order by step.sort,step.code limit 1
      ) first_step on true
    ),'[]'::jsonb)
  )),'[]'::jsonb)
  from root_bom root
$$;


ALTER FUNCTION "app_private"."mes_build_work_order_bom_snapshot"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_order_quantity" numeric, "p_route_id" "uuid", "p_as_of" "date") OWNER TO "postgres";

--

--
-- Name: mes_build_work_order_route_snapshot("uuid", "uuid", "date"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_build_work_order_route_snapshot"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select jsonb_build_object(
      'id',r.id,'code',r.code,'name',r.name,'version',r.version,
      'route_type',r.route_type,'allocation_mode',r.allocation_mode,
      'batch_from',r.batch_from,'batch_to',r.batch_to,
      'production_unit_id',r.production_unit_id,'department_id',r.department_id,
      'effective_date',r.effective_date,'expiry_date',r.expiry_date,
      'is_default',r.is_default,'source',r.source,'remark',r.remark,
      'steps',coalesce((
        select jsonb_agg(
          to_jsonb(s) || jsonb_build_object(
            'sequence_no',coalesce(seq.sequence_no,1),
            'sequence_type',coalesce(seq.sequence_type,'main'),
            'sequence_remark',coalesce(seq.remark,''),
            'operation_code',coalesce(operation.code,''),
            'operation_name',coalesce(operation.name,''),
            'department_name',coalesce(department.name,''),
            'unit_name',coalesce(unit.unit_name,unit.symbol,''),
            'work_center_names',coalesce(centers.names,'[]'::jsonb),
            'control_code',coalesce(control_code.control_code,''),
            'control_code_name',coalesce(control_code.control_code_name,'')
          ) order by coalesce(seq.sequence_no,1),s.sort,s.code
        )
        from public.mdm_process_route_step s
        left join public.mdm_process_route_sequence seq
          on seq.id=s.sequence_id and seq.tenant_id=s.tenant_id
        left join public.mdm_operation operation
          on operation.id=s.operation_id and operation.tenant_id=s.tenant_id
        left join public.mdm_production_department department
          on department.id=s.department_id and department.tenant_id=s.tenant_id
        left join public.mdm_unit_of_measure unit
          on unit.id=s.unit_id and unit.tenant_id=s.tenant_id
        left join public.mdm_operation_control_code control_code
          on control_code.id=s.control_code_id and control_code.tenant_id=s.tenant_id
        left join lateral (
          select jsonb_agg(center.name order by array_position(s.work_center_ids,center.id)) as names
          from public.mdm_work_center center
          where center.tenant_id=s.tenant_id and center.id=any(s.work_center_ids)
        ) centers on true
        where s.route_id=r.id
      ),'[]'::jsonb)
    )
    from public.mdm_process_route r
    where r.tenant_id=p_tenant_id and r.material_id=p_material_id and r.enabled
      and r.effective_date<=coalesce(p_as_of,current_date)
      and r.expiry_date>=coalesce(p_as_of,current_date)
    order by r.is_default desc,r.update_time desc limit 1
  ),'{}'::jsonb)
$$;


ALTER FUNCTION "app_private"."mes_build_work_order_route_snapshot"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_as_of" "date") OWNER TO "postgres";

--

--
-- Name: mes_financial_close_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_financial_close_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
 if current_user <> 'postgres' and (
   (tg_op='INSERT' and new.financially_closed_at is not null)
   or (tg_op='UPDATE' and new.financially_closed_at is distinct from old.financially_closed_at)
 ) then
  raise exception '财务关闭必须通过受控业务操作变更' using errcode='42501';
 end if;
 return new;
end
$$;


ALTER FUNCTION "app_private"."mes_financial_close_guard"() OWNER TO "postgres";

--

--
-- Name: mes_planning_defaults_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_planning_defaults_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_material public.mdm_material%rowtype; v_rule public.mes_scheduling_rule%rowtype; v_rule_found boolean:=false;
begin
  select * into v_material from public.mdm_material where id=new.material_id and tenant_id=new.tenant_id;
  if found and (tg_op='INSERT' or new.material_id is distinct from old.material_id) then
    new.scheduling_priority:=v_material.scheduling_priority;
    new.planning_time_fence_days_snapshot:=v_material.planning_time_fence_days;
    new.batch_rounding_quantity_snapshot:=v_material.batch_rounding_quantity;
  end if;
  if new.scheduling_rule_id is null then
    select * into v_rule from public.mes_scheduling_rule where tenant_id=new.tenant_id and enabled order by is_default desc,update_time desc limit 1;
  else
    select * into v_rule from public.mes_scheduling_rule where id=new.scheduling_rule_id and tenant_id=new.tenant_id and enabled;
    if not found then raise exception '排产规则不存在、已停用或不属于当前租户'; end if;
  end if;
  v_rule_found:=found;
  if v_rule_found then new.scheduling_rule_id:=v_rule.id; end if;
  new.scheduling_strategy_snapshot:=case
    when v_rule_found and coalesce(v_material.scheduling_strategy,'inherit')='inherit' then v_rule.direction
    else coalesce(nullif(v_material.scheduling_strategy,'inherit'),new.scheduling_strategy_snapshot,'forward')
  end;
  return new;
end $$;


ALTER FUNCTION "app_private"."mes_planning_defaults_guard"() OWNER TO "postgres";

--

--
-- Name: mes_protect_lifecycle_fields(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_protect_lifecycle_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
begin
  if current_user <> 'postgres' then
    if tg_table_name = 'mes_work_order' then
      if old.packing_published_at is not null then
        raise exception '排包单已发布，请先重排包';
      end if;
      if old.status not in ('pending', 'abnormal') then
        raise exception '已确认或已结案工单不可直接修改';
      end if;

      if new.status is distinct from old.status
        or new.status_reason is distinct from old.status_reason
        or new.confirmed_at is distinct from old.confirmed_at
        or new.closed_at is distinct from old.closed_at
        or new.deleted_at is distinct from old.deleted_at
        or new.deleted_by is distinct from old.deleted_by
        or new.packing_rule_id is distinct from old.packing_rule_id
        or new.packing_enabled_snapshot is distinct from old.packing_enabled_snapshot
        or new.packing_thickness_field_key_snapshot is distinct from old.packing_thickness_field_key_snapshot
        or new.packing_published_at is distinct from old.packing_published_at
        or new.packing_published_by is distinct from old.packing_published_by
      then
        raise exception '工单状态必须通过受控业务操作变更';
      end if;
    elsif tg_table_name = 'mes_operation_task' then
      if new.task_no is distinct from old.task_no
        or new.status is distinct from old.status
        or new.scheduling_status is distinct from old.scheduling_status
        or new.operation_status is distinct from old.operation_status
        or new.scheduled_quantity is distinct from old.scheduled_quantity
        or new.completed_quantity is distinct from old.completed_quantity
        or new.cumulative_completed_quantity is distinct from old.cumulative_completed_quantity
        or new.qualified_quantity is distinct from old.qualified_quantity
        or new.cumulative_qualified_quantity is distinct from old.cumulative_qualified_quantity
        or new.unqualified_quantity is distinct from old.unqualified_quantity
        or new.cumulative_unqualified_quantity is distinct from old.cumulative_unqualified_quantity
        or new.scrap_quantity is distinct from old.scrap_quantity
        or new.cumulative_scrap_quantity is distinct from old.cumulative_scrap_quantity
        or new.pending_rework_quantity is distinct from old.pending_rework_quantity
        or new.pending_inspection_quantity is distinct from old.pending_inspection_quantity
        or new.closed_at is distinct from old.closed_at
        or new.deleted_at is distinct from old.deleted_at
        or new.deleted_by is distinct from old.deleted_by
        or new.work_center_id is distinct from old.work_center_id
        or new.required_completion_date is distinct from old.required_completion_date
        or new.urgency is distinct from old.urgency
        or new.annotation is distinct from old.annotation
      then
        raise exception '工序任务状态、排程、批注和执行数量必须通过受控业务操作变更';
      end if;
    end if;
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."mes_protect_lifecycle_fields"() OWNER TO "postgres";

--

--
-- Name: mes_snapshot_write_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_snapshot_write_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres'
    and coalesce(current_setting('app.mes_explicit_snapshot_edit',true),'') <> 'on'
    and coalesce(current_setting('app.mes_explicit_snapshot_reload',true),'') <> 'on' then
    if new.route_snapshot is distinct from old.route_snapshot
      and new.material_id is not distinct from old.material_id then
      raise exception '工单工艺路线必须通过受控业务操作修改' using errcode='42501';
    end if;
    if new.bom_snapshot is distinct from old.bom_snapshot
      and new.material_id is not distinct from old.material_id
      and new.order_quantity is not distinct from old.order_quantity then
      raise exception '工单 BOM 必须通过受控业务操作修改' using errcode='42501';
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."mes_snapshot_write_guard"() OWNER TO "postgres";

--

--
-- Name: mes_work_order_extension_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_work_order_extension_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fields jsonb:='[]'::jsonb; v_field jsonb; v_key text; v_value jsonb; v_require_enabled boolean;
begin
 if new.work_order_type_id is not null then
   v_require_enabled:=tg_op='INSERT';
   if tg_op='UPDATE' then v_require_enabled:=new.work_order_type_id is distinct from old.work_order_type_id; end if;
   select d.extension_fields into v_fields from public.mdm_document_type d
   where d.id=new.work_order_type_id and d.tenant_id=new.tenant_id
     and (not v_require_enabled or d.enabled);
   if not found then raise exception '工单类型无效或已禁用' using errcode='23514'; end if;
 end if;
 new.extension_schema_snapshot:=v_fields;
 if jsonb_typeof(new.extension_values)<>'object' then raise exception '工单扩展字段值格式无效' using errcode='23514'; end if;
 if (select count(*) from jsonb_object_keys(new.extension_values))>30 then raise exception '工单扩展字段值过多' using errcode='23514'; end if;
 for v_key,v_value in select key,value from jsonb_each(new.extension_values) loop
   select value into v_field from jsonb_array_elements(v_fields) where value->>'key'=v_key;
   if not found then raise exception '工单扩展字段未配置: %',v_key using errcode='23514'; end if;
   if v_value<>'null'::jsonb then
     if v_field->>'valueType'='number' and jsonb_typeof(v_value)<>'number' then raise exception '工单数字字段类型无效: %',v_key using errcode='23514'; end if;
     if v_field->>'valueType' in ('text','material') and jsonb_typeof(v_value)<>'string' then raise exception '工单文本字段类型无效: %',v_key using errcode='23514'; end if;
     if v_field->>'valueType'='material' and length(v_value #>> '{}')>0 and not exists(select 1 from public.mdm_material m where m.id=(v_value #>> '{}')::uuid and m.tenant_id=new.tenant_id) then raise exception '工单扩展字段物料不属于当前租户' using errcode='23503'; end if;
   end if;
 end loop;
 return new;
end $$;


ALTER FUNCTION "app_private"."mes_work_order_extension_guard"() OWNER TO "postgres";

--

--
-- Name: mes_work_order_packing_config_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_work_order_packing_config_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_enabled boolean; v_key text;
begin
  if tg_op='UPDATE' and new.work_order_type_id is not distinct from old.work_order_type_id then
    new.packing_enabled_snapshot:=old.packing_enabled_snapshot;
    new.packing_thickness_field_key_snapshot:=old.packing_thickness_field_key_snapshot;
    return new;
  end if;
  select d.packing_enabled,d.packing_thickness_field_key into v_enabled,v_key
  from public.mdm_document_type d
  where d.id=new.work_order_type_id and d.tenant_id=new.tenant_id;
  new.packing_rule_id:=null;
  new.packing_enabled_snapshot:=coalesce(v_enabled,false);
  new.packing_thickness_field_key_snapshot:=case when v_enabled then v_key else null end;
  return new;
end $$;


ALTER FUNCTION "app_private"."mes_work_order_packing_config_guard"() OWNER TO "postgres";

