--
-- Name: mes_work_order_progress_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mes_work_order_progress_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres'
    and (new.completed_quantity is distinct from old.completed_quantity
      or new.warehoused_quantity is distinct from old.warehoused_quantity) then
    raise exception '工单报工与交货数量只能通过业务操作更新' using errcode='42501';
  end if;
  return new;
end
$$;


