CREATE OR REPLACE FUNCTION "app_private"."tms_carrier_option_to_secure_json"("p_carrier" "public"."mdm_carrier") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
