--

--
-- Name: tms_recompute_source_order("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."tms_recompute_source_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.tms_order%rowtype;
 v_count integer; v_qty numeric; v_weight numeric; v_volume numeric;
 v_any_receipt boolean; v_all_receipted boolean; v_all_completed boolean;
 v_any_transit boolean; v_any_pickup boolean; v_full boolean;
 v_dispatch text; v_status text;
begin
 select * into o from public.tms_order where id=p_order_id for update;
 if not found or o.order_status='cancelled' then return; end if;
 select count(*),coalesce(sum(a.quantity),0),coalesce(sum(a.weight_kg),0),coalesce(sum(a.volume_m3),0),
   coalesce(bool_or(a.receipt_recorded_at is not null),false),
   coalesce(bool_and(w.status in ('signed','completed') and a.receipt_recorded_at is not null and a.signed_quantity>=a.quantity-0.000001 and a.exception_quantity=0),false),
   coalesce(bool_and(w.status='completed'),false),
   coalesce(bool_or(w.status in ('transporting','unloading')),false),
   coalesce(bool_or(w.status in ('accepted','loading')),false)
 into v_count,v_qty,v_weight,v_volume,v_any_receipt,v_all_receipted,v_all_completed,v_any_transit,v_any_pickup
 from public.tms_waybill_order_allocation a join public.tms_waybill w on w.id=a.waybill_id and w.tenant_id=a.tenant_id
 where a.order_id=o.id and a.tenant_id=o.tenant_id and w.status<>'cancelled';
 v_full := v_count>0
   and v_qty >= (select coalesce(sum(coalesce((item.value->>'quantity')::numeric,0)),0)-0.000001 from jsonb_array_elements(o.cargo_items) item)
   and v_weight >= (select coalesce(sum(coalesce((item.value->>'weight_kg')::numeric,0)),0)-0.000001 from jsonb_array_elements(o.cargo_items) item)
   and v_volume >= (select coalesce(sum(coalesce((item.value->>'volume_m3')::numeric,0)),0)-0.000001 from jsonb_array_elements(o.cargo_items) item);
 v_dispatch := case when v_count=0 then 'pending' when v_full then 'loaded' else 'partial' end;
 v_status := case
   when v_count=0 then 'pending_load'
   when v_full and v_all_receipted and v_all_completed then 'completed'
   when v_full and v_all_receipted then 'signed'
   when v_any_receipt then 'partially_signed'
   when not v_full then 'partially_dispatched'
   when v_any_transit then 'transporting'
   when v_any_pickup then 'pending_pickup'
   else 'pending_order'
 end;
 update public.tms_order set dispatch_status=v_dispatch,order_status=v_status,
   signed_at=case when v_full and v_all_receipted then
     (select max(a.receipt_recorded_at) from public.tms_waybill_order_allocation a join public.tms_waybill w on w.id=a.waybill_id where a.order_id=o.id and w.status<>'cancelled')
     else null end
 where id=o.id and (dispatch_status,order_status,signed_at) is distinct from (v_dispatch,v_status,
   case when v_full and v_all_receipted then
     (select max(a.receipt_recorded_at) from public.tms_waybill_order_allocation a join public.tms_waybill w on w.id=a.waybill_id where a.order_id=o.id and w.status<>'cancelled')
     else null end);
end $$;


ALTER FUNCTION "app_private"."tms_recompute_source_order"("p_order_id" "uuid") OWNER TO "postgres";

--

--
-- Name: tms_remaining_cargo_items("public"."tms_order"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."tms_remaining_cargo_items"("p_order" "public"."tms_order") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select coalesce(jsonb_agg(
   item.value || jsonb_build_object(
    'quantity',greatest(0,coalesce((item.value->>'quantity')::numeric,0)-coalesce(used.quantity,0)),
    'weight_kg',greatest(0,coalesce((item.value->>'weight_kg')::numeric,0)-coalesce(used.weight_kg,0)),
    'volume_m3',greatest(0,coalesce((item.value->>'volume_m3')::numeric,0)-coalesce(used.volume_m3,0))
   ) order by item.ordinality
 ),'[]'::jsonb)
 from jsonb_array_elements(p_order.cargo_items) with ordinality item(value,ordinality)
 left join lateral (
   select sum((line.value->>'quantity')::numeric) quantity,
     sum((line.value->>'weight_kg')::numeric) weight_kg,
     sum((line.value->>'volume_m3')::numeric) volume_m3
   from public.tms_waybill_order_allocation a
   join public.tms_waybill w on w.id=a.waybill_id and w.status<>'cancelled'
   cross join lateral jsonb_array_elements(a.cargo_items) line
   where a.order_id=p_order.id and a.tenant_id=p_order.tenant_id
     and (line.value->>'line_index')::integer=item.ordinality-1
 ) used on true
$$;


ALTER FUNCTION "app_private"."tms_remaining_cargo_items"("p_order" "public"."tms_order") OWNER TO "postgres";

--

--
-- Name: tms_valid_url_array("jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."tms_valid_url_array"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_typeof(p_value) = 'array'
    and jsonb_array_length(p_value) between 1 and 9
    and not exists (
      select 1
      from jsonb_array_elements(p_value) item
      where jsonb_typeof(item) <> 'string'
        or nullif(btrim(item #>> '{}'), '') is null
    );
$$;


ALTER FUNCTION "app_private"."tms_valid_url_array"("p_value" "jsonb") OWNER TO "postgres";

