--

--
-- Name: trg_assign_configurable_number(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_assign_configurable_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rule public.sys_document_number_rule;
  v_tenant_id uuid;
  v_current text;
  v_override text;
  v_value text;
begin
  v_tenant_id := coalesce(new.tenant_id, app_private.current_user_tenant_id());
  select * into v_rule
  from public.sys_document_number_rule
  where tenant_id = v_tenant_id and rule_key = tg_argv[0] and enabled;
  if not found then
    raise exception '未找到已启用的编号规则：%', tg_argv[0];
  end if;

  v_current := nullif(btrim(coalesce(to_jsonb(new) ->> tg_argv[1], '')), '');
  v_override := nullif(btrim(current_setting(
    'app.document_number.' || replace(tg_argv[0], '.', '_'), true
  )), '');
  if v_rule.auto_enabled then
    v_value := app_private.next_document_number(tg_argv[0], v_tenant_id);
  else
    v_value := coalesce(v_current, v_override);
    if v_rule.manual_required and v_value is null then
      raise exception '%未启用自动编码，请手工填写', v_rule.rule_name;
    end if;
  end if;
  new := jsonb_populate_record(new, jsonb_build_object(tg_argv[1], v_value));
  return new;
end;
$$;


ALTER FUNCTION "app_private"."trg_assign_configurable_number"() OWNER TO "postgres";

--

--
-- Name: trg_guard_tms_expense_workflow_state(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_guard_tms_expense_workflow_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status_field text;
  v_old_status text;
  v_new_status text;
begin
  v_status_field := case
    when tg_table_name = 'tms_in_transit_expense' then 'report_status'
    else 'status'
  end;
  v_old_status := pg_catalog.to_jsonb(old) ->> v_status_field;
  v_new_status := pg_catalog.to_jsonb(new) ->> v_status_field;

  if v_new_status is distinct from v_old_status
     and (
       v_new_status in ('pending_review', 'approved', 'rejected')
       or v_old_status in ('pending_review', 'approved')
     )
     and coalesce(pg_catalog.current_setting('app.workflow_engine', true), '') <> 'on'
     and coalesce(pg_catalog.current_setting('app.expense_payment_engine', true), '') <> 'on'
  then
    raise exception '费用审批状态必须通过审批中心或出纳支付流程流转';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."trg_guard_tms_expense_workflow_state"() OWNER TO "postgres";

--

--
-- Name: trg_guard_workflow_delegation(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_guard_workflow_delegation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if (new.tenant_id, new.delegator_user_id, new.delegate_user_id, new.starts_at, new.ends_at, new.reason)
       is distinct from
       (old.tenant_id, old.delegator_user_id, old.delegate_user_id, old.starts_at, old.ends_at, old.reason) then
      raise exception '已创建的委托主体、时间和原因不可修改；请撤销后重新创建';
    end if;
    return new;
  end if;

  if not exists (
    select 1
    from public.sys_user delegator
    join public.sys_user delegate_user on delegate_user.id = new.delegate_user_id
    where delegator.id = new.delegator_user_id
      and delegator.tenant_id = new.tenant_id
      and delegator.status = '1'
      and delegate_user.tenant_id = new.tenant_id
      and delegate_user.status = '1'
  ) then
    raise exception '委托人或受托人不存在、已停用或不属于当前租户';
  end if;

  if exists (
    select 1
    from public.wf_delegation delegation
    where delegation.tenant_id = new.tenant_id
      and delegation.revoked_at is null
      and tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(new.starts_at, new.ends_at, '[)')
      and delegation.delegator_user_id = new.delegator_user_id
  ) then
    raise exception '该时间段已存在有效委托，请先调整或撤销原委托';
  end if;

  if exists (
    select 1
    from public.wf_delegation delegation
    where delegation.tenant_id = new.tenant_id
      and delegation.revoked_at is null
      and tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(new.starts_at, new.ends_at, '[)')
      and (
        delegation.delegate_user_id = new.delegator_user_id
        or delegation.delegator_user_id = new.delegate_user_id
      )
  ) then
    raise exception '委托不允许形成转委托或循环委托，请调整时间或人员';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."trg_guard_workflow_delegation"() OWNER TO "postgres";

--

--
-- Name: trg_notify_workflow_action_created(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_notify_workflow_action_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance public.wf_instance;
  v_action_label text;
  v_severity text;
begin
  if new.action not in ('approve', 'reject', 'cancel') then
    return new;
  end if;

  select * into v_instance
  from public.wf_instance i
  where i.id = new.instance_id;

  if not found or new.actor_user_id is null
     or new.actor_user_id = v_instance.initiator_user_id then
    return new;
  end if;

  v_action_label := case new.action
    when 'approve' then '通过了'
    when 'reject' then '驳回了'
    else '终止了'
  end;
  v_severity := case new.action
    when 'approve' then 'success'
    when 'reject' then 'danger'
    else 'warning'
  end;

  perform app_private.enqueue_user_notification(
    v_instance.initiator_user_id,
    v_instance.tenant_id,
    'message',
    new.actor_name_snapshot || v_action_label || '审批节点',
    coalesce(nullif(new.node_name, '') || ' · ', '')
      || v_instance.business_title
      || coalesce('：' || nullif(btrim(coalesce(new.comment, '')), ''), ''),
    v_severity,
    'workflow_action',
    new.id,
    v_instance.business_type,
    v_instance.business_id,
    v_instance.id,
    '/workflow/workbench',
    jsonb_build_object('tab', 'initiated', 'instanceId', v_instance.id)
  );

  return new;
end;
$$;


ALTER FUNCTION "app_private"."trg_notify_workflow_action_created"() OWNER TO "postgres";

--

--
-- Name: trg_notify_workflow_instance_finished(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_notify_workflow_instance_finished"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_title text;
  v_severity text;
begin
  if old.status = new.status or new.status = 'running' then
    return new;
  end if;

  v_title := case new.status
    when 'approved' then '审批已通过：'
    when 'rejected' then '审批已驳回：'
    when 'withdrawn' then '审批已撤回：'
    when 'cancelled' then '审批已取消：'
    else '审批状态已更新：'
  end || new.business_title;
  v_severity := case new.status
    when 'approved' then 'success'
    when 'rejected' then 'danger'
    when 'cancelled' then 'warning'
    else 'info'
  end;

  perform app_private.enqueue_user_notification(
    new.initiator_user_id,
    new.tenant_id,
    'notice',
    v_title,
    coalesce(nullif(btrim(coalesce(new.finish_comment, '')), ''), '流程处理完成，可进入审批工作台查看完整记录。'),
    v_severity,
    'workflow_instance',
    new.id,
    new.business_type,
    new.business_id,
    new.id,
    '/workflow/workbench',
    jsonb_build_object('tab', 'initiated', 'instanceId', new.id)
  );

  return new;
end;
$$;


ALTER FUNCTION "app_private"."trg_notify_workflow_instance_finished"() OWNER TO "postgres";

