--

--
-- Name: withdraw_workflow("uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."withdraw_workflow"("p_instance_id" "uuid", "p_comment" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_instance public.wf_instance;
  v_actor_name text;
begin
  select * into v_instance from public.wf_instance where id=p_instance_id for update;
  if not found or v_instance.initiator_user_id<>v_user_id then raise exception '流程不存在或仅发起人可以撤回'; end if;
  if v_instance.status<>'running' then raise exception '流程已结束，不能撤回'; end if;
  if exists (select 1 from public.wf_task where instance_id=p_instance_id and status in ('approved','rejected')) then
    raise exception '已有审批人处理，不能直接撤回';
  end if;
  select coalesce(nullif(nick_name,''),nullif(user_name,''),user_email,id::text)
  into v_actor_name from public.sys_user where id=v_user_id;
  update public.wf_task set status='cancelled',handled_at=now(),comment='发起人撤回'
  where instance_id=p_instance_id and status='pending';
  update public.wf_instance set status='withdrawn',finished_at=now(),finish_comment=p_comment,
    current_node_key=null,current_node_name=null,row_version=row_version+1 where id=p_instance_id;
  insert into public.wf_action(instance_id,action,actor_user_id,actor_name_snapshot,comment,tenant_id)
  values (p_instance_id,'withdraw',v_user_id,v_actor_name,nullif(btrim(coalesce(p_comment,'')),''),v_instance.tenant_id);
  perform app_private.apply_workflow_business_status(
    v_instance.business_type,v_instance.business_id,'withdrawn',v_actor_name,p_comment
  );
end;
$$;


ALTER FUNCTION "app_private"."withdraw_workflow"("p_instance_id" "uuid", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: wms_allowed_issue_warehouse_types("uuid", "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_allowed_issue_warehouse_types"("p_tenant_id" "uuid", "p_work_order_type_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_allowed text[];
begin
 if p_work_order_type_id is null then return array['raw_material']::text[]; end if;
 select allowed_issue_warehouse_types into v_allowed from public.mdm_document_type
 where id=p_work_order_type_id and tenant_id=p_tenant_id;
 if not found then raise exception '工单类型不属于当前租户' using errcode='23514'; end if;
 return v_allowed;
end $$;


ALTER FUNCTION "app_private"."wms_allowed_issue_warehouse_types"("p_tenant_id" "uuid", "p_work_order_type_id" "uuid") OWNER TO "postgres";

--

--
-- Name: wms_assert_project_section("uuid", "uuid", "text", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_assert_project_section"("p_tenant_id" "uuid", "p_project_id" "uuid", "p_construction_no" "text", "p_allow_closed" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_project public.mdm_project%rowtype; v_section public.mdm_project_construction%rowtype;
begin
 if p_project_id is null and p_construction_no is null then return; end if;
 if p_project_id is null or nullif(btrim(p_construction_no),'') is null then raise exception '项目库存必须同时指定项目和施工号' using errcode='23514'; end if;
 select * into v_project from public.mdm_project where id=p_project_id and tenant_id=p_tenant_id;
 if not found then raise exception '项目不存在或不属于当前租户' using errcode='23514'; end if;
 select * into v_section from public.mdm_project_construction where tenant_id=p_tenant_id and project_id=p_project_id and construction_no=p_construction_no;
 if not found then raise exception '施工号未在该项目登记' using errcode='23514'; end if;
 if not p_allow_closed and (not v_project.enabled or v_project.project_status in ('closed','cancelled') or v_section.status<>'active') then
   raise exception '项目或施工号已关闭，不能新增业务' using errcode='23514'; end if;
end $$;


ALTER FUNCTION "app_private"."wms_assert_project_section"("p_tenant_id" "uuid", "p_project_id" "uuid", "p_construction_no" "text", "p_allow_closed" boolean) OWNER TO "postgres";

--

--
-- Name: wms_guard_work_order_scope(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_guard_work_order_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_required boolean;
begin
  if tg_op = 'UPDATE'
     and new.project_id is not distinct from old.project_id
     and new.construction_no is not distinct from old.construction_no
     and new.work_order_type_id is not distinct from old.work_order_type_id then
    return new;
  end if;
  select coalesce(t.project_required,false) into v_required
  from public.mdm_document_type t
  where t.id=new.work_order_type_id and t.tenant_id=new.tenant_id;
  if coalesce(v_required,false) and new.project_id is null then
    raise exception '工程项目工单必须选择项目' using errcode='23514';
  end if;
  if new.project_id is null then
    if nullif(btrim(coalesce(new.construction_no,'')),'') is not null then
      raise exception '无项目工单不能填写施工号' using errcode='23514';
    end if;
  else
    if nullif(btrim(coalesce(new.construction_no,'')),'') is not null then
      if not exists (select 1 from public.mdm_document_type t
        where t.id=new.work_order_type_id and t.tenant_id=new.tenant_id
          and t.document_type_code='PP40') then
        perform app_private.wms_assert_project_section(new.tenant_id,new.project_id,new.construction_no,false);
      end if;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."wms_guard_work_order_scope"() OWNER TO "postgres";

--

--
-- Name: wms_resolve_finished_receipt_warehouse("uuid", "uuid", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_resolve_finished_receipt_warehouse"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_strict" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v_material_type text; v_configured uuid; v_destination uuid; v_count bigint;
begin
 select material_type,inbound_warehouse_id into v_material_type,v_configured
 from public.mdm_material where id=p_material_id and tenant_id=p_tenant_id;
 if not found then raise exception '物料不存在或不属于当前租户' using errcode='P0002'; end if;
 if v_material_type is distinct from 'FERT' then return null; end if;
 select id into v_destination from public.mdm_warehouse
 where id=v_configured and tenant_id=p_tenant_id and warehouse_type='finished'
   and status='enabled' and cardinality(business_scopes)>0;
 if v_destination is not null then return v_destination; end if;
 select count(*),min(id::text)::uuid into v_count,v_destination
 from public.mdm_warehouse where tenant_id=p_tenant_id and warehouse_type='finished'
   and status='enabled' and cardinality(business_scopes)>0;
 if v_count=1 then return v_destination; end if;
 if p_strict then
  if v_count=0 then
   raise exception '暂无可用于业务的成品仓，请先启用成品仓并在物料主数据中配置入库仓库' using errcode='23514';
  end if;
  raise exception '存在多个成品仓，请先在物料主数据中指定入库仓库' using errcode='23514';
 end if;
 return null;
end $$;


ALTER FUNCTION "app_private"."wms_resolve_finished_receipt_warehouse"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_strict" boolean) OWNER TO "postgres";

--

--
-- Name: wms_resolve_write_tenant_id("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_resolve_write_tenant_id"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare scope_id uuid;
begin
 if auth.uid() is null then raise exception '请先登录' using errcode='42501'; end if;
 if p_tenant_id is null then raise exception '请明确业务租户' using errcode='22023'; end if;
 if app_private.is_platform_super() then
   scope_id:=app_private.current_read_tenant_id();
   if scope_id is not null and scope_id<>p_tenant_id then
     raise exception '写入目标与当前租户范围不一致' using errcode='42501';
   end if;
   if not exists(select 1 from public.sys_tenant t where t.id=p_tenant_id and t.status='1'
     and t.builtin_type is distinct from 'platform'
     and (t.service_start_date is null or t.service_start_date<=(now() at time zone 'Asia/Shanghai')::date)
     and (t.service_end_date is null or t.service_end_date>=(now() at time zone 'Asia/Shanghai')::date)) then
     raise exception '业务租户不存在、已停用或不在服务期' using errcode='22023';
   end if;
 else
   if app_private.auth_user_tenant_id() is distinct from p_tenant_id then
     raise exception '不能维护当前租户之外的数据' using errcode='42501';
   end if;
 end if;
 return p_tenant_id;
end $$;


ALTER FUNCTION "app_private"."wms_resolve_write_tenant_id"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: wms_warehouse_organization_guard(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."wms_warehouse_organization_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_org public.mdm_organization%rowtype;
begin
 if new.organization_id is null then
  select id into new.organization_id from public.mdm_organization
  where tenant_id=new.tenant_id and is_system=true;
 end if;
 select * into v_org from public.mdm_organization
 where id=new.organization_id and tenant_id=new.tenant_id;
 if not found or v_org.status<>'1' then
  raise exception '仓库库存组织不存在或已停用' using errcode='23514';end if;
 return new;
end $$;


ALTER FUNCTION "app_private"."wms_warehouse_organization_guard"() OWNER TO "postgres";

