CREATE OR REPLACE FUNCTION "public"."copy_mdm_document_type"("p_source_id" "uuid", "p_menu_id" "uuid", "p_document_type_code" "text", "p_document_type_name" "text", "p_is_default" boolean, "p_remark" "text", "p_sort_order" integer, "p_text_color" "text", "p_tag_style" "text", "p_enabled" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_source public.mdm_document_type%rowtype; v_id uuid;
begin
 if auth.uid() is null then raise exception '请先登录后再复制单据类型' using errcode='42501'; end if;
 if not app_private.is_platform_super() and not (app_private.has_permission('MdmDocumentType:View') and app_private.has_permission('MdmDocumentType:Copy')) then raise exception '无权复制单据类型' using errcode='42501'; end if;
 select source.* into v_source from public.mdm_document_type source where source.id=p_source_id and app_private.tenant_in_current_read_scope(source.tenant_id);
 if not found then raise exception '源单据类型不存在或不在当前租户范围内' using errcode='P0002'; end if;
 insert into public.mdm_document_type (tenant_id,menu_id,document_type_code,document_type_name,is_default,remark,sort_order,text_color,tag_style,enabled,extension_fields)
 values(v_source.tenant_id,p_menu_id,p_document_type_code,p_document_type_name,p_is_default,p_remark,p_sort_order,p_text_color,p_tag_style,p_enabled,
 case when p_menu_id=v_source.menu_id then v_source.extension_fields else '[]'::jsonb end) returning id into v_id;
 return v_id;
end $$;


