CREATE OR REPLACE FUNCTION "public"."create_tms_carrier_payment"("p_carrier_id" "uuid", "p_transaction_date" "date", "p_amount" numeric, "p_payment_method" "text", "p_bank_reference" "text", "p_voucher_urls" "jsonb", "p_remark" "text", "p_allocations" "jsonb", "p_transaction_no" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
