--

--
-- Name: execute_sql_query("text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."execute_sql_query"("sql_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_result jsonb;
  v_rows jsonb;
  v_columns jsonb;
  v_command_tag text;
  v_row_count integer := 0;
  v_start_time timestamp with time zone;
  v_end_time timestamp with time zone;
  v_duration_ms numeric;
  v_notices text[] := ARRAY[]::text[];
  v_warnings text[] := ARRAY[]::text[];
  v_query_upper text;
  v_error_message text;
  v_sql_state text;
  v_sql_err_msg text;
  v_detail text;
  v_sql_lines text[];
  v_line_num integer;
  v_found_line boolean := false;
  v_line_content text;
  v_identifier text;
  v_col_rec record;
  v_col_info jsonb;
  v_col_name text;
  v_col_value jsonb;
  v_col_type text;
BEGIN
  -- 记录开始时间
  v_start_time := clock_timestamp();
  v_query_upper := upper(trim(sql_query));
  
  -- 将 SQL 查询按行分割，用于后续的 LINE 信息提取
  v_sql_lines := string_to_array(sql_query, E'\n');

  -- 检查是否为 SELECT 查询
  IF v_query_upper LIKE 'SELECT%' OR v_query_upper LIKE 'WITH%' THEN
    -- 对于 SELECT 查询，使用动态 SQL 转换为 JSON
    BEGIN
      -- 执行查询获取结果
      EXECUTE format('SELECT jsonb_agg(row_to_json(t)) FROM (%s) t', sql_query) INTO v_rows;
      
      -- 如果结果为 NULL（没有行），设置为空数组
      IF v_rows IS NULL THEN
        v_rows := '[]'::jsonb;
      END IF;
      
      v_row_count := jsonb_array_length(v_rows);
      v_command_tag := format('SELECT %s', v_row_count);
      
      -- 获取列信息
      v_columns := '[]'::jsonb;
      
      -- 如果有数据行，从第一行获取列名和类型信息
      IF v_row_count > 0 THEN
        DECLARE
          v_first_row jsonb;
          v_col_info_item jsonb;
        BEGIN
          v_first_row := v_rows->0;
          
          -- 遍历第一行的所有键（列名）
          FOR v_col_name, v_col_value IN SELECT * FROM jsonb_each(v_first_row)
          LOOP
            -- 根据值的类型推断 PostgreSQL 类型
            v_col_type := CASE
              WHEN jsonb_typeof(v_col_value) = 'null' THEN 'unknown'
              WHEN jsonb_typeof(v_col_value) = 'boolean' THEN 'boolean'
              WHEN jsonb_typeof(v_col_value) = 'number' THEN 
                CASE 
                  WHEN v_col_value::text ~ '^-?[0-9]+$' THEN 'integer'
                  ELSE 'numeric'
                END
              WHEN jsonb_typeof(v_col_value) = 'string' THEN
                CASE
                  WHEN v_col_value::text ~ '^\d{4}-\d{2}-\d{2}' THEN 'date'
                  WHEN v_col_value::text ~ '^\d{4}-\d{2}-\d{2}.*\d{2}:\d{2}:\d{2}' THEN 'timestamp'
                  ELSE 'text'
                END
              WHEN jsonb_typeof(v_col_value) = 'object' THEN 'jsonb'
              WHEN jsonb_typeof(v_col_value) = 'array' THEN 'array'
              ELSE 'text'
            END;
            
            -- 构建列信息对象
            v_col_info_item := jsonb_build_object(
              'name', v_col_name,
              'type', v_col_type,
              'nullable', true,  -- 默认值
              'jsType', CASE 
                WHEN v_col_type IN ('integer', 'numeric', 'bigint', 'smallint', 'real', 'double precision') THEN 'number'
                WHEN v_col_type = 'boolean' THEN 'boolean'
                WHEN v_col_type IN ('date', 'timestamp', 'timestamptz', 'time', 'timetz') THEN 'date'
                WHEN v_col_type IN ('json', 'jsonb') THEN 'json'
                ELSE 'string'
              END,
              'description', NULL
            );
            
            v_columns := v_columns || jsonb_build_array(v_col_info_item);
          END LOOP;
        END;
      END IF;
      
      -- 尝试从查询结果中获取更详细的列信息
      -- 使用 pg_catalog 查询列的描述信息
      -- 注意：这需要知道表名，对于复杂查询可能不适用
      DECLARE
        v_table_schema text;
        v_table_name text;
        v_table_match text[];
        v_col_descriptions jsonb;
      BEGIN
        -- 尝试从 SQL 中提取表名（简单匹配 FROM 子句）
        -- 匹配: FROM schema.table 或 FROM table
        v_table_match := regexp_match(sql_query, E'(?i)\\s+FROM\\s+(?:([a-z_][a-z0-9_]*)\\.)?([a-z_][a-z0-9_]*)', 'i');
        
        IF v_table_match IS NOT NULL THEN
          v_table_schema := COALESCE(NULLIF(v_table_match[1], ''), 'public');
          v_table_name := v_table_match[2];
          
          -- 查询列的描述信息
          FOR v_col_rec IN
            SELECT 
              a.attname as column_name,
              pg_catalog.format_type(a.atttypid, a.atttypmod) as data_type,
              a.attnotnull as is_not_null,
              COALESCE(d.description, '') as column_comment
            FROM pg_catalog.pg_attribute a
            JOIN pg_catalog.pg_class c ON c.oid = a.attrelid
            JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
            LEFT JOIN pg_catalog.pg_description d ON d.objoid = c.oid AND d.objsubid = a.attnum
            WHERE n.nspname = v_table_schema
              AND c.relname = v_table_name
              AND a.attnum > 0
              AND NOT a.attisdropped
            ORDER BY a.attnum
          LOOP
            -- 更新对应列的信息
            v_columns := (
              SELECT jsonb_agg(
                CASE 
                  WHEN col->>'name' = v_col_rec.column_name THEN
                    jsonb_build_object(
                      'name', v_col_rec.column_name,
                      'type', split_part(v_col_rec.data_type, '(', 1),  -- 移除长度信息
                      'fullType', v_col_rec.data_type,
                      'nullable', NOT v_col_rec.is_not_null,
                      'jsType', CASE 
                        WHEN v_col_rec.data_type LIKE '%int%' OR v_col_rec.data_type LIKE '%numeric%' OR v_col_rec.data_type LIKE '%float%' OR v_col_rec.data_type LIKE '%double%' THEN 'number'
                        WHEN v_col_rec.data_type LIKE '%bool%' THEN 'boolean'
                        WHEN v_col_rec.data_type LIKE '%date%' OR v_col_rec.data_type LIKE '%time%' THEN 'date'
                        WHEN v_col_rec.data_type LIKE '%json%' THEN 'json'
                        ELSE 'string'
                      END,
                      'description', NULLIF(v_col_rec.column_comment, '')
                    )
                  ELSE col
                END
              )
              FROM jsonb_array_elements(v_columns) AS col
            );
          END LOOP;
        END IF;
      END;
      
    EXCEPTION
      WHEN OTHERS THEN
        -- 获取详细的错误信息
        GET STACKED DIAGNOSTICS
          v_sql_state = RETURNED_SQLSTATE,
          v_sql_err_msg = MESSAGE_TEXT,
          v_detail = PG_EXCEPTION_DETAIL;
        
        -- 构建错误消息，格式与 Supabase 一致
        v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
        
        -- 尝试从错误消息中提取引用的标识符（表名、列名等）
        v_identifier := (regexp_match(v_sql_err_msg, E'"([^"]+)"'))[1];
        
        -- 如果找到了标识符，在 SQL 查询中查找包含该标识符的行
        IF v_identifier IS NOT NULL THEN
          FOR v_line_num IN 1..array_length(v_sql_lines, 1) LOOP
            v_line_content := v_sql_lines[v_line_num];
            
            IF v_line_content LIKE '%' || v_identifier || '%' THEN
              v_error_message := v_error_message || E'\n' || 
                format('LINE %s: %s', v_line_num, trim(v_line_content)) || E'\n' ||
                repeat(' ', greatest(5 + length(v_line_num::text) + 2, 0)) || '^';
              v_found_line := true;
              EXIT;
            END IF;
          END LOOP;
        END IF;
        
        IF NOT v_found_line THEN
          IF v_detail IS NOT NULL AND v_detail != '' THEN
            v_error_message := v_error_message || E'\n' || v_detail;
          END IF;
        END IF;
        
        RETURN jsonb_build_object(
          'error', true,
          'error_message', v_error_message,
          'sql_state', v_sql_state,
          'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
        );
    END;
    
  ELSIF v_query_upper LIKE 'INSERT%' THEN
    BEGIN
      EXECUTE sql_query;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_command_tag := format('INSERT 0 %s', v_row_count);
      v_rows := '[]'::jsonb;
      v_columns := '[]'::jsonb;
    EXCEPTION
      WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
          v_sql_state = RETURNED_SQLSTATE,
          v_sql_err_msg = MESSAGE_TEXT,
          v_detail = PG_EXCEPTION_DETAIL;
        v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
        IF v_detail IS NOT NULL AND v_detail != '' THEN
          v_error_message := v_error_message || E'\n' || v_detail;
        END IF;
        RETURN jsonb_build_object(
          'error', true,
          'error_message', v_error_message,
          'sql_state', v_sql_state,
          'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
        );
    END;
    
  ELSIF v_query_upper LIKE 'UPDATE%' THEN
    BEGIN
      EXECUTE sql_query;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_command_tag := format('UPDATE %s', v_row_count);
      v_rows := '[]'::jsonb;
      v_columns := '[]'::jsonb;
    EXCEPTION
      WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
          v_sql_state = RETURNED_SQLSTATE,
          v_sql_err_msg = MESSAGE_TEXT,
          v_detail = PG_EXCEPTION_DETAIL;
        v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
        IF v_detail IS NOT NULL AND v_detail != '' THEN
          v_error_message := v_error_message || E'\n' || v_detail;
        END IF;
        RETURN jsonb_build_object(
          'error', true,
          'error_message', v_error_message,
          'sql_state', v_sql_state,
          'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
        );
    END;
    
  ELSIF v_query_upper LIKE 'DELETE%' THEN
    BEGIN
      EXECUTE sql_query;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_command_tag := format('DELETE %s', v_row_count);
      v_rows := '[]'::jsonb;
      v_columns := '[]'::jsonb;
    EXCEPTION
      WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
          v_sql_state = RETURNED_SQLSTATE,
          v_sql_err_msg = MESSAGE_TEXT,
          v_detail = PG_EXCEPTION_DETAIL;
        v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
        IF v_detail IS NOT NULL AND v_detail != '' THEN
          v_error_message := v_error_message || E'\n' || v_detail;
        END IF;
        RETURN jsonb_build_object(
          'error', true,
          'error_message', v_error_message,
          'sql_state', v_sql_state,
          'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
        );
    END;
    
  ELSE
    BEGIN
      EXECUTE sql_query;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_command_tag := upper(split_part(trim(sql_query), ' ', 1));
      v_rows := '[]'::jsonb;
      v_columns := '[]'::jsonb;
    EXCEPTION
      WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
          v_sql_state = RETURNED_SQLSTATE,
          v_sql_err_msg = MESSAGE_TEXT,
          v_detail = PG_EXCEPTION_DETAIL;
        v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
        IF v_detail IS NOT NULL AND v_detail != '' THEN
          v_error_message := v_error_message || E'\n' || v_detail;
        END IF;
        RETURN jsonb_build_object(
          'error', true,
          'error_message', v_error_message,
          'sql_state', v_sql_state,
          'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
        );
    END;
  END IF;
  
  -- 记录结束时间
  v_end_time := clock_timestamp();
  v_duration_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
  
  -- 构建返回结果
  v_result := jsonb_build_object(
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'columns', COALESCE(v_columns, '[]'::jsonb),
    'command_tag', v_command_tag,
    'row_count', v_row_count,
    'duration_ms', round(v_duration_ms::numeric, 2),
    'notices', v_notices,
    'warnings', v_warnings
  );
  
  RETURN v_result;
  
EXCEPTION
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_sql_state = RETURNED_SQLSTATE,
      v_sql_err_msg = MESSAGE_TEXT,
      v_detail = PG_EXCEPTION_DETAIL;
    
    v_error_message := format('ERROR: %s: %s', v_sql_state, v_sql_err_msg);
    
    IF v_detail IS NOT NULL AND v_detail != '' THEN
      v_error_message := v_error_message || E'\n' || v_detail;
    END IF;
    
    RETURN jsonb_build_object(
      'error', true,
      'error_message', v_error_message,
      'sql_state', v_sql_state,
      'duration_ms', round(EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) * 1000::numeric, 2)
    );
END;
$_$;


ALTER FUNCTION "public"."execute_sql_query"("sql_query" "text") OWNER TO "postgres";

--

--
-- Name: export_mdm_business_types("uuid", "uuid"[], "uuid", "text", boolean, boolean, integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."export_mdm_business_types"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_menu_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_document_type_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT NULL::"text", "p_enabled" boolean DEFAULT NULL::boolean, "p_is_default" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 10000) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "tenant_code" "text", "tenant_name" "text", "menu_id" "uuid", "document_type_id" "uuid", "document_type_code" "text", "document_type_name" "text", "business_type_code" "text", "business_type_name" "text", "is_default" boolean, "source_business_type_id" "uuid", "source_business_type_code" "text", "source_business_type_name" "text", "inventory_direction" "text", "owner_type" "text", "inventory_accounting" boolean, "remark" "text", "sort_order" integer, "text_color" "text", "tag_style" "text", "enabled" boolean, "create_by" "text", "create_time" timestamp with time zone, "update_by" "text", "update_time" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception '请先登录后再导出业务类型' using errcode='42501';
  end if;
  if not app_private.is_platform_super()
     and not (
       app_private.has_permission('MdmBusinessType:View')
       and app_private.has_permission('MdmBusinessType:Export')
     ) then
    raise exception '无权导出业务类型' using errcode='42501';
  end if;

  return query
  select
    business_type.id,business_type.tenant_id,tenant.tenant_code,tenant.tenant_name,
    document_type.menu_id,business_type.document_type_id,
    document_type.document_type_code,document_type.document_type_name,
    business_type.business_type_code,business_type.business_type_name,business_type.is_default,
    business_type.source_business_type_id,source.business_type_code,source.business_type_name,
    business_type.inventory_direction,business_type.owner_type,business_type.inventory_accounting,
    business_type.remark,business_type.sort_order,business_type.text_color,
    business_type.tag_style,business_type.enabled,business_type.create_by,
    business_type.create_time,business_type.update_by,business_type.update_time
  from public.mdm_business_type business_type
  join public.mdm_document_type document_type on document_type.id=business_type.document_type_id
    and document_type.tenant_id=business_type.tenant_id
  join public.sys_tenant tenant on tenant.id=business_type.tenant_id
  left join public.mdm_business_type source on source.id=business_type.source_business_type_id
    and source.tenant_id=business_type.tenant_id
  where (p_tenant_id is null or business_type.tenant_id=p_tenant_id)
    and (p_menu_ids is null or document_type.menu_id=any(p_menu_ids))
    and (p_document_type_id is null or business_type.document_type_id=p_document_type_id)
    and (p_enabled is null or business_type.enabled=p_enabled)
    and (p_is_default is null or business_type.is_default=p_is_default)
    and (
      nullif(btrim(p_keyword),'') is null
      or concat_ws(' ',business_type.business_type_code,business_type.business_type_name,business_type.remark)
        ilike '%'||btrim(p_keyword)||'%'
    )
  order by business_type.sort_order,business_type.business_type_name,business_type.id
  limit least(greatest(coalesce(p_limit,10000),1),10000);
end
$$;


ALTER FUNCTION "public"."export_mdm_business_types"("p_tenant_id" "uuid", "p_menu_ids" "uuid"[], "p_document_type_id" "uuid", "p_keyword" "text", "p_enabled" boolean, "p_is_default" boolean, "p_limit" integer) OWNER TO "postgres";

--

--
-- Name: export_mdm_document_types("uuid", "uuid"[], "text", boolean, boolean, integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."export_mdm_document_types"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_menu_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_keyword" "text" DEFAULT NULL::"text", "p_enabled" boolean DEFAULT NULL::boolean, "p_is_default" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 10000) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "tenant_code" "text", "tenant_name" "text", "menu_id" "uuid", "document_type_code" "text", "document_type_name" "text", "is_default" boolean, "remark" "text", "sort_order" integer, "text_color" "text", "tag_style" "text", "enabled" boolean, "create_by" "text", "create_time" timestamp with time zone, "update_by" "text", "update_time" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception '请先登录后再导出单据类型' using errcode='42501'; end if;
  if not app_private.is_platform_super() and not (app_private.has_permission('MdmDocumentType:View') and app_private.has_permission('MdmDocumentType:Export')) then
    raise exception '无权导出单据类型' using errcode='42501';
  end if;
  return query
  select
    document_type.id,document_type.tenant_id,tenant.tenant_code,tenant.tenant_name,
    document_type.menu_id,document_type.document_type_code,document_type.document_type_name,
    document_type.is_default,document_type.remark,document_type.sort_order,
    document_type.text_color,document_type.tag_style,document_type.enabled,
    document_type.create_by,document_type.create_time,document_type.update_by,document_type.update_time
  from public.mdm_document_type document_type
  join public.sys_tenant tenant on tenant.id=document_type.tenant_id
  where (p_tenant_id is null or document_type.tenant_id=p_tenant_id)
    and (p_menu_ids is null or document_type.menu_id=any(p_menu_ids))
    and (p_enabled is null or document_type.enabled=p_enabled)
    and (p_is_default is null or document_type.is_default=p_is_default)
    and (nullif(btrim(p_keyword),'') is null or concat_ws(' ',document_type.document_type_code,document_type.document_type_name,document_type.remark) ilike '%'||btrim(p_keyword)||'%')
  order by document_type.sort_order,document_type.document_type_name,document_type.id
  limit least(greatest(coalesce(p_limit,10000),1),10000);
end
$$;


ALTER FUNCTION "public"."export_mdm_document_types"("p_tenant_id" "uuid", "p_menu_ids" "uuid"[], "p_keyword" "text", "p_enabled" boolean, "p_is_default" boolean, "p_limit" integer) OWNER TO "postgres";

--

--
-- Name: finish_notification_delivery("uuid", boolean, "text", "text", boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."finish_notification_delivery"("p_delivery_id" "uuid", "p_succeeded" boolean, "p_external_message_id" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_skipped" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_delivery public.sys_notification_delivery%rowtype;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'Service role required' using errcode = '42501';
  end if;
  update public.sys_notification_delivery
  set status = case when p_succeeded then 'delivered' when p_skipped then 'skipped' else 'failed' end,
      delivered_at = case when p_succeeded then now() else null end,
      external_message_id = nullif(p_external_message_id, ''),
      error_message = case when p_succeeded then null else left(coalesce(p_error_message, '投递失败'), 1000) end,
      next_retry_at = case
        when p_succeeded or p_skipped or attempt_count >= 5 then null
        else now() + make_interval(mins => least(15 * attempt_count, 120))
      end,
      update_by = 'notification-dispatcher'
  where id = p_delivery_id and status = 'processing'
  returning * into v_delivery;
  if not found then return false; end if;

  update public.sys_notification_channel_config
  set last_test_status = case
        when last_test_at is not null and last_test_at >= v_delivery.create_time
          then case when p_succeeded then 'delivered' else 'failed' end
        else last_test_status
      end,
      last_error = case when p_succeeded then null else left(coalesce(p_error_message, '投递失败'), 1000) end,
      update_by = 'notification-dispatcher'
  where tenant_id = v_delivery.tenant_id and channel_code = v_delivery.channel_code;

  if v_delivery.event_id is not null and not exists (
    select 1 from public.sys_notification_delivery
    where event_id = v_delivery.event_id and status in ('pending', 'processing', 'failed')
  ) then
    update public.sys_notification_event
    set status = case when exists (
          select 1 from public.sys_notification_delivery
          where event_id = v_delivery.event_id and status = 'delivered'
        ) then 'delivered' else 'failed' end,
        update_by = 'notification-dispatcher'
    where id = v_delivery.event_id;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."finish_notification_delivery"("p_delivery_id" "uuid", "p_succeeded" boolean, "p_external_message_id" "text", "p_error_message" "text", "p_skipped" boolean) OWNER TO "postgres";

--

--
-- Name: get_accessible_applications(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_accessible_applications"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'code', application_row.app_code,
    'name', application_row.app_name,
    'description', application_row.description,
    'baseUrl', application_row.base_url,
    'sort', application_row.sort
  ) order by application_row.sort, application_row.app_code), '[]'::jsonb)
  from public.sys_application application_row
  where (select auth.uid()) is not null
    and application_row.enabled
    and (
      app_private.is_platform_super()
      or exists (
        select 1
        from public.sys_user current_user_row
        join public.sys_role role_row
          on role_row.role_code = any(coalesce(current_user_row.user_roles, array[]::text[]))
         and role_row.enabled
         and (
           role_row.tenant_id = current_user_row.tenant_id
           or role_row.tenant_id is null
         )
        join public.sys_role_menu role_menu on role_menu.role_id = role_row.id
        join public.sys_menu menu_row
          on menu_row.id = role_menu.menu_id
         and menu_row.app_code = application_row.app_code
        where current_user_row.auth_user_id = (select auth.uid())
          and current_user_row.status = '1'
          and current_user_row.deleted_at is null
      )
    );
$$;


ALTER FUNCTION "public"."get_accessible_applications"() OWNER TO "postgres";

--

--
-- Name: get_ai_project_capability_snapshot(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_ai_project_capability_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from public.sys_user app_user
    where app_user.auth_user_id = (select auth.uid())
      and app_user.status = '1'
  ) then
    raise exception 'Active authenticated user permission is required'
      using errcode = '42501';
  end if;

  return app_private.get_ai_project_capability_snapshot();
end;
$$;


ALTER FUNCTION "public"."get_ai_project_capability_snapshot"() OWNER TO "postgres";

--

--
-- Name: get_ai_project_catalog("text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_ai_project_catalog"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_action text := lower(coalesce(nullif(btrim(p_action), ''), 'overview'));
  v_type text := lower(coalesce(nullif(btrim(p_args->>'objectType'), ''), 'all'));
  v_schema text := coalesce(nullif(btrim(p_args->>'schema'), ''), 'public');
  v_name text := nullif(btrim(p_args->>'name'), '');
  v_keyword text := nullif(btrim(p_args->>'keyword'), '');
  v_limit integer := least(greatest(coalesce((p_args->>'limit')::integer, 50), 1), 200);
  v_result jsonb;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from public.sys_user as app_user
    where app_user.auth_user_id = (select auth.uid())
      and app_user.status = '1'
  ) then
    raise exception 'Active authenticated user permission is required'
      using errcode = '42501';
  end if;

  if v_action = 'overview' then
    select jsonb_build_object(
      'projectRef', 'ckbftoopuyophiebamwy',
      'databaseVersion', current_setting('server_version'),
      'schemas', (
        select count(*) from pg_namespace
        where nspname not like 'pg_%' and nspname <> 'information_schema'
      ),
      'tables', (
        select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
        where c.relkind in ('r','p') and n.nspname not like 'pg_%'
          and n.nspname <> 'information_schema'
      ),
      'views', (
        select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
        where c.relkind in ('v','m') and n.nspname not like 'pg_%'
          and n.nspname <> 'information_schema'
      ),
      'functions', (
        select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
      ),
      'triggers', (
        select count(*) from pg_trigger t
        join pg_class c on c.oid=t.tgrelid
        join pg_namespace n on n.oid=c.relnamespace
        where not t.tgisinternal and n.nspname not like 'pg_%'
          and n.nspname <> 'information_schema'
      ),
      'policies', (
        select count(*) from pg_policy pol
        join pg_class c on c.oid=pol.polrelid
        join pg_namespace n on n.oid=c.relnamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
      ),
      'indexes', (
        select count(*) from pg_index i
        join pg_class c on c.oid=i.indexrelid
        join pg_namespace n on n.oid=c.relnamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
      )
    ) into v_result;
    return v_result;
  end if;

  if v_action = 'schemas' then
    select coalesce(jsonb_agg(x.name order by x.name), '[]'::jsonb)
    into v_result
    from (
      select nspname as name
      from pg_namespace
      where nspname not like 'pg_%' and nspname <> 'information_schema'
    ) x;
    return v_result;
  end if;

  if v_action = 'list_objects' then
    select coalesce(jsonb_agg(to_jsonb(x) order by x.object_type, x.schema_name, x.object_name), '[]'::jsonb)
    into v_result
    from (
      select *
      from (
        select n.nspname as schema_name, c.relname as object_name,
          case c.relkind when 'v' then 'view' when 'm' then 'materialized_view' else 'table' end as object_type,
          obj_description(c.oid, 'pg_class') as description
        from pg_class c join pg_namespace n on n.oid=c.relnamespace
        where c.relkind in ('r','p','v','m')
          and n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
        union all
        select n.nspname, p.proname, 'function',
          obj_description(p.oid, 'pg_proc')
        from pg_proc p join pg_namespace n on n.oid=p.pronamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
        union all
        select n.nspname, t.tgname, 'trigger',
          'on ' || quote_ident(c.relname)
        from pg_trigger t
        join pg_class c on c.oid=t.tgrelid
        join pg_namespace n on n.oid=c.relnamespace
        where not t.tgisinternal and n.nspname not like 'pg_%'
          and n.nspname <> 'information_schema'
        union all
        select n.nspname, pol.polname, 'policy',
          'on ' || quote_ident(c.relname)
        from pg_policy pol
        join pg_class c on c.oid=pol.polrelid
        join pg_namespace n on n.oid=c.relnamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
        union all
        select n.nspname, idx.relname, 'index',
          'on ' || quote_ident(tbl.relname)
        from pg_index i
        join pg_class idx on idx.oid=i.indexrelid
        join pg_class tbl on tbl.oid=i.indrelid
        join pg_namespace n on n.oid=idx.relnamespace
        where n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
      ) objects
      where (v_type = 'all' or objects.object_type = v_type
        or (v_type = 'view' and objects.object_type = 'materialized_view'))
        and (v_schema = 'all' or objects.schema_name = v_schema)
        and (v_keyword is null
          or objects.object_name ilike '%' || v_keyword || '%'
          or coalesce(objects.description, '') ilike '%' || v_keyword || '%')
      limit v_limit
    ) x;
    return v_result;
  end if;

  if v_action = 'object_detail' then
    if v_name is null then
      raise exception 'Object name is required' using errcode = '22023';
    end if;

    if v_type = 'table' then
      select jsonb_build_object(
        'schemaName', n.nspname,
        'objectName', c.relname,
        'objectType', 'table',
        'description', obj_description(c.oid, 'pg_class'),
        'columns', coalesce((
          select jsonb_agg(jsonb_build_object(
            'name', a.attname,
            'dataType', format_type(a.atttypid, a.atttypmod),
            'nullable', not a.attnotnull,
            'defaultValue', pg_get_expr(ad.adbin, ad.adrelid),
            'description', col_description(a.attrelid, a.attnum)
          ) order by a.attnum)
          from pg_attribute a
          left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum
          where a.attrelid=c.oid and a.attnum > 0 and not a.attisdropped
        ), '[]'::jsonb),
        'constraints', coalesce((
          select jsonb_agg(jsonb_build_object(
            'name', con.conname,
            'type', con.contype,
            'definition', pg_get_constraintdef(con.oid, true)
          ) order by con.conname)
          from pg_constraint con where con.conrelid=c.oid
        ), '[]'::jsonb),
        'ddl', 'CREATE TABLE ' || quote_ident(n.nspname) || '.' || quote_ident(c.relname)
          || E' (\n'
          || coalesce((
            select string_agg(
              '  ' || quote_ident(a.attname) || ' ' || format_type(a.atttypid, a.atttypmod)
              || case when ad.adbin is not null then ' DEFAULT ' || pg_get_expr(ad.adbin, ad.adrelid) else '' end
              || case when a.attnotnull then ' NOT NULL' else '' end,
              E',\n' order by a.attnum
            )
            from pg_attribute a
            left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum
            where a.attrelid=c.oid and a.attnum > 0 and not a.attisdropped
          ), '')
          || coalesce((
            select E',\n' || string_agg(
              '  CONSTRAINT ' || quote_ident(con.conname) || ' ' || pg_get_constraintdef(con.oid, true),
              E',\n' order by con.conname
            )
            from pg_constraint con where con.conrelid=c.oid
          ), '')
          || E'\n);'
      ) into v_result
      from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname=v_schema and c.relname=v_name and c.relkind in ('r','p')
      limit 1;
    elsif v_type in ('view','materialized_view') then
      select jsonb_build_object(
        'schemaName', n.nspname, 'objectName', c.relname,
        'objectType', case c.relkind when 'm' then 'materialized_view' else 'view' end,
        'description', obj_description(c.oid, 'pg_class'),
        'ddl', 'CREATE ' || case when c.relkind='m' then 'MATERIALIZED ' else '' end
          || 'VIEW ' || quote_ident(n.nspname) || '.' || quote_ident(c.relname)
          || E' AS\n' || pg_get_viewdef(c.oid, true) || ';'
      ) into v_result
      from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname=v_schema and c.relname=v_name and c.relkind in ('v','m')
      limit 1;
    elsif v_type = 'function' then
      select jsonb_build_object(
        'schemaName', n.nspname, 'objectName', p.proname, 'objectType', 'function',
        'description', obj_description(p.oid, 'pg_proc'),
        'identityArguments', pg_get_function_identity_arguments(p.oid),
        'resultType', pg_get_function_result(p.oid),
        'ddl', pg_get_functiondef(p.oid)
      ) into v_result
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname=v_schema and p.proname=v_name
      order by p.oid limit 1;
    elsif v_type = 'trigger' then
      select jsonb_build_object(
        'schemaName', n.nspname, 'objectName', t.tgname, 'objectType', 'trigger',
        'tableName', c.relname, 'enabled', t.tgenabled,
        'ddl', pg_get_triggerdef(t.oid, true) || ';'
      ) into v_result
      from pg_trigger t
      join pg_class c on c.oid=t.tgrelid
      join pg_namespace n on n.oid=c.relnamespace
      where n.nspname=v_schema and t.tgname=v_name and not t.tgisinternal
      limit 1;
    elsif v_type = 'policy' then
      select jsonb_build_object(
        'schemaName', schemaname, 'objectName', policyname, 'objectType', 'policy',
        'tableName', tablename, 'command', cmd, 'roles', roles,
        'usingExpression', qual, 'checkExpression', with_check,
        'ddl', 'CREATE POLICY ' || quote_ident(policyname) || ' ON '
          || quote_ident(schemaname) || '.' || quote_ident(tablename)
          || ' FOR ' || cmd
          || case when array_length(roles,1) > 0 then ' TO ' || array_to_string(roles, ', ') else '' end
          || case when qual is not null then ' USING (' || qual || ')' else '' end
          || case when with_check is not null then ' WITH CHECK (' || with_check || ')' else '' end
          || ';'
      ) into v_result
      from pg_policies
      where schemaname=v_schema and policyname=v_name
      limit 1;
    elsif v_type = 'index' then
      select jsonb_build_object(
        'schemaName', n.nspname, 'objectName', idx.relname, 'objectType', 'index',
        'tableName', tbl.relname, 'isUnique', i.indisunique, 'isPrimary', i.indisprimary,
        'ddl', pg_get_indexdef(idx.oid) || ';'
      ) into v_result
      from pg_index i
      join pg_class idx on idx.oid=i.indexrelid
      join pg_class tbl on tbl.oid=i.indrelid
      join pg_namespace n on n.oid=idx.relnamespace
      where n.nspname=v_schema and idx.relname=v_name
      limit 1;
    else
      raise exception 'Unsupported object type: %', v_type using errcode = '22023';
    end if;
    return coalesce(v_result, jsonb_build_object('notFound', true));
  end if;

  if v_action = 'relationships' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'constraintName', con.conname,
      'sourceSchema', ns.nspname,
      'sourceTable', src.relname,
      'sourceColumns', (
        select jsonb_agg(sa.attname order by k.ordinality)
        from unnest(con.conkey) with ordinality k(attnum, ordinality)
        join pg_attribute sa on sa.attrelid=con.conrelid and sa.attnum=k.attnum
      ),
      'targetSchema', nt.nspname,
      'targetTable', tgt.relname,
      'targetColumns', (
        select jsonb_agg(ta.attname order by k.ordinality)
        from unnest(con.confkey) with ordinality k(attnum, ordinality)
        join pg_attribute ta on ta.attrelid=con.confrelid and ta.attnum=k.attnum
      ),
      'definition', pg_get_constraintdef(con.oid, true)
    ) order by ns.nspname, src.relname, con.conname), '[]'::jsonb)
    into v_result
    from pg_constraint con
    join pg_class src on src.oid=con.conrelid
    join pg_namespace ns on ns.oid=src.relnamespace
    join pg_class tgt on tgt.oid=con.confrelid
    join pg_namespace nt on nt.oid=tgt.relnamespace
    where con.contype='f'
      and ns.nspname not like 'pg_%' and ns.nspname <> 'information_schema'
      and (v_schema='all' or ns.nspname=v_schema)
      and (v_name is null or src.relname=v_name or tgt.relname=v_name);
    return v_result;
  end if;

  raise exception 'Unsupported catalog action: %', v_action using errcode = '22023';
exception
  when invalid_text_representation then
    raise exception 'Invalid catalog arguments' using errcode = '22023';
end;
$$;


ALTER FUNCTION "public"."get_ai_project_catalog"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";

--

--
-- Name: get_app_user_display_name(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_app_user_display_name"() RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select current_setting('myapp.current_user_display', true)
  where current_setting('myapp.current_user_display', true) is not null
  union all
  select coalesce(nullif(user_email, ''), nullif(user_name, ''), nullif(nick_name, ''))
  from public.sys_user
  where auth_user_id = (select auth.uid())
  limit 1;
$$;


ALTER FUNCTION "public"."get_app_user_display_name"() OWNER TO "postgres";

--

--
-- Name: get_attachment_delete_dependency_details("uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_attachment_delete_dependency_details"("p_resource_ids" "uuid"[]) RETURNS TABLE("resource_id" "uuid", "dependency_code" "text", "record_id" "uuid", "target_id" "uuid", "record_no" "text", "record_summary" "text", "record_status" "text", "record_amount" numeric, "created_at" timestamp with time zone, "cleanup_allowed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if to_regclass('public.tms_waybill_proof') is null then
    return;
  end if;

  return query execute $query$
    with requested as (
      select attachment.id as resource_id
      from public.sys_attachment attachment
      where attachment.id = any(coalesce($1, '{}'::uuid[]))
        and (
          app_private.tenant_in_current_read_scope(attachment.tenant_id)
        )
    )
    select
      proof.attachment_id,
      'attachment_waybill_proof'::text,
      proof.id,
      proof.waybill_id,
      coalesce(nullif(proof.file_name, ''), proof.id::text),
      proof.proof_type,
      null::text,
      null::numeric,
      proof.create_time,
      false
    from public.tms_waybill_proof proof
    join requested on requested.resource_id = proof.attachment_id
    where app_private.tenant_in_current_read_scope(proof.tenant_id)
    order by proof.attachment_id, proof.create_time desc, proof.id
  $query$ using p_resource_ids;
end;
$_$;


ALTER FUNCTION "public"."get_attachment_delete_dependency_details"("p_resource_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: get_database_metadata_all(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_database_metadata_all"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_schemas jsonb;
  v_tables jsonb;
  v_columns jsonb;
  v_functions jsonb;
BEGIN
  -- 获取所有 schemas
  SELECT jsonb_agg(schema_name ORDER BY schema_name)
  INTO v_schemas
  FROM information_schema.schemata
  WHERE schema_name NOT IN ('pg_catalog', 'information_schema', 'pg_toast', 'pg_temp_1', 'pg_toast_temp_1');

  -- 获取所有表信息
  SELECT jsonb_agg(
    jsonb_build_object(
      'tableSchema', table_schema,
      'tableName', table_name
    )
    ORDER BY table_schema, table_name
  )
  INTO v_tables
  FROM information_schema.tables
  WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
    AND table_type = 'BASE TABLE';

  -- 获取所有列信息
  SELECT jsonb_agg(
    jsonb_build_object(
      'tableSchema', table_schema,
      'tableName', table_name,
      'columnName', column_name,
      'dataType', data_type,
      'isNullable', is_nullable,
      'ordinalPosition', ordinal_position
    )
    ORDER BY table_schema, table_name, ordinal_position
  )
  INTO v_columns
  FROM information_schema.columns
  WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'pg_toast');

  -- 获取所有函数信息
  SELECT jsonb_agg(
    jsonb_build_object(
      'routineSchema', routine_schema,
      'routineName', routine_name,
      'returnType', data_type
    )
    ORDER BY routine_schema, routine_name
  )
  INTO v_functions
  FROM information_schema.routines
  WHERE routine_schema NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
    AND routine_type = 'FUNCTION';

  -- 构建返回结果
  v_result := jsonb_build_object(
    'schemas', COALESCE(v_schemas, '[]'::jsonb),
    'tables', COALESCE(v_tables, '[]'::jsonb),
    'columns', COALESCE(v_columns, '[]'::jsonb),
    'functions', COALESCE(v_functions, '[]'::jsonb)
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_database_metadata_all"() OWNER TO "postgres";

--

--
-- Name: get_effective_ai_feature_configs(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_effective_ai_feature_configs"() RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "source_tenant_id" "uuid", "inherited" boolean, "feature" "text", "enabled" boolean, "provider" "text", "model" "text", "vision_model" "text", "fallback_model" "text", "timeout_ms" integer, "max_retries" smallint, "temperature" numeric, "max_tokens" integer, "rate_limit_per_minute" integer, "rate_limit_per_day" integer, "prompt_version" "text", "metadata" "jsonb", "create_by" "text", "create_time" timestamp with time zone, "update_by" "text", "update_time" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with request_context as (
    select
      app_private.current_user_tenant_id() as current_tenant_id,
      app_private.platform_tenant_id() as platform_tenant_id
  ),
  ranked as (
    select
      config.*,
      context.current_tenant_id,
      row_number() over (
        partition by config.feature
        order by
          case when config.tenant_id = context.current_tenant_id then 0 else 1 end,
          config.update_time desc,
          config.id
      ) as priority
    from public.ai_feature_config as config
    cross join request_context as context
    where config.tenant_id in (context.current_tenant_id, context.platform_tenant_id)
  )
  select
    ranked.id,
    ranked.current_tenant_id as tenant_id,
    ranked.tenant_id as source_tenant_id,
    ranked.tenant_id <> ranked.current_tenant_id as inherited,
    ranked.feature,
    ranked.enabled,
    ranked.provider,
    ranked.model,
    ranked.vision_model,
    ranked.fallback_model,
    ranked.timeout_ms,
    ranked.max_retries,
    ranked.temperature,
    ranked.max_tokens,
    ranked.rate_limit_per_minute,
    ranked.rate_limit_per_day,
    ranked.prompt_version,
    ranked.metadata,
    ranked.create_by,
    ranked.create_time,
    ranked.update_by,
    ranked.update_time
  from ranked
  where ranked.priority = 1
  order by ranked.feature;
$$;


ALTER FUNCTION "public"."get_effective_ai_feature_configs"() OWNER TO "postgres";

--

--
-- Name: get_field_permission_audit_logs("text", "text", "uuid", integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_field_permission_audit_logs"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_resource_id uuid;
  v_target_type text;
  v_limit integer := least(greatest(coalesce(p_limit, 10), 1), 50);
begin
  if not app_private.can_view_field_permissions() then
    raise exception 'Missing field permission page access' using errcode = '42501';
  end if;

  if p_subject_type not in ('role', 'user') then
    raise exception 'Invalid permission subject type';
  end if;

  select resource_row.id
  into v_resource_id
  from public.sys_permission_resource resource_row
  where resource_row.tenant_id = v_tenant_id
    and resource_row.resource_key = p_resource_key
    and resource_row.enabled is true;

  if v_resource_id is null then
    raise exception 'Permission resource not found';
  end if;

  if p_subject_type = 'role' and not exists (
    select 1 from public.sys_role role_row
    where role_row.id = p_subject_id
      and role_row.tenant_id = v_tenant_id
      and role_row.enabled is true
  ) then
    raise exception 'Role not found or access denied';
  end if;

  if p_subject_type = 'user' and not exists (
    select 1 from public.sys_user user_row
    where user_row.id = p_subject_id
      and user_row.tenant_id = v_tenant_id
      and user_row.status = '1'
      and user_row.deleted_at is null
  ) then
    raise exception 'User not found or access denied';
  end if;

  v_target_type := p_subject_type || '_field';

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', audit_row.id,
        'action', audit_row.action,
        'beforeValue', coalesce(audit_row.before_value, '{}'::jsonb),
        'afterValue', coalesce(audit_row.after_value, '{}'::jsonb),
        'actorName', coalesce(
          nullif(actor_user.nick_name, ''),
          nullif(actor_user.user_name, ''),
          nullif(actor_user.user_email, ''),
          audit_row.create_by
        ),
        'actorEmail', actor_user.user_email,
        'createTime', audit_row.create_time
      )
      order by audit_row.create_time desc, audit_row.id desc
    )
    from (
      select audit_log.*
      from public.sys_permission_audit_log audit_log
      where audit_log.tenant_id = v_tenant_id
        and audit_log.resource_id = v_resource_id
        and audit_log.target_type = v_target_type
        and audit_log.target_id = p_subject_id
      order by audit_log.create_time desc, audit_log.id desc
      limit v_limit
    ) audit_row
    left join public.sys_user actor_user
      on actor_user.id = audit_row.actor_user_id
     and actor_user.tenant_id = audit_row.tenant_id
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_field_permission_audit_logs"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer) OWNER TO "postgres";

--

--
-- Name: get_field_permission_configuration("text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_field_permission_configuration"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_resource public.sys_permission_resource%rowtype;
begin
  if not app_private.can_view_field_permissions() then
    raise exception 'Missing field permission page access' using errcode = '42501';
  end if;

  if p_subject_type not in ('role', 'user') then
    raise exception 'Invalid permission subject type';
  end if;

  select * into v_resource
  from public.sys_permission_resource
  where tenant_id = v_tenant_id
    and resource_key = p_resource_key
    and enabled is true;

  if not found then
    raise exception 'Permission resource not found';
  end if;

  if p_subject_type = 'role' and not exists (
    select 1 from public.sys_role
    where id = p_subject_id and tenant_id = v_tenant_id and enabled is true
  ) then
    raise exception 'Role not found or access denied';
  end if;

  if p_subject_type = 'user' and not exists (
    select 1 from public.sys_user
    where id = p_subject_id
      and tenant_id = v_tenant_id
      and status = '1'
      and deleted_at is null
  ) then
    raise exception 'User not found or access denied';
  end if;

  return jsonb_build_object(
    'resourceId', v_resource.id,
    'resourceKey', v_resource.resource_key,
    'resourceLabel', v_resource.resource_label,
    'subjectType', p_subject_type,
    'subjectId', p_subject_id,
    'fields', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', field_row.id,
          'fieldKey', field_row.field_key,
          'fieldLabel', field_row.field_label,
          'defaultAccess', field_row.default_access,
          'maskStrategy', field_row.mask_strategy,
          'ownerOverrideEnabled', field_row.owner_override_enabled,
          'inheritedAccess', case
            when p_subject_type = 'user' then coalesce((
              select case max(app_private.permission_access_rank(role_permission.access_level))
                when 3 then 'edit'
                when 2 then 'read'
                when 1 then 'masked'
                when 0 then 'hidden'
                else null
              end
              from public.sys_user subject_user
              join public.sys_role role_row
                on role_row.tenant_id = subject_user.tenant_id
               and role_row.enabled is true
               and role_row.role_code = any(coalesce(subject_user.user_roles, array[]::text[]))
              join public.sys_role_field_permission role_permission
                on role_permission.tenant_id = role_row.tenant_id
               and role_permission.role_id = role_row.id
               and role_permission.resource_id = v_resource.id
               and role_permission.field_id = field_row.id
              where subject_user.id = p_subject_id
                and subject_user.tenant_id = v_tenant_id
            ), field_row.default_access)
            else field_row.default_access
          end,
          'explicitAccess', case
            when p_subject_type = 'role' then (
              select role_permission.access_level
              from public.sys_role_field_permission role_permission
              where role_permission.tenant_id = v_tenant_id
                and role_permission.role_id = p_subject_id
                and role_permission.resource_id = v_resource.id
                and role_permission.field_id = field_row.id
            )
            else (
              select user_permission.access_level
              from public.sys_user_field_permission user_permission
              where user_permission.tenant_id = v_tenant_id
                and user_permission.user_id = p_subject_id
                and user_permission.resource_id = v_resource.id
                and user_permission.field_id = field_row.id
            )
          end
        )
        order by field_row.sort, field_row.id
      )
      from public.sys_permission_field field_row
      where field_row.tenant_id = v_tenant_id
        and field_row.resource_id = v_resource.id
        and field_row.enabled is true
        and field_row.sensitive is true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_field_permission_configuration"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid") OWNER TO "postgres";

--

--
-- Name: get_field_permission_resources(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_field_permission_resources"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not app_private.can_view_field_permissions() then
    raise exception 'Missing field permission page access' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', resource_row.id,
        'resourceKey', resource_row.resource_key,
        'resourceLabel', resource_row.resource_label,
        'menuName', resource_row.menu_name,
        'fieldCount', (
          select count(*)
          from public.sys_permission_field field_row
          where field_row.tenant_id = resource_row.tenant_id
            and field_row.resource_id = resource_row.id
            and field_row.enabled is true
        )
      )
      order by resource_row.resource_label, resource_row.resource_key
    )
    from public.sys_permission_resource resource_row
    where resource_row.tenant_id = app_private.current_user_tenant_id()
      and resource_row.enabled is true
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_field_permission_resources"() OWNER TO "postgres";

--

--
-- Name: get_governed_delete_dependency_details("text", "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_governed_delete_dependency_details"("p_resource_type" "text", "p_resource_ids" "uuid"[]) RETURNS TABLE("resource_id" "uuid", "dependency_code" "text", "record_id" "uuid", "target_id" "uuid", "record_no" "text", "record_summary" "text", "record_status" "text", "record_amount" numeric, "created_at" timestamp with time zone, "cleanup_allowed" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
begin
  if p_resource_type = any(array['carrier', 'driver', 'cargo', 'customer_address', 'vehicle']) then
    return query
    select *
    from public.get_master_data_delete_dependency_details(p_resource_type, p_resource_ids);
    return;
  end if;

  if p_resource_type = 'organization' then
    return query
    with requested as (
      select distinct unnest(coalesce(p_resource_ids, '{}'::uuid[])) as resource_id
    )
    select details.*
    from (
      select child.parent_id, 'organization_child'::text, child.id, child.id,
        child.organization_name, child.organization_code, child.status,
        null::numeric, child.create_time, false
      from public.mdm_organization child
      join requested on requested.resource_id = child.parent_id

      union all

      select app_user.organization_id, 'organization_user', app_user.id, app_user.id,
        coalesce(nullif(app_user.nick_name, ''), app_user.user_name), app_user.user_email,
        app_user.status, null::numeric, app_user.create_time, false
      from public.sys_user app_user
      join requested on requested.resource_id = app_user.organization_id

      union all

      select role.organization_id, 'organization_role', role.id, role.id,
        role.role_name, role.role_code, case when role.enabled then 'enabled' else 'disabled' end,
        null::numeric, role.create_time, false
      from public.sys_role role
      join requested on requested.resource_id = role.organization_id
    ) details(
      resource_id,
      dependency_code,
      record_id,
      target_id,
      record_no,
      record_summary,
      record_status,
      record_amount,
      created_at,
      cleanup_allowed
    )
    order by details.resource_id, details.dependency_code, details.created_at desc, details.record_id;
    return;
  end if;

  if p_resource_type = 'role' then
    return query
    with requested as (
      select distinct unnest(coalesce(p_resource_ids, '{}'::uuid[])) as resource_id
    )
    select details.*
    from (
      select role_menu.role_id, 'role_menu_grant'::text, role_menu.id, role_menu.menu_id,
        coalesce(menu.meta ->> 'title', menu.name, role_menu.menu_id::text),
        coalesce(menu.path, role_menu.permission::text), null::text,
        null::numeric, role_menu.create_time, true
      from public.sys_role_menu role_menu
      join requested on requested.resource_id = role_menu.role_id
      left join public.sys_menu menu on menu.id = role_menu.menu_id

      union all

      select role.id, 'role_user_assignment', app_user.id, app_user.id,
        coalesce(nullif(app_user.nick_name, ''), app_user.user_name), app_user.user_email,
        app_user.status, null::numeric, app_user.create_time, true
      from public.sys_role role
      join requested on requested.resource_id = role.id
      join public.sys_user app_user
        on role.role_code = any(coalesce(app_user.user_roles, '{}'::text[]))
    ) details(
      resource_id,
      dependency_code,
      record_id,
      target_id,
      record_no,
      record_summary,
      record_status,
      record_amount,
      created_at,
      cleanup_allowed
    )
    order by details.resource_id, details.cleanup_allowed desc, details.dependency_code,
      details.created_at desc, details.record_id;
    return;
  end if;

  if p_resource_type = 'menu' then
    return query
    with requested as (
      select distinct unnest(coalesce(p_resource_ids, '{}'::uuid[])) as resource_id
    )
    select details.*
    from (
      select role_menu.menu_id, 'menu_role_grant'::text, role_menu.id, role_menu.role_id,
        role.role_name, role.role_code, case when role.enabled then 'enabled' else 'disabled' end,
        null::numeric, role_menu.create_time, true
      from public.sys_role_menu role_menu
      join requested on requested.resource_id = role_menu.menu_id
      left join public.sys_role role on role.id = role_menu.role_id

      union all

      select scene.menu_id, 'menu_document_number_scene', md5(scene.rule_key)::uuid, scene.menu_id,
        scene.rule_key, concat_ws(' · ', scene.rule_name, scene.target_table, scene.target_column),
        case when scene.enabled then 'enabled' else 'disabled' end,
        null::numeric, scene.create_time, false
      from public.sys_document_number_scene scene
      join requested on requested.resource_id = scene.menu_id
    ) details(
      resource_id,
      dependency_code,
      record_id,
      target_id,
      record_no,
      record_summary,
      record_status,
      record_amount,
      created_at,
      cleanup_allowed
    )
    order by details.resource_id, details.cleanup_allowed desc, details.dependency_code,
      details.created_at desc, details.record_id;
    return;
  end if;

  if p_resource_type = 'dict_type' then
    return query
    with requested as (
      select distinct unnest(coalesce(p_resource_ids, '{}'::uuid[])) as resource_id
    )
    select
      details.resource_id,
      details.dependency_code,
      details.record_id,
      details.target_id,
      details.record_no::text,
      details.record_summary::text,
      details.record_status::text,
      details.record_amount,
      details.created_at,
      details.cleanup_allowed
    from (
      select child.parent_id, 'dict_type_child'::text, child.id, child.id,
        child.name, child.code, child.status, null::numeric, child.create_time, false
      from public.sys_dict_type child
      join requested on requested.resource_id = child.parent_id

      union all

      select dictionary.type_id, 'dict_type_item', dictionary.id, dictionary.id,
        coalesce(nullif(dictionary.label, ''), dictionary.code), dictionary.value,
        dictionary.status, null::numeric, dictionary.create_time, true
      from public.sys_dictionary dictionary
      join requested on requested.resource_id = dictionary.type_id
    ) details(
      resource_id,
      dependency_code,
      record_id,
      target_id,
      record_no,
      record_summary,
      record_status,
      record_amount,
      created_at,
      cleanup_allowed
    )
    order by details.resource_id, details.cleanup_allowed desc, details.dependency_code,
      details.created_at desc, details.record_id;
    return;
  end if;

  if p_resource_type = 'dictionary' then
    return query
    with requested as (
      select distinct unnest(coalesce(p_resource_ids, '{}'::uuid[])) as resource_id
    )
    select child.parent_id, 'dictionary_child'::text, child.id, child.id,
      coalesce(nullif(child.label, ''), child.code)::text, child.value::text,
      child.status::text, null::numeric, child.create_time, true
    from public.sys_dictionary child
    join requested on requested.resource_id = child.parent_id
    order by child.parent_id, child.create_time desc, child.id;
    return;
  end if;

  if p_resource_type = 'attachment' then
    if to_regclass('public.tms_waybill_proof') is not null then
      return query execute $query$
        with requested as (
          select distinct unnest(coalesce($1, '{}'::uuid[])) as resource_id
        )
        select proof.attachment_id, 'attachment_waybill_proof'::text, proof.id, proof.waybill_id,
          coalesce(nullif(proof.file_name, ''), proof.id::text), proof.proof_type,
          null::text, null::numeric, proof.create_time, false
        from public.tms_waybill_proof proof
        join requested on requested.resource_id = proof.attachment_id
        order by proof.attachment_id, proof.create_time desc, proof.id
      $query$ using p_resource_ids;
    end if;
    return;
  end if;

  if p_resource_type = 'order' then
    if to_regclass('public.tms_waybill') is not null then
      return query execute $query$
        with requested as (
          select distinct unnest(coalesce($1, '{}'::uuid[])) as resource_id
        )
        select waybill.order_id, 'order_waybill'::text, waybill.id, waybill.id,
          waybill.waybill_no, concat_ws(' -> ', waybill.origin_city, waybill.destination_city),
          waybill.status, waybill.freight_amount, waybill.create_time, false
        from public.tms_waybill waybill
        join requested on requested.resource_id = waybill.order_id
        order by waybill.order_id, waybill.create_time desc, waybill.id
      $query$ using p_resource_ids;
    end if;

    if to_regclass('public.tms_in_transit_expense') is not null then
      return query execute $query$
        with requested as (
          select distinct unnest(coalesce($1, '{}'::uuid[])) as resource_id
        )
        select expense.order_id, 'order_expense'::text, expense.id, expense.id,
          expense.expense_no, expense.expense_type, expense.report_status,
          expense.amount, expense.create_time, false
        from public.tms_in_transit_expense expense
        join requested on requested.resource_id = expense.order_id
        order by expense.order_id, expense.create_time desc, expense.id
      $query$ using p_resource_ids;
    end if;

    if to_regclass('public.tms_receipt_exception_work_order') is not null then
      return query execute $query$
        with requested as (
          select distinct unnest(coalesce($1, '{}'::uuid[])) as resource_id
        )
        select work_order.order_id, 'order_receipt_work_order'::text,
          work_order.id, work_order.id, work_order.work_order_no, work_order.summary,
          work_order.status, null::numeric, work_order.create_time, false
        from public.tms_receipt_exception_work_order work_order
        join requested on requested.resource_id = work_order.order_id
        order by work_order.order_id, work_order.create_time desc, work_order.id
      $query$ using p_resource_ids;
    end if;

    if to_regclass('public.tms_customer_statement_item') is not null then
      return query execute $query$
        with requested as (
          select distinct unnest(coalesce($1, '{}'::uuid[])) as resource_id
        )
        select item.order_id, 'order_statement_item'::text, item.id, item.statement_id,
          coalesce(nullif(item.order_no_snapshot, ''), item.id::text),
          concat_ws(' -> ', item.origin_station_snapshot, item.destination_station_snapshot),
          case when item.is_active then 'active' else 'inactive' end,
          item.line_amount, item.create_time, false
        from public.tms_customer_statement_item item
        join requested on requested.resource_id = item.order_id
        order by item.order_id, item.create_time desc, item.id
      $query$ using p_resource_ids;
    end if;
    return;
  end if;
end;
$_$;


ALTER FUNCTION "public"."get_governed_delete_dependency_details"("p_resource_type" "text", "p_resource_ids" "uuid"[]) OWNER TO "postgres";

