-- Name: get_notification_dispatch_scope(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_notification_dispatch_scope"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not app_private.has_permission('System:NotificationReminder:Dispatch')
     and not app_private.has_permission('System:NotificationReminder:TestChannel') then
    raise exception '缺少通知投递权限' using errcode = '42501';
  end if;
  return app_private.current_user_tenant_id();
end;
$$;


ALTER FUNCTION "public"."get_notification_dispatch_scope"() OWNER TO "postgres";

--

--
-- Name: get_notification_reminder_workspace("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_notification_reminder_workspace"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid;
begin
  if not app_private.can_view_notification_reminders() then
    raise exception '缺少查看消息提醒配置权限' using errcode = '42501';
  end if;
  v_tenant_id := app_private.notification_target_tenant(p_tenant_id);

  return jsonb_build_object(
    'tenant', (
      select jsonb_build_object(
        'id', tenant_row.id,
        'tenantCode', tenant_row.tenant_code,
        'tenantName', tenant_row.tenant_name,
        'serviceStartDate', tenant_row.service_start_date,
        'serviceEndDate', tenant_row.service_end_date,
        'status', tenant_row.status
      )
      from public.sys_tenant tenant_row where tenant_row.id = v_tenant_id
    ),
    'scenarios', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', scenario.id,
        'scenarioCode', scenario.scenario_code,
        'scenarioName', scenario.scenario_name,
        'moduleCode', scenario.module_code,
        'description', scenario.description,
        'routePath', scenario.route_path
      ) order by scenario.sort, scenario.id)
      from public.sys_notification_scenario scenario where scenario.enabled is true
    ), '[]'::jsonb),
    'rules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rule_row.id,
        'tenantId', rule_row.tenant_id,
        'scenarioId', rule_row.scenario_id,
        'scenarioCode', scenario.scenario_code,
        'scenarioName', scenario.scenario_name,
        'moduleCode', scenario.module_code,
        'ruleName', rule_row.rule_name,
        'leadDays', rule_row.lead_days,
        'repeatEveryDays', rule_row.repeat_every_days,
        'sendHour', rule_row.send_hour,
        'recipientStrategy', rule_row.recipient_strategy,
        'recipientRoleCodes', rule_row.recipient_role_codes,
        'channels', rule_row.channels,
        'enabled', rule_row.enabled,
        'updateTime', rule_row.update_time,
        'updateBy', rule_row.update_by
      ) order by scenario.sort, rule_row.lead_days desc, rule_row.rule_name)
      from public.sys_notification_rule rule_row
      join public.sys_notification_scenario scenario on scenario.id = rule_row.scenario_id
      where rule_row.tenant_id = v_tenant_id
    ), '[]'::jsonb),
    'channels', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', channel.id,
        'tenantId', channel.tenant_id,
        'channelCode', channel.channel_code,
        'providerCode', channel.provider_code,
        'enabled', channel.enabled,
        'config', channel.config,
        'secretConfigured', channel.channel_code = 'in_app' or channel.vault_secret_id is not null,
        'lastTestAt', channel.last_test_at,
        'lastTestStatus', channel.last_test_status,
        'lastError', channel.last_error,
        'updateTime', channel.update_time
      ) order by array_position(array['in_app','email','sms','dingtalk','wecom']::text[], channel.channel_code))
      from public.sys_notification_channel_config channel
      where channel.tenant_id = v_tenant_id
    ), '[]'::jsonb),
    'summary', jsonb_build_object(
      'activeSubjectCount', (
        select count(*) from public.sys_notification_subject subject
        where subject.tenant_id = v_tenant_id and subject.status = 'active'
      ),
      'dueWithin30Days', (
        select count(*) from public.sys_notification_subject subject
        where subject.tenant_id = v_tenant_id and subject.status = 'active'
          and subject.due_at >= now() and subject.due_at < now() + interval '30 days'
      ),
      'enabledRuleCount', (
        select count(*) from public.sys_notification_rule rule_row
        where rule_row.tenant_id = v_tenant_id and rule_row.enabled is true
      ),
      'enabledChannelCount', (
        select count(*) from public.sys_notification_channel_config channel
        where channel.tenant_id = v_tenant_id and channel.enabled is true
      ),
      'pendingDeliveryCount', (
        select count(*) from public.sys_notification_delivery delivery
        where delivery.tenant_id = v_tenant_id and delivery.status in ('pending', 'processing', 'failed')
      ),
      'failedDeliveryCount', (
        select count(*) from public.sys_notification_delivery delivery
        where delivery.tenant_id = v_tenant_id and delivery.status = 'failed'
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_notification_reminder_workspace"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: get_organization_list_secure("text", "uuid", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_organization_list_secure"("p_keyword" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_organization_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_record_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "tenant" "jsonb", "parent_id" "uuid", "organization_code" "text", "organization_name" "text", "organization_type" "text", "leader_user_id" "uuid", "leader" "jsonb", "status" "text", "sort" integer, "phone" "text", "email" "text", "address" "text", "description" "text", "is_system" boolean, "create_by" "text", "create_time" timestamp with time zone, "update_by" "text", "update_time" timestamp with time zone, "member_count" integer, "role_count" integer, "menu_count" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with visible_organizations as materialized (
    select organization.*
    from public.mdm_organization as organization
    where (p_record_id is null or organization.id = p_record_id)
      and (p_tenant_id is null or organization.tenant_id = p_tenant_id)
      and (p_organization_type is null or organization.organization_type = p_organization_type)
      and (p_status is null or organization.status = p_status)
      and (
        nullif(btrim(p_keyword), '') is null
        or organization.organization_name ilike '%' || btrim(p_keyword) || '%'
        or organization.organization_code ilike '%' || btrim(p_keyword) || '%'
        or organization.description ilike '%' || btrim(p_keyword) || '%'
      )
  ),
  member_counts as (
    select member.organization_id, count(*)::integer as member_count
    from public.sys_user as member
    join visible_organizations as organization on organization.id = member.organization_id
    where member.deleted_at is null
    group by member.organization_id
  ),
  role_counts as (
    select organization_role.organization_id,
      count(distinct organization_role.id)::integer as role_count,
      count(distinct role_menu.menu_id)::integer as menu_count
    from public.sys_role as organization_role
    join visible_organizations as organization on organization.id = organization_role.organization_id
    left join public.sys_role_menu as role_menu on role_menu.role_id = organization_role.id
    group by organization_role.organization_id
  )
  select
    organization.id,
    organization.tenant_id,
    case when tenant.id is null then null
      else jsonb_build_object('tenant_code', tenant.tenant_code, 'tenant_name', tenant.tenant_name)
    end as tenant,
    organization.parent_id,
    organization.organization_code,
    organization.organization_name,
    organization.organization_type,
    organization.leader_user_id,
    case when leader.id is null then null
      else jsonb_build_object(
        'id', leader.id, 'avatar', leader.avatar, 'user_name', leader.user_name,
        'nick_name', leader.nick_name, 'user_email', leader.user_email
      )
    end as leader,
    organization.status,
    organization.sort,
    organization.phone,
    organization.email,
    organization.address,
    organization.description,
    organization.is_system,
    organization.create_by,
    organization.create_time,
    organization.update_by,
    organization.update_time,
    coalesce(member_counts.member_count, 0) as member_count,
    coalesce(role_counts.role_count, 0) as role_count,
    coalesce(role_counts.menu_count, 0) as menu_count
  from visible_organizations as organization
  left join public.sys_tenant as tenant on tenant.id = organization.tenant_id
  left join public.sys_user as leader on leader.id = organization.leader_user_id
  left join member_counts on member_counts.organization_id = organization.id
  left join role_counts on role_counts.organization_id = organization.id
  order by organization.sort asc, organization.organization_name asc;
$$;


ALTER FUNCTION "public"."get_organization_list_secure"("p_keyword" "text", "p_tenant_id" "uuid", "p_organization_type" "text", "p_status" "text", "p_record_id" "uuid") OWNER TO "postgres";

--

--
-- Name: get_record_delete_dependency_details("text", "text"[], "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_record_delete_dependency_details"("p_table" "text", "p_ids" "text"[], "p_constraint" "text" DEFAULT NULL::"text") RETURNS TABLE("resource_id" "text", "source_table" "text", "record_id" "text", "target_id" "text", "record_no" "text", "record_summary" "text", "record_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
 v_target regclass; v_fk record; v_join text; v_count bigint; v_total bigint:=0;
 v_id text; v_scope text; v_parent_scope text; v_sql text;
begin
 if auth.uid() is null then raise exception '请先登录后检查关联记录' using errcode='42501'; end if;
 if cardinality(p_ids) is null or cardinality(p_ids)=0 then return; end if;
 if cardinality(p_ids)>500 then raise exception '单次最多检查 500 条记录' using errcode='22023'; end if;
 select c.oid into v_target from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relname=p_table and c.relkind in ('r','p') and c.relrowsecurity
 and exists(select 1 from pg_catalog.pg_attribute a where a.attrelid=c.oid and a.attname='id' and not a.attisdropped);
 if v_target is null then raise exception '该资料暂不支持自动检查，请联系管理员核对关联' using errcode='22023'; end if;
 v_parent_scope:='(to_jsonb(p)->>''tenant_id'' is null or app_private.tenant_in_current_read_scope((to_jsonb(p)->>''tenant_id'')::uuid))';
 for v_fk in
  select c.oid,c.conname,c.conrelid,s.relname,s.relrowsecurity,c.conkey,c.confkey
  from pg_catalog.pg_constraint c join pg_catalog.pg_class s on s.oid=c.conrelid
  join pg_catalog.pg_namespace n on n.oid=s.relnamespace
  where c.contype='f' and c.confrelid=v_target and c.confdeltype in ('a','r')
  and n.nspname='public' and (p_constraint is null or c.conname=p_constraint)
  order by c.conname
 loop
  if not v_fk.relrowsecurity then
   raise exception '关联检查无法完整执行，请联系管理员核对资料权限' using errcode='42501';
  end if;
  select string_agg(format('s.%I = p.%I',sa.attname,pa.attname),' and ' order by k.ord)
  into v_join from unnest(v_fk.conkey,v_fk.confkey) with ordinality k(sk,pk,ord)
  join pg_catalog.pg_attribute sa on sa.attrelid=v_fk.conrelid and sa.attnum=k.sk
  join pg_catalog.pg_attribute pa on pa.attrelid=v_target and pa.attnum=k.pk;
  v_scope:='(to_jsonb(s)->>''tenant_id'' is null or app_private.tenant_in_current_read_scope((to_jsonb(s)->>''tenant_id'')::uuid))';
  v_sql:=format($sql$
   select p.id::text,%L::text,
    %L || ':' || coalesce(to_jsonb(s)->>'id',md5(to_jsonb(s)::text)),
    case %L when 'mdm_bom_item' then to_jsonb(s)->>'bom_id'
      when 'mdm_accessory_processing_item' then to_jsonb(s)->>'list_id'
      else coalesce(to_jsonb(s)->>'id','') end,
    coalesce(nullif(to_jsonb(s)->>'document_no',''),nullif(to_jsonb(s)->>'work_order_no',''),
     nullif(to_jsonb(s)->>'bom_code',''),nullif(to_jsonb(s)->>'material_code',''),
     nullif(to_jsonb(s)->>'code',''),nullif(to_jsonb(s)->>'name',''),
     nullif(to_jsonb(s)->>'drawing_name',''),nullif(to_jsonb(s)->>'source_name',''),
     nullif(to_jsonb(s)->>'title',''),nullif(to_jsonb(s)->>'record_no',''),
     (select value from jsonb_each_text(to_jsonb(s)) e where e.key ~ '(_name|_no|_code)$'
 and e.key not in ('tenant_id','tenant_name','user_name','user_email') and nullif(e.value,'') is not null
 order by e.key limit 1),
     '关联记录 ' || left(coalesce(to_jsonb(s)->>'id',''),8)),
    concat_ws(' · ',
     case when %L='mdm_bom_item' then
       (select b.bom_code from public.mdm_bom b where b.id::text=to_jsonb(s)->>'bom_id'
        and app_private.tenant_in_current_read_scope(b.tenant_id)) end,
     nullif(to_jsonb(s)->>'project_name',''),nullif(to_jsonb(s)->>'material_name',''),
     nullif(to_jsonb(s)->>'description',''),
     case when to_jsonb(s)->>'row_no' is not null then '第 '||(to_jsonb(s)->>'row_no')||' 行' end),
    coalesce(to_jsonb(s)->>'status',to_jsonb(s)->>'state',''),
    coalesce(nullif(to_jsonb(s)->>'create_time',''),nullif(to_jsonb(s)->>'created_at',''))::timestamptz
   from %s s join %s p on %s
   where p.id::text=any($1) and %s and %s
   order by p.id::text,to_jsonb(s)->>'id'
  $sql$,v_fk.relname,v_fk.conname,v_fk.relname,v_fk.relname,v_fk.conrelid::regclass,v_target,v_join,v_scope,v_parent_scope);
  return query execute v_sql using p_ids;
  get diagnostics v_count = row_count; v_total:=v_total+v_count;
 end loop;
 if p_constraint is not null and v_total=0 then
  select s.relname into v_id from pg_catalog.pg_constraint c join pg_catalog.pg_class s on s.oid=c.conrelid
  where c.confrelid=v_target and c.conname=p_constraint and c.contype='f';
  if v_id is null then raise exception '关联类型已变化，请刷新页面重试' using errcode='22023'; end if;
  return query execute format(
   'select p.id::text,$2::text,$3 || '':restricted:'' || p.id::text,'''',''关联记录暂不可见'',''引用可能已变化，或当前账号无权查看。请联系有权限的人员核对后重试。'',''待核对'',null::timestamptz from %s p where p.id::text=any($1) and %s',
    v_target,v_parent_scope) using p_ids,v_id,p_constraint;
 end if;
end
$_$;


ALTER FUNCTION "public"."get_record_delete_dependency_details"("p_table" "text", "p_ids" "text"[], "p_constraint" "text") OWNER TO "postgres";

