--
-- Name: mdm_add_work_center_devices("uuid", "uuid"[], "uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid" DEFAULT NULL::"uuid", "p_point" "text" DEFAULT '无'::"text") RETURNS integer
    LANGUAGE "sql"
