ALTER FUNCTION "public"."mdm_add_work_center_devices"("p_work_center_id" "uuid", "p_equipment_ids" "uuid"[], "p_main_equipment_id" "uuid", "p_point" "text") OWNER TO "postgres";

--

--
-- Name: mdm_available_main_centers("uuid", "text", integer, integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_available_main_centers"("p_center_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT ''::"text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with recursive ancestors(id) as (
    select c.id from public.mdm_work_center c where c.main_center_id = p_center_id
    union
    select c.id from public.mdm_work_center c join ancestors a on c.main_center_id = a.id
  ), candidates as (
    select c.id,c.code,c.name from public.mdm_work_center c
    where c.tenant_id = (select app_private.current_user_tenant_id())
      and c.id is distinct from p_center_id
      and not exists (select 1 from ancestors a where a.id=c.id)
      and not exists (select 1 from public.mdm_work_center used where used.main_center_id=c.id and used.id is distinct from p_center_id)
      and (coalesce(p_keyword,'')='' or c.code ilike '%'||p_keyword||'%' or c.name ilike '%'||p_keyword||'%')
  ), page as (select * from candidates order by code,id offset greatest(p_from,0) limit least(greatest(p_to-p_from+1,1),1000))
  select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb),'total',(select count(*) from candidates));
$$;


ALTER FUNCTION "public"."mdm_available_main_centers"("p_center_id" "uuid", "p_keyword" "text", "p_from" integer, "p_to" integer) OWNER TO "postgres";

--

--
-- Name: mdm_bind_operation_template("uuid"[], "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_bind_operation_template"("p_ids" "uuid"[], "p_template_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare affected integer; expected integer;
begin
 if auth.uid() is null or not app_private.has_permission('MdmOperationTemplate:'||case when p_template_id is null then 'Unbind' else 'Bind' end) then raise exception '没有模板绑定权限' using errcode='42501'; end if;
 if cardinality(p_ids) is null or cardinality(p_ids) not between 1 and 1000 or array_position(p_ids,null) is not null then raise exception '请选择 1 至 1000 个工序'; end if;
 select count(distinct x) into expected from unnest(p_ids) x;
 update public.mdm_process_route_step set template_id=p_template_id where id=any(p_ids) and tenant_id=app_private.current_user_tenant_id(); get diagnostics affected=row_count;
 if affected<>expected then raise exception '部分工序不存在或无权访问，请刷新后重试'; end if;
 return affected;
end $$;


ALTER FUNCTION "public"."mdm_bind_operation_template"("p_ids" "uuid"[], "p_template_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_bom_structure_detail("uuid", integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_bom_structure_detail"("p_bom_id" "uuid", "p_max_depth" integer DEFAULT 8) RETURNS TABLE("node_id" "text", "parent_node_id" "text", "bom_id" "uuid", "bom_code" "text", "bom_version" "text", "bom_item_id" "uuid", "material_id" "uuid", "material_code" "text", "material_name" "text", "specification_model" "text", "material_source" "text", "special_purchase_type" "text", "is_virtual" boolean, "quantity" numeric, "component_quantity" numeric, "unit_id" "uuid", "unit_code" "text", "unit_name" "text", "depth" integer, "path" "uuid"[], "has_children" boolean, "sequence_no" integer, "scrap_rate" numeric, "mrp_enabled" boolean, "default_issue_warehouse_id" "uuid", "default_issue_warehouse_code" "text", "default_issue_warehouse_name" "text", "issue_method" "text", "backflush_method" "text", "over_issue_control_method" "text", "project_text" "text", "position_no" "text", "process_route_step_id" "uuid", "process_sequence_no" integer, "process_sequence_type" "text", "process_route_step_code" "text", "process_route_step_name" "text", "work_center_ids" "uuid"[], "work_center_code" "text", "work_center_name" "text", "operation_name" "text", "effective_from" "date", "effective_to" "date", "remark" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with recursive tree(
    node_id,
    parent_node_id,
    source_bom_id,
    item_id,
    material_id,
    quantity,
    depth,
    material_path,
    sort_path,
    tenant_id,
    force_expand
  ) as (
    select
      root_bom.id::text,
      null::text,
      root_bom.id,
      null::uuid,
      root_bom.material_id,
      1::numeric,
      0,
      array[root_bom.material_id]::uuid[],
      array[]::integer[],
      root_bom.tenant_id,
      root_material.special_purchase_type = 'virtual_part'
    from public.mdm_bom root_bom
    join public.mdm_material root_material
      on root_material.id = root_bom.material_id
     and root_material.tenant_id = root_bom.tenant_id
    where root_bom.id = p_bom_id

    union all

    select
      tree.node_id || '/' || component.id::text,
      tree.node_id,
      source_bom.id,
      component.id,
      component.component_material_id,
      tree.quantity * component.quantity / nullif(source_bom.base_quantity, 0),
      tree.depth + 1,
      tree.material_path || component.component_material_id,
      tree.sort_path || component.sequence_no,
      tree.tenant_id,
      tree.force_expand or component_material.special_purchase_type = 'virtual_part'
    from tree
    join lateral (
      select candidate.*
      from public.mdm_bom candidate
      where candidate.tenant_id = tree.tenant_id
        and (
          (tree.depth = 0 and candidate.id = p_bom_id)
          or
          (
            tree.depth > 0
            and candidate.material_id = tree.material_id
            and candidate.status in ('effective', 'review', 'changing', 'design')
          )
        )
      order by
        case
          when candidate.id = p_bom_id then -1
          when candidate.status = 'effective'
            and current_date between coalesce(candidate.effective_from, '-infinity'::date)
                                 and coalesce(candidate.effective_to, 'infinity'::date) then 0
          when candidate.status = 'effective' then 1
          when candidate.status = 'review' then 2
          when candidate.status = 'changing' then 3
          when candidate.status = 'design' then 4
          else 5
        end,
        candidate.effective_from desc nulls last,
        candidate.update_time desc,
        candidate.id
      limit 1
    ) source_bom on true
    join public.mdm_bom_item component
      on component.bom_id = source_bom.id
     and component.tenant_id = source_bom.tenant_id
    join public.mdm_material component_material
      on component_material.id = component.component_material_id
     and component_material.tenant_id = component.tenant_id
    where tree.depth < 20
      and (
        tree.depth < greatest(1, least(coalesce(p_max_depth, 8), 20))
        or tree.force_expand
      )
      and not component.component_material_id = any(tree.material_path)
  )
  select
    tree.node_id,
    tree.parent_node_id,
    tree.source_bom_id,
    source_bom.bom_code,
    source_bom.version,
    item.id,
    material.id,
    material.material_code,
    material.material_name,
    material.specification_model,
    material.material_source,
    material.special_purchase_type,
    material.special_purchase_type = 'virtual_part',
    tree.quantity,
    item.quantity,
    coalesce(item.unit_id, source_bom.base_unit_id),
    unit.unit_code,
    unit.unit_name,
    tree.depth,
    tree.material_path,
    exists (
      select 1
      from public.mdm_bom candidate
      join public.mdm_bom_item nested_item
        on nested_item.bom_id = candidate.id
       and nested_item.tenant_id = candidate.tenant_id
      where candidate.tenant_id = tree.tenant_id
        and (
          (tree.depth = 0 and candidate.id = p_bom_id)
          or
          (
            tree.depth > 0
            and candidate.material_id = tree.material_id
            and candidate.status in ('effective', 'review', 'changing', 'design')
          )
        )
    ),
    item.sequence_no,
    item.scrap_rate,
    item.mrp_enabled,
    item.default_issue_warehouse_id,
    warehouse.warehouse_code,
    warehouse.warehouse_name,
    item.issue_method,
    item.backflush_method,
    item.over_issue_control_method,
    item.project_text,
    item.position_no,
    item.process_route_step_id,
    process_sequence.sequence_no,
    process_sequence.sequence_type,
    process_step.code,
    process_step.name,
    process_step.work_center_ids,
    work_center.code,
    work_center.name,
    item.operation_name,
    item.effective_from,
    item.effective_to,
    item.remark
  from tree
  join public.mdm_bom source_bom
    on source_bom.id = tree.source_bom_id
   and source_bom.tenant_id = tree.tenant_id
  join public.mdm_material material
    on material.id = tree.material_id
   and material.tenant_id = tree.tenant_id
  left join public.mdm_bom_item item
    on item.id = tree.item_id
   and item.tenant_id = tree.tenant_id
  left join public.mdm_unit_of_measure unit
    on unit.id = coalesce(item.unit_id, source_bom.base_unit_id)
   and unit.tenant_id = tree.tenant_id
  left join public.mdm_warehouse warehouse
    on warehouse.id = item.default_issue_warehouse_id
   and warehouse.tenant_id = tree.tenant_id
  left join public.mdm_process_route_step process_step
    on process_step.id = item.process_route_step_id
   and process_step.tenant_id = tree.tenant_id
  left join public.mdm_process_route_sequence process_sequence
    on process_sequence.id = process_step.sequence_id
   and process_sequence.tenant_id = tree.tenant_id
  left join public.mdm_work_center work_center
    on work_center.id = process_step.work_center_id
   and work_center.tenant_id = tree.tenant_id
  order by tree.sort_path, tree.depth;
$$;


ALTER FUNCTION "public"."mdm_bom_structure_detail"("p_bom_id" "uuid", "p_max_depth" integer) OWNER TO "postgres";

