--

--
-- Name: mdm_delete_personnel_common_work_centers("uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_delete_personnel_common_work_centers"("p_personnel_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tenant_value uuid;
  normalized_ids uuid[];
  affected_rows integer;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再删除常用工作中心配置' using errcode = '42501';
  end if;
  if app_private.has_permission('MdmPersonnelWorkCenter:Delete') is not true then
    raise exception '当前账号没有删除常用工作中心配置的权限' using errcode = '42501';
  end if;

  tenant_value := app_private.current_user_tenant_id();
  normalized_ids := array(
    select distinct personnel_id
    from unnest(coalesce(p_personnel_ids, array[]::uuid[])) personnel_id
    where personnel_id is not null
  );

  delete from public.mdm_personnel_common_work_center configured
  where configured.tenant_id = tenant_value
    and configured.personnel_id = any(normalized_ids);
  get diagnostics affected_rows = row_count;
  return affected_rows;
end;
$$;


ALTER FUNCTION "public"."mdm_delete_personnel_common_work_centers"("p_personnel_ids" "uuid"[]) OWNER TO "postgres";

