--
-- Name: mdm_delete_shift_schedule_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_delete_shift_schedule_secure"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:Delete') then raise exception '没有排班删除权限' using errcode='42501'; end if;
 update public.mdm_shift_schedule set deleted_at=now(),deleted_by=coalesce((select u.user_email from public.sys_user u where u.auth_user_id=auth.uid() limit 1),auth.uid()::text) where id=p_id and deleted_at is null and app_private.tenant_in_current_read_scope(tenant_id);
 if not found then raise exception '排班不存在或不可删除'; end if;
end $$;


