--

--
-- Name: mdm_delete_statutory_holidays_secure("uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_delete_statutory_holidays_secure"("p_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_count integer; begin
  if not app_private.has_permission('MdmStatutoryHoliday:Delete') then
    raise exception '当前账号没有删除法定节假日的权限' using errcode = '42501';
  end if;
  delete from public.smis_statutory_holiday
  where (app_private.is_platform_super() or tenant_id = app_private.auth_user_tenant_id()) and id = any(p_ids);
  get diagnostics v_count = row_count;
  return v_count;
end; $$;


