--

--
-- Name: mdm_get_my_shift_schedule_secure("date", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_get_my_shift_schedule_secure"("p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid;
  v_profiles jsonb := '[]'::jsonb;
  v_schedules jsonb := '[]'::jsonb;
  v_holiday_dates jsonb := '[]'::jsonb;
begin
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date then
    raise exception '请选择有效的排班日期范围' using errcode='22023';
  end if;
  if p_end_date-p_start_date>62 then
    raise exception '单次最多查看 63 天排班' using errcode='22023';
  end if;
  if (select auth.uid()) is null or not app_private.can_access_business_menu('MdmMyShiftSchedule') then
    raise exception '当前账号没有查看“我的排班”的权限' using errcode='42501';
  end if;
  v_tenant_id := app_private.auth_user_tenant_id();
  if v_tenant_id is null then
    raise exception '当前账号未关联有效租户' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(profile_row) order by profile_row."departmentName",profile_row."employeeNo"),'[]'::jsonb)
  into v_profiles
  from (
    select personnel.id as "personnelId",personnel.employee_id as "employeeId",personnel.name as "employeeName",
      personnel.employee_no as "employeeNo",personnel.job_title as "jobTitle",personnel.avatar_url as "avatarUrl",
      department.id as "departmentId",department.name as "departmentName",department.code as "departmentCode",department.factory
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.tenant_id=account.tenant_id and personnel.employee_id=account.hr_employee_id
    join public.mdm_production_department department on department.tenant_id=personnel.tenant_id and department.id=personnel.department_id
    where account.auth_user_id=(select auth.uid()) and account.tenant_id=v_tenant_id and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null
  ) profile_row;

  select coalesce(jsonb_agg(to_jsonb(schedule_row) order by schedule_row."startDate",schedule_row."shiftStartTime"),'[]'::jsonb)
  into v_schedules
  from (
    select distinct on (schedule.id)
      schedule.id,department.id as "departmentId",department.name as "departmentName",department.code as "departmentCode",
      department.factory,pattern.name as "patternName",pattern.color as "patternColor",schedule.shift_name as "shiftName",
      to_char(schedule.shift_start_time,'HH24:MI') as "shiftStartTime",to_char(schedule.shift_end_time,'HH24:MI') as "shiftEndTime",
      schedule.date_mode as "dateMode",to_char(schedule.start_date,'YYYY-MM-DD') as "startDate",
      case when schedule.end_date is null then null else to_char(schedule.end_date,'YYYY-MM-DD') end as "endDate",
      coalesce(to_jsonb(schedule)->'weekdays','[0,1,2,3,4,5,6]'::jsonb) as weekdays,
      coalesce((to_jsonb(schedule)->>'include_statutory_holidays')::boolean,true) as "includeStatutoryHolidays",schedule.note
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.tenant_id=account.tenant_id and personnel.employee_id=account.hr_employee_id
    join public.mdm_shift_schedule_member member on member.tenant_id=personnel.tenant_id and member.personnel_id=personnel.id
    join public.mdm_shift_schedule schedule on schedule.tenant_id=member.tenant_id and schedule.id=member.schedule_id
    join public.mdm_production_department department on department.tenant_id=schedule.tenant_id and department.id=schedule.department_id
    join public.mdm_production_shift_pattern pattern on pattern.tenant_id=schedule.tenant_id and pattern.id=schedule.pattern_id
    where account.auth_user_id=(select auth.uid()) and account.tenant_id=v_tenant_id and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null and schedule.deleted_at is null
      and app_private.mdm_shift_schedule_range(schedule.start_date,schedule.end_date) && daterange(p_start_date,p_end_date,'[]')
    order by schedule.id,schedule.start_date,schedule.shift_start_time
  ) schedule_row;

  select coalesce(jsonb_agg(to_char(holiday_row.work_date,'YYYY-MM-DD') order by holiday_row.work_date),'[]'::jsonb)
  into v_holiday_dates
  from (
    select distinct holiday.work_date
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.tenant_id=account.tenant_id and personnel.employee_id=account.hr_employee_id
    join public.mdm_production_department department on department.tenant_id=personnel.tenant_id and department.id=personnel.department_id
    cross join lateral app_private.mdm_non_working_statutory_holiday_dates(
      department.id,p_start_date,p_end_date,v_tenant_id
    ) holiday
    where account.auth_user_id=(select auth.uid()) and account.tenant_id=v_tenant_id and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null
  ) holiday_row;

  return jsonb_build_object('profiles',v_profiles,'schedules',v_schedules,'holidayDates',v_holiday_dates);
end;
$$;


ALTER FUNCTION "public"."mdm_get_my_shift_schedule_secure"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

--

--
-- Name: mdm_list_personnel_common_work_centers("uuid"[], "text", boolean, integer, integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_personnel_common_work_centers"("p_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_keyword" "text" DEFAULT NULL::"text", "p_only_unconfigured" boolean DEFAULT false, "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tenant_value uuid;
  normalized_keyword text := nullif(btrim(p_keyword), '');
  safe_from integer := greatest(coalesce(p_from, 0), 0);
  safe_to integer;
  result_value jsonb;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再查看常用工作中心配置' using errcode = '42501';
  end if;
  if app_private.has_permission('MdmPersonnelWorkCenter:View') is not true then
    raise exception '当前账号没有查看人员工作中心配置的权限' using errcode = '42501';
  end if;

  tenant_value := app_private.current_user_tenant_id();
  safe_to := least(greatest(coalesce(p_to, safe_from + 19), safe_from), safe_from + 999);

  with filtered as materialized (
    select person.*
    from public.mdm_production_personnel person
    where app_private.tenant_in_current_read_scope(person.tenant_id)
      and person.enabled is true
      and (
        p_department_ids is null
        or cardinality(p_department_ids) = 0
        or person.department_id = any(p_department_ids)
      )
      and (
        normalized_keyword is null
        or person.name ilike '%' || normalized_keyword || '%'
        or person.employee_no ilike '%' || normalized_keyword || '%'
        or person.phone ilike '%' || normalized_keyword || '%'
      )
      and (
        p_only_unconfigured is not true
        or not exists (
          select 1
          from public.mdm_personnel_common_work_center configured
          where configured.tenant_id = person.tenant_id
            and configured.personnel_id = person.id
        )
      )
  ),
  paged as (
    select person.*
    from filtered person
    order by person.sort, person.employee_no, person.id
    offset safe_from
    limit safe_to - safe_from + 1
  )
  select jsonb_build_object(
    'records', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', person.id,
          'tenantId', person.tenant_id,
          'departmentId', person.department_id,
          'department', jsonb_build_object(
            'id', department.id,
            'name', department.name,
            'code', department.code
          ),
          'name', person.name,
          'employeeNo', person.employee_no,
          'phone', person.phone,
          'jobTitle', person.job_title,
          'avatarUrl', person.avatar_url,
          'commonWorkCenters', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', center.id,
                'code', center.code,
                'name', center.name,
                'departmentId', center.department_id,
                'departmentName', center_department.name
              )
              order by center.sort, center.code, center.id
            )
            from public.mdm_personnel_common_work_center configured
            join public.mdm_work_center center
              on center.tenant_id = configured.tenant_id
             and center.id = configured.work_center_id
            join public.mdm_production_department center_department
              on center_department.tenant_id = center.tenant_id
             and center_department.id = center.department_id
            where configured.tenant_id = person.tenant_id
              and configured.personnel_id = person.id
          ), '[]'::jsonb)
        )
        order by person.sort, person.employee_no, person.id
      )
      from paged person
      join public.mdm_production_department department
        on department.tenant_id = person.tenant_id
       and department.id = person.department_id
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result_value;

  return result_value;
end;
$$;


ALTER FUNCTION "public"."mdm_list_personnel_common_work_centers"("p_department_ids" "uuid"[], "p_keyword" "text", "p_only_unconfigured" boolean, "p_from" integer, "p_to" integer) OWNER TO "postgres";

--

--
-- Name: mdm_list_production_calendar_day_settings_secure("uuid", "date", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_production_calendar_day_settings_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; v_result jsonb;
begin
 if auth.uid() is null or not app_private.has_permission('MdmFactoryCalendar:View') then raise exception '没有工厂日历查看权限' using errcode='42501'; end if;
 if p_start_date is null or p_end_date is null or p_end_date<p_start_date or p_end_date-p_start_date>3660 then raise exception '请选择有效日期区间' using errcode='22023'; end if;
 select d.tenant_id into v_tenant from public.mdm_production_department d where d.id=p_department_id and app_private.tenant_in_current_read_scope(d.tenant_id);
 if v_tenant is null then raise exception '无权查看该生产组织' using errcode='42501'; end if;
 with recursive production_scope as (
 select d.id,d.parent_id,d.organization_id,0 as depth,array[d.id] as visited from public.mdm_production_department d where d.id=p_department_id and d.tenant_id=v_tenant
 union all
 select d.id,d.parent_id,d.organization_id,s.depth+1,s.visited||d.id from public.mdm_production_department d join production_scope s on d.id=s.parent_id where d.tenant_id=v_tenant and not d.id=any(s.visited)
 ), linked_org as (
 select organization_id from production_scope where organization_id is not null order by depth limit 1
 ), org_scope as (
 select o.id,o.parent_id,0 as depth,array[o.id] as visited from public.mdm_organization o join linked_org l on l.organization_id=o.id where o.tenant_id=v_tenant
 union all
 select o.id,o.parent_id,s.depth+1,s.visited||o.id from public.mdm_organization o join org_scope s on o.id=s.parent_id where o.tenant_id=v_tenant and not o.id=any(s.visited)
 ), candidates as (
 select s.id,s.work_date,s.day_type,'manual'::text as source,null::uuid as holiday_id,null::text as holiday_name,-1 as priority,s.update_time from public.mdm_production_calendar_day_setting s where s.tenant_id=v_tenant and s.department_id=p_department_id and s.work_date between p_start_date and p_end_date
 union all
 select h.id,dates.d::date,
 case h.holiday_type when 'compensatory_leave' then 'rest_day' when 'makeup_work' then 'work_day' else 'statutory_holiday' end,
 'statutory_holiday',h.id,
 case h.holiday_type when 'compensatory_leave' then '调休' when 'makeup_work' then '补班' when 'new_year' then '元旦' when 'spring_festival' then '春节' when 'qingming' then '清明节' when 'labor_day' then '劳动节' when 'dragon_boat' then '端午节' when 'mid_autumn' then '中秋节' when 'national_day' then '国庆节' else h.holiday_type end,
 o.depth,h.update_time
 from public.smis_statutory_holiday h join org_scope o on o.id=h.organization_id
 cross join lateral generate_series(greatest(h.start_date,p_start_date)::timestamp,least(h.end_date,p_end_date)::timestamp,interval '1 day') dates(d)
 where h.tenant_id=v_tenant and h.start_date<=p_end_date and h.end_date>=p_start_date
 ), chosen as (select distinct on(work_date) * from candidates order by work_date,priority,update_time desc,id)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'departmentId',p_department_id,'workDate',work_date,'dayType',day_type,'source',source,'holidayId',holiday_id,'holidayName',holiday_name) order by work_date),'[]'::jsonb) into v_result from chosen;
 return v_result;
end $$;


ALTER FUNCTION "public"."mdm_list_production_calendar_day_settings_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

