--

--
-- Name: mdm_list_production_equipment_v2_secure(integer, integer, "text", "uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_production_equipment_v2_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_department_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1);
  v_keyword text := nullif(btrim(coalesce(p_keyword, '')), '');
  v_records jsonb;
  v_total bigint;
  v_references jsonb;
  v_overview jsonb;
begin
  if auth.uid() is null then raise exception '请先登录后再查看生产设备' using errcode = '42501'; end if;
  if not app_private.has_permission('MdmProductionEquipment:View') then
    raise exception '当前账号没有查看生产设备的权限' using errcode = '42501';
  end if;

  with recursive category_scope as (
    select id from public.mdm_equipment_category
    where id = p_category_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_equipment_category child
    join category_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  ), department_scope as (
    select id from public.mdm_production_department
    where id = p_department_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_production_department child
    join department_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  ), location_scope as (
    select id from public.mdm_storage_location
    where id = p_location_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_storage_location child
    join location_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  ), filtered as (
    select equipment.*
    from public.mdm_equipment equipment
    where app_private.tenant_in_current_read_scope(equipment.tenant_id)
      and (p_category_id is null or equipment.category_id in (select id from category_scope))
      and (p_department_id is null or equipment.production_department_id in (select id from department_scope))
      and (p_location_id is null or equipment.location_id in (select id from location_scope))
      and (p_status is null or equipment.status = p_status)
      and (
        v_keyword is null
        or equipment.equipment_code ilike '%' || v_keyword || '%'
        or equipment.equipment_name ilike '%' || v_keyword || '%'
        or coalesce(equipment.model, '') ilike '%' || v_keyword || '%'
        or coalesce(equipment.factory_no, '') ilike '%' || v_keyword || '%'
      )
  )
  select count(*) into v_total from filtered;

  with recursive category_scope as (
    select id from public.mdm_equipment_category
    where id = p_category_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_equipment_category child
    join category_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  ), department_scope as (
    select id from public.mdm_production_department
    where id = p_department_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_production_department child
    join department_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  ), location_scope as (
    select id from public.mdm_storage_location
    where id = p_location_id and app_private.tenant_in_current_read_scope(tenant_id)
    union all
    select child.id from public.mdm_storage_location child
    join location_scope parent on child.parent_id = parent.id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
  )
  select coalesce(jsonb_agg(record order by record->>'equipmentName', record->>'equipmentCode'), '[]'::jsonb)
  into v_records
  from (
    select jsonb_build_object(
      'id', e.id, 'tenantId', e.tenant_id, 'tenantName', tenant.tenant_name,
      'equipmentCode', e.equipment_code, 'equipmentName', e.equipment_name,
      'photoUrl', e.photo_url,
      'categoryId', e.category_id, 'categoryName', category.category_name,
      'productionDepartmentId', e.production_department_id, 'departmentName', department.name,
      'locationId', e.location_id, 'locationName', location.location_name,
      'workCenterId', e.work_center_id, 'workCenterCode', center.code, 'workCenterName', center.name,
      'responsibleEmployeeId', e.responsible_employee_id, 'responsibleName', employee.employee_name,
      'supplierId', e.supplier_id, 'supplierName', supplier.supplier_name,
      'equipmentBrand', e.equipment_brand, 'model', e.model, 'factoryNo', e.factory_no,
      'manufacturer', e.manufacturer, 'fixedAssetNo', e.fixed_asset_no,
      'manufactureDate', e.manufacture_date, 'installationDate', e.installation_date,
      'acceptanceDate', e.acceptance_date, 'enableDate', e.enable_date,
      'trafficLightCardNo', e.traffic_light_card_no, 'andonBoxNo', e.andon_box_no,
      'pulseIntervalSeconds', e.pulse_interval_seconds,
      'standardUtilization', e.standard_utilization,
      'syncWorkCenter', e.sync_work_center, 'operationStatus', e.operation_status,
      'status', e.status, 'remark', e.remark, 'sort', e.sort,
      'createBy', e.create_by, 'createTime', e.create_time,
      'updateBy', e.update_by, 'updateTime', e.update_time
    ) record
    from public.mdm_equipment e
    join public.sys_tenant tenant on tenant.id = e.tenant_id
    join public.mdm_equipment_category category
      on category.id = e.category_id and category.tenant_id = e.tenant_id
    left join public.mdm_production_department department
      on department.id = e.production_department_id and department.tenant_id = e.tenant_id
    left join public.mdm_storage_location location
      on location.id = e.location_id and location.tenant_id = e.tenant_id
    left join public.mdm_work_center center
      on center.id = e.work_center_id and center.tenant_id = e.tenant_id
    left join public.mdm_employee employee
      on employee.id = e.responsible_employee_id and employee.tenant_id = e.tenant_id
    left join public.mdm_supplier supplier
      on supplier.id = e.supplier_id and supplier.tenant_id = e.tenant_id
    where app_private.tenant_in_current_read_scope(e.tenant_id)
      and (p_category_id is null or e.category_id in (select id from category_scope))
      and (p_department_id is null or e.production_department_id in (select id from department_scope))
      and (p_location_id is null or e.location_id in (select id from location_scope))
      and (p_status is null or e.status = p_status)
      and (
        v_keyword is null
        or e.equipment_code ilike '%' || v_keyword || '%'
        or e.equipment_name ilike '%' || v_keyword || '%'
        or coalesce(e.model, '') ilike '%' || v_keyword || '%'
        or coalesce(e.factory_no, '') ilike '%' || v_keyword || '%'
      )
    order by e.sort, e.equipment_name, e.equipment_code
    offset v_from limit v_limit
  ) page;

  select jsonb_build_object(
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'tenantId', tenant_id, 'parentId', parent_id,
        'code', category_code, 'name', category_name
      ) order by sort, category_name)
      from public.mdm_equipment_category
      where app_private.tenant_in_current_read_scope(tenant_id) and status = 'enabled'
    ), '[]'::jsonb),
    'departments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'tenantId', tenant_id, 'parentId', parent_id,
        'code', code, 'name', name, 'organizationId', organization_id, 'kind', kind
      ) order by sort, name)
      from public.mdm_production_department
      where app_private.tenant_in_current_read_scope(tenant_id) and enabled
    ), '[]'::jsonb),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'tenantId', tenant_id, 'parentId', parent_id,
        'code', location_code, 'name', location_name
      ) order by location_name)
      from public.mdm_storage_location
      where app_private.tenant_in_current_read_scope(tenant_id) and status = 'enabled'
    ), '[]'::jsonb),
    'workCenters', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'tenantId', tenant_id, 'departmentId', department_id,
        'code', code, 'name', name
      ) order by sort, name)
      from public.mdm_work_center
      where app_private.tenant_in_current_read_scope(tenant_id)
    ), '[]'::jsonb),
    'suppliers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'tenantId', tenant_id, 'code', supplier_code, 'name', supplier_name
      ) order by supplier_name)
      from public.mdm_supplier
      where app_private.tenant_in_current_read_scope(tenant_id)
    ), '[]'::jsonb)
  ) into v_references;

  select jsonb_build_object(
    'total', count(*),
    'enabled', count(*) filter (where status = 'enabled'),
    'connected', count(*) filter (where traffic_light_card_no is not null or andon_box_no is not null),
    'unassigned', count(*) filter (where production_department_id is null)
  )
  into v_overview
  from public.mdm_equipment
  where app_private.tenant_in_current_read_scope(tenant_id);

  return jsonb_build_object(
    'records', v_records, 'total', v_total,
    'references', v_references, 'overview', v_overview
  );
end
$$;


ALTER FUNCTION "public"."mdm_list_production_equipment_v2_secure"("p_from" integer, "p_to" integer, "p_keyword" "text", "p_category_id" "uuid", "p_department_id" "uuid", "p_location_id" "uuid", "p_status" "text") OWNER TO "postgres";

