    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select case when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('id',d.id,'tenantId',d.tenant_id,'organizationId',d.organization_id,'parentId',d.parent_id,'name',d.name,'code',d.code,'factory',d.factory,'kind',d.kind,'sort',d.sort,'textColor',d.text_color,'tagType',d.tag_type,'enabled',d.enabled,'remark',d.remark) order by d.sort,d.code),'[]'::jsonb) end from public.mdm_production_department d where app_private.tenant_in_current_read_scope(d.tenant_id) $$;


