--

--
-- Name: mdm_list_shift_schedule_holiday_dates_secure("uuid", "date", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_shift_schedule_holiday_dates_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; v_result jsonb;
begin
  if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then
    raise exception '没有排班查看权限' using errcode='42501';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date
    or p_end_date-p_start_date>3660 then
    raise exception '请选择有效日期区间' using errcode='22023';
  end if;
  select d.tenant_id into v_tenant
  from public.mdm_production_department d
  where d.id=p_department_id and app_private.tenant_in_current_read_scope(d.tenant_id);
  if v_tenant is null then raise exception '无权查看该生产组织' using errcode='42501'; end if;
  select coalesce(jsonb_agg(to_char(h.work_date,'YYYY-MM-DD') order by h.work_date),'[]'::jsonb)
  into v_result
  from app_private.mdm_non_working_statutory_holiday_dates(
    p_department_id,p_start_date,p_end_date,v_tenant
  ) h;
  return v_result;
end
$$;


ALTER FUNCTION "public"."mdm_list_shift_schedule_holiday_dates_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

