CREATE OR REPLACE FUNCTION "public"."mdm_list_shift_schedule_patterns_secure"("p_department_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select case when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('id',p.id,'tenantId',p.tenant_id,'departmentId',p.department_id,'name',p.name,'description',p.description,'sort',p.sort,'color',p.color,'shifts',p.shifts) order by p.sort,p.name),'[]'::jsonb) end from public.mdm_production_shift_pattern p where p.department_id=p_department_id and app_private.tenant_in_current_read_scope(p.tenant_id) $$;


