--

--
-- Name: mdm_list_shift_schedule_people_secure("uuid", integer, integer, "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_shift_schedule_people_secure"("p_department_id" "uuid", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 9, "p_keyword" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; v_result jsonb;
begin
 if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then raise exception '没有排班查看权限' using errcode='42501'; end if;
 select tenant_id into v_tenant from public.mdm_production_department where id=p_department_id and app_private.tenant_in_current_read_scope(tenant_id);
 if v_tenant is null then raise exception '部门或产线不可访问'; end if;
 if p_from<0 or p_to<p_from or p_to-p_from>199 then raise exception '分页范围无效'; end if;
 with recursive department_scope as (select id from public.mdm_production_department where id=p_department_id and tenant_id=v_tenant union all select d.id from public.mdm_production_department d join department_scope s on d.parent_id=s.id where d.tenant_id=v_tenant), filtered as (select p.*,d.name department_name,d.code department_code,count(*) over() total from public.mdm_production_personnel p join department_scope scope on scope.id=p.department_id join public.mdm_production_department d on d.id=p.department_id where p.tenant_id=v_tenant and p.enabled and (p_keyword is null or concat_ws(' ',p.name,p.employee_no,p.job_title) ilike '%'||p_keyword||'%') order by p.employee_no,p.id offset p_from limit p_to-p_from+1)
 select jsonb_build_object('records',coalesce(jsonb_agg(jsonb_build_object('id',f.id,'tenantId',f.tenant_id,'departmentId',f.department_id,'employeeName',f.name,'employeeNo',f.employee_no,'phone',f.phone,'jobTitle',f.job_title,'avatarUrl',f.avatar_url,'employmentStatus',case when f.enabled then 'active' else 'inactive' end,'organization',jsonb_build_object('id',f.department_id,'organizationCode',f.department_code,'organizationName',f.department_name),'organizationName',f.department_name) order by f.employee_no),'[]'::jsonb),'total',coalesce(max(f.total),0)) into v_result from filtered f;
 return v_result;
end $$;


ALTER FUNCTION "public"."mdm_list_shift_schedule_people_secure"("p_department_id" "uuid", "p_from" integer, "p_to" integer, "p_keyword" "text") OWNER TO "postgres";

--

--
-- Name: mdm_list_shift_schedules_secure("uuid", "date", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_shift_schedules_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
select case
  when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb
  else coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'tenantId',s.tenant_id,'departmentId',s.department_id,
    'patternId',s.pattern_id,'patternName',p.name,'patternColor',p.color,
    'shiftIndex',s.shift_index,'shiftName',s.shift_name,
    'shiftStartTime',to_char(s.shift_start_time,'HH24:MI'),
    'shiftEndTime',to_char(s.shift_end_time,'HH24:MI'),
    'dateMode',s.date_mode,'startDate',to_char(s.start_date,'YYYY-MM-DD'),
    'endDate',case when s.end_date is null then null else to_char(s.end_date,'YYYY-MM-DD') end,
    'weekdays',to_jsonb(s.weekdays),
    'includeStatutoryHolidays',s.include_statutory_holidays,
    'note',s.note,'memberCount',coalesce(m.member_count,0),
    'members',coalesce(m.members,'[]'::jsonb),
    'createTime',s.create_time,'updateTime',s.update_time
  ) order by s.start_date,s.shift_index,s.create_time),'[]'::jsonb)
end
from public.mdm_shift_schedule s
join public.mdm_production_shift_pattern p
  on p.id=s.pattern_id and p.tenant_id=s.tenant_id
left join lateral (
  select count(*)::integer member_count,
    jsonb_agg(jsonb_build_object(
      'id',person.id,'tenantId',person.tenant_id,'departmentId',person.department_id,
      'employeeName',person.name,'employeeNo',person.employee_no,'phone',person.phone,
      'jobTitle',person.job_title,'avatarUrl',person.avatar_url,
      'employmentStatus',case when person.enabled then 'active' else 'inactive' end,
      'organization',jsonb_build_object(
        'id',d.id,'organizationCode',d.code,'organizationName',d.name
      )
    ) order by person.employee_no) members
  from public.mdm_shift_schedule_member sm
  join public.mdm_production_personnel person
    on person.id=sm.personnel_id and person.tenant_id=sm.tenant_id
  join public.mdm_production_department d
    on d.id=person.department_id and d.tenant_id=person.tenant_id
  where sm.schedule_id=s.id
) m on true
where s.department_id=p_department_id and s.deleted_at is null
  and app_private.tenant_in_current_read_scope(s.tenant_id)
  and p_start_date<=p_end_date
  and app_private.mdm_shift_schedule_range(s.start_date,s.end_date)
      && daterange(p_start_date,p_end_date,'[]')
$$;


ALTER FUNCTION "public"."mdm_list_shift_schedules_secure"("p_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

--

--
-- Name: mdm_list_statutory_holidays_secure(integer, integer, "uuid", "text", integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_list_statutory_holidays_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 999, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_holiday_type" "text" DEFAULT NULL::"text", "p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_records jsonb;
  v_total bigint;
begin
  if not (app_private.is_platform_super() or app_private.has_permission('MdmStatutoryHoliday:View')) then
    raise exception '当前账号没有查看法定节假日的权限' using errcode = '42501';
  end if;

  select count(*) into v_total
  from public.smis_statutory_holiday holiday
  where (app_private.current_read_tenant_id() is null or holiday.tenant_id = app_private.current_read_tenant_id())
    and (p_organization_id is null or holiday.organization_id = p_organization_id)
    and (p_holiday_type is null or holiday.holiday_type = p_holiday_type)
    and (p_year is null or holiday.start_date <= make_date(p_year, 12, 31)
      and holiday.end_date >= make_date(p_year, 1, 1));

  select coalesce(jsonb_agg(to_jsonb(record_row) order by record_row."startDate", record_row."createTime"), '[]'::jsonb)
  into v_records
  from (
    select holiday.id,
      holiday.organization_id as "organizationId",
      holiday.holiday_type as "holidayType",
      holiday.start_date as "startDate",
      holiday.end_date as "endDate",
      holiday.remark,
      holiday.create_time as "createTime",
      holiday.update_time as "updateTime",
      jsonb_build_object(
        'id', organization.id,
        'organizationCode', organization.organization_code,
        'organizationName', organization.organization_name,
        'organizationType', organization.organization_type
      ) as organization
    from public.smis_statutory_holiday holiday
    join public.mdm_organization organization
      on organization.id = holiday.organization_id and organization.tenant_id = holiday.tenant_id
    where (app_private.current_read_tenant_id() is null or holiday.tenant_id = app_private.current_read_tenant_id())
      and (p_organization_id is null or holiday.organization_id = p_organization_id)
      and (p_holiday_type is null or holiday.holiday_type = p_holiday_type)
      and (p_year is null or holiday.start_date <= make_date(p_year, 12, 31)
        and holiday.end_date >= make_date(p_year, 1, 1))
    order by holiday.start_date, holiday.create_time
    offset greatest(coalesce(p_from, 0), 0)
    limit greatest(coalesce(p_to, 999) - greatest(coalesce(p_from, 0), 0) + 1, 0)
  ) record_row;

  return jsonb_build_object('records', v_records, 'total', v_total);
end;
$$;


ALTER FUNCTION "public"."mdm_list_statutory_holidays_secure"("p_from" integer, "p_to" integer, "p_organization_id" "uuid", "p_holiday_type" "text", "p_year" integer) OWNER TO "postgres";

--

--
-- Name: mdm_process_route_material_options("uuid", "text", "uuid", integer, integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_process_route_material_options"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT ''::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 9) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_term text := replace(replace(replace(coalesce(p_keyword, ''), '\\', '\\\\'), '%', '\\%'), '_', '\\_');
begin
  if auth.uid() is null or not app_private.has_permission('MdmProcessRoute:View') then
    raise exception '没有查看工艺路线物料参选数据权限' using errcode = '42501';
  end if;
  if p_from < 0 or p_to < p_from or p_to - p_from > 999 then
    raise exception '分页范围无效';
  end if;
  if p_tenant_id is not null and not app_private.tenant_in_current_read_scope(p_tenant_id) then
    raise exception '无权访问目标租户数据' using errcode = '42501';
  end if;

  with recursive selected_categories as (
    select category.id
    from public.mdm_material_category category
    where category.id = p_category_id
      and app_private.tenant_in_current_read_scope(category.tenant_id)
      and (p_tenant_id is null or category.tenant_id = p_tenant_id)
    union all
    select child.id
    from public.mdm_material_category child
    join selected_categories parent on parent.id = child.parent_id
    where app_private.tenant_in_current_read_scope(child.tenant_id)
      and (p_tenant_id is null or child.tenant_id = p_tenant_id)
  ),
  source as (
    select
      material.material_code,
      jsonb_build_object(
        'id', material.id,
        'categoryId', material.category_id,
        'materialCode', material.material_code,
        'materialName', material.material_name,
        'specificationModel', material.specification_model,
        'drawingNo', material.drawing_no,
        'materialComposition', material.material_composition,
        'brand', material.brand,
        'materialType', material.material_type,
        'materialSource', material.material_source,
        'specialPurchaseType', material.special_purchase_type,
        'productionUnitId', material.production_unit_id,
        'category', jsonb_build_object(
          'id', category.id,
          'categoryCode', category.category_code,
          'categoryName', category.category_name
        ),
        'materialTypeRef', case
          when material_type.id is null then null
          else jsonb_build_object(
            'id', material_type.id,
            'typeCode', material_type.type_code,
            'typeName', material_type.type_name
          )
        end
      ) as record
    from public.mdm_material material
    join public.mdm_material_category category on category.id = material.category_id
    left join public.mdm_material_type material_type on material_type.id = material.material_type_id
    where app_private.tenant_in_current_read_scope(material.tenant_id)
      and (p_tenant_id is null or material.tenant_id = p_tenant_id)
      and (
        p_category_id is null
        or material.category_id in (select id from selected_categories)
      )
      and (
        material.material_code ilike '%' || v_term || '%'
        or material.material_name ilike '%' || v_term || '%'
        or coalesce(material.specification_model, '') ilike '%' || v_term || '%'
        or coalesce(material.drawing_no, '') ilike '%' || v_term || '%'
        or coalesce(material.material_composition, '') ilike '%' || v_term || '%'
        or coalesce(material.brand, '') ilike '%' || v_term || '%'
      )
  ),
  page as (
    select record
    from source
    order by material_code
    limit p_to - p_from + 1
    offset p_from
  )
  select jsonb_build_object(
    'records', coalesce((select jsonb_agg(page.record) from page), '[]'::jsonb),
    'total', (select count(*) from source)
  )
  into v_result;

  return v_result;
end
$$;


ALTER FUNCTION "public"."mdm_process_route_material_options"("p_tenant_id" "uuid", "p_keyword" "text", "p_category_id" "uuid", "p_from" integer, "p_to" integer) OWNER TO "postgres";

