--

--
-- Name: mdm_reference_shift_patterns("uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_reference_shift_patterns"("p_source_department_id" "uuid", "p_target_department_id" "uuid") RETURNS integer
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select app_private.reference_production_shift_patterns(p_source_department_id, p_target_department_id)
$$;


ALTER FUNCTION "public"."mdm_reference_shift_patterns"("p_source_department_id" "uuid", "p_target_department_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_replace_production_calendar_range_secure("uuid", "uuid", "date", "date", smallint[], boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_replace_production_calendar_range_secure"("p_department_id" "uuid", "p_pattern_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_weekdays" smallint[], "p_include_statutory_holidays" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; v_removed integer:=0; v_scheduled integer:=0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmFactoryCalendar:Configure') then
    raise exception '没有排班设置权限' using errcode='42501';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date
    or p_end_date-p_start_date>3659 then
    raise exception '请选择有效日期范围，最多可设置 3660 天';
  end if;
  if p_start_date<=(current_timestamp at time zone 'Asia/Shanghai')::date then
    raise exception '只能设置明天及以后的生产日历';
  end if;
  if cardinality(p_weekdays) is null or cardinality(p_weekdays) not between 1 and 7
    or array_position(p_weekdays,null) is not null
    or exists(select 1 from unnest(p_weekdays) weekday where weekday not between 0 and 6) then
    raise exception '请至少选择一个有效的参与星期';
  end if;
  select d.tenant_id into v_tenant
  from public.mdm_production_department d
  where d.id=p_department_id and d.enabled
    and app_private.tenant_in_current_read_scope(d.tenant_id);
  if v_tenant is null then raise exception '部门或产线不可访问' using errcode='42501'; end if;
  if not exists(
    select 1 from public.mdm_production_shift_pattern p
    where p.id=p_pattern_id and p.department_id=p_department_id and p.tenant_id=v_tenant
  ) then raise exception '轮班模式不属于当前部门或产线'; end if;
  delete from public.mdm_production_calendar c
  where c.tenant_id=v_tenant and c.department_id=p_department_id
    and c.work_date between p_start_date and p_end_date;
  get diagnostics v_removed=row_count;
  insert into public.mdm_production_calendar(tenant_id,department_id,pattern_id,work_date)
  select v_tenant,p_department_id,p_pattern_id,candidate.work_date
  from (
    select day::date work_date
    from generate_series(p_start_date::timestamp,p_end_date::timestamp,interval '1 day') day
  ) candidate
  where extract(dow from candidate.work_date)::smallint=any(p_weekdays)
    and (
      coalesce(p_include_statutory_holidays,false)
      or not exists(
        select 1
        from app_private.mdm_non_working_statutory_holiday_dates(
          p_department_id,p_start_date,p_end_date,v_tenant
        ) holiday
        where holiday.work_date=candidate.work_date
      )
    )
  on conflict(tenant_id,department_id,work_date)
  do update set pattern_id=excluded.pattern_id;
  get diagnostics v_scheduled=row_count;
  return jsonb_build_object('removed',v_removed,'scheduled',v_scheduled);
end
$$;


ALTER FUNCTION "public"."mdm_replace_production_calendar_range_secure"("p_department_id" "uuid", "p_pattern_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_weekdays" smallint[], "p_include_statutory_holidays" boolean) OWNER TO "postgres";

