--

--
-- Name: mdm_save_bom("jsonb", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_bom"("p_header" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_header->>'id', '')::uuid;
  v_tenant uuid;
  v_actor text := coalesce(nullif(auth.jwt()->>'email', ''), auth.uid()::text, 'system');
  v_status text;
  v_code text;
  v_material public.mdm_material%rowtype;
  v_component public.mdm_material%rowtype;
  v_item jsonb;
  v_group_id uuid := nullif(p_header->>'group_id', '')::uuid;
  v_base_unit_id uuid;
  v_unit_id uuid;
  v_issue_method text;
  v_backflush_method text;
  v_over_issue_method text;
begin
  if auth.uid() is null then
    raise exception '请先登录后再维护 BOM' using errcode = '42501';
  end if;
  if p_header is null or jsonb_typeof(p_header) <> 'object' then
    raise exception 'BOM 基本信息格式不正确' using errcode = '22023';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then
    raise exception 'BOM 组件必须是数组且单次不超过 500 行' using errcode = '22023';
  end if;

  if v_id is null then
    if not app_private.has_permission('MdmBomMaintenance:Add') then
      raise exception '当前账号没有新增 BOM 的权限' using errcode = '42501';
    end if;
    v_tenant := case
      when app_private.is_platform_super() then nullif(p_header->>'tenant_id', '')::uuid
      else app_private.auth_user_tenant_id()
    end;
    if v_tenant is null then
      raise exception '请选择 BOM 归属租户' using errcode = '22023';
    end if;
  else
    if not app_private.has_permission('MdmBomMaintenance:Edit') then
      raise exception '当前账号没有编辑 BOM 的权限' using errcode = '42501';
    end if;
    select status, tenant_id, base_unit_id
      into v_status, v_tenant, v_base_unit_id
    from public.mdm_bom
    where id = v_id
      and app_private.tenant_in_current_read_scope(tenant_id)
    for update;
    if not found then
      raise exception 'BOM 不存在或不属于当前查看范围' using errcode = 'P0002';
    end if;
    if v_status not in ('design', 'changing') then
      raise exception '仅设计或变更中的 BOM 可以编辑' using errcode = '55000';
    end if;
  end if;

  select * into v_material
  from public.mdm_material
  where id = (p_header->>'material_id')::uuid
    and tenant_id = v_tenant
    and status = 'enabled';
  if not found then
    raise exception '父项物料不存在、已停用或不属于当前租户' using errcode = '23503';
  end if;
  v_base_unit_id := coalesce(
    v_material.production_unit_id,
    v_material.base_unit_id,
    nullif(p_header->>'base_unit_id', '')::uuid,
    v_base_unit_id
  );
  if v_base_unit_id is null then
    raise exception '请选择生产单位后再建立 BOM' using errcode = '23514';
  end if;
  if not exists(
    select 1
    from public.mdm_unit_of_measure
    where id = v_base_unit_id
      and tenant_id = v_tenant
      and status = 'enabled'
  ) then
    raise exception '所选生产单位不可用' using errcode = '23503';
  end if;
  if v_group_id is not null and not exists(
    select 1
    from public.mdm_master_group
    where id = v_group_id
      and tenant_id = v_tenant
      and domain = 'bom'
      and enabled
  ) then
    raise exception '所选 BOM 分组不可用' using errcode = '23503';
  end if;

  if v_id is null then
    v_code := app_private.next_document_number('mdm.bom', v_tenant);
    insert into public.mdm_bom(
      tenant_id, bom_code, material_id, version, purpose, status, group_id,
      base_quantity, base_unit_id, effective_from, effective_to, description,
      sort, create_by, update_by
    ) values (
      v_tenant, v_code, v_material.id, btrim(coalesce(p_header->>'version', '')),
      coalesce(nullif(p_header->>'purpose', ''), 'production'), 'design', v_group_id,
      coalesce((p_header->>'base_quantity')::numeric, 1), v_base_unit_id,
      coalesce(nullif(p_header->>'effective_from', '')::date, current_date),
      coalesce(nullif(p_header->>'effective_to', '')::date, date '9999-12-31'),
      nullif(btrim(coalesce(p_header->>'description', '')), ''),
      coalesce((p_header->>'sort')::integer, 10), v_actor, v_actor
    ) returning id into v_id;
  else
    update public.mdm_bom set
      material_id = v_material.id,
      version = btrim(coalesce(p_header->>'version', '')),
      purpose = coalesce(nullif(p_header->>'purpose', ''), 'production'),
      group_id = v_group_id,
      base_quantity = coalesce((p_header->>'base_quantity')::numeric, 1),
      base_unit_id = v_base_unit_id,
      effective_from = coalesce(nullif(p_header->>'effective_from', '')::date, current_date),
      effective_to = coalesce(nullif(p_header->>'effective_to', '')::date, date '9999-12-31'),
      description = nullif(btrim(coalesce(p_header->>'description', '')), ''),
      sort = coalesce((p_header->>'sort')::integer, 10),
      update_by = v_actor,
      update_time = now()
    where id = v_id
      and tenant_id = v_tenant;
    delete from public.mdm_bom_item
    where bom_id = v_id
      and tenant_id = v_tenant;
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    select * into v_component
    from public.mdm_material
    where id = (v_item->>'component_material_id')::uuid
      and tenant_id = v_tenant
      and status = 'enabled';
    if not found then
      raise exception '组件物料不存在、已停用或不属于当前租户' using errcode = '23503';
    end if;
    v_unit_id := coalesce(
      v_component.base_unit_id,
      v_component.production_unit_id,
      nullif(v_item->>'unit_id', '')::uuid
    );
    if v_unit_id is null then
      raise exception '组件物料 % 未维护计量单位', v_component.material_code using errcode = '23514';
    end if;
    if not exists(
      select 1
      from public.mdm_unit_of_measure
      where id = v_unit_id
        and tenant_id = v_tenant
        and status = 'enabled'
    ) then
      raise exception '组件物料 % 的计量单位不可用', v_component.material_code using errcode = '23503';
    end if;
    v_issue_method := coalesce(
      nullif(v_item->>'issue_method', ''),
      nullif(v_component.material_issue_method, ''),
      'production_pick'
    );
    v_backflush_method := coalesce(
      nullif(v_item->>'backflush_method', ''),
      nullif(v_component.backflush_method, ''),
      'none'
    );
    v_over_issue_method := coalesce(
      nullif(v_item->>'over_issue_control_method', ''),
      nullif(v_component.over_issue_control_method, '')
    );

    insert into public.mdm_bom_item(
      tenant_id, bom_id, component_material_id, sequence_no, quantity, unit_id,
      scrap_rate, position_no, operation_name, mrp_enabled,
      default_issue_warehouse_id, issue_method, backflush_method,
      over_issue_control_method, effective_from, effective_to, project_text,
      remark, create_by, update_by
    ) values (
      v_tenant, v_id, v_component.id,
      coalesce((v_item->>'sequence_no')::integer, 10),
      (v_item->>'quantity')::numeric, v_unit_id,
      coalesce((v_item->>'scrap_rate')::numeric, 0),
      nullif(btrim(coalesce(v_item->>'position_no', '')), ''),
      nullif(btrim(coalesce(v_item->>'operation_name', '')), ''),
      coalesce((v_item->>'mrp_enabled')::boolean, true),
      v_component.default_warehouse_id,
      v_issue_method, v_backflush_method, v_over_issue_method,
      coalesce(nullif(v_item->>'effective_from', '')::date, current_date),
      coalesce(nullif(v_item->>'effective_to', '')::date, date '9999-12-31'),
      nullif(btrim(coalesce(v_item->>'project_text', '')), ''),
      nullif(btrim(coalesce(v_item->>'remark', '')), ''),
      v_actor, v_actor
    );
  end loop;
  return v_id;
exception
  when unique_violation then
    raise exception 'BOM 编码、版本或组件行号重复，请检查后重试' using errcode = '23505';
end
$$;


ALTER FUNCTION "public"."mdm_save_bom"("p_header" "jsonb", "p_items" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_bom_group_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_bom_group_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_tenant_id uuid;
  v_parent_id uuid:=nullif(p_payload->>'parent_id','')::uuid;
  v_code text:=upper(btrim(coalesce(p_payload->>'code','')));
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_enabled boolean:=coalesce((p_payload->>'enabled')::boolean,true);
  v_sort integer:=coalesce((p_payload->>'sort')::integer,10);
  v_remark text:=btrim(coalesce(p_payload->>'remark',''));
  v_result uuid;
begin
  if auth.uid() is null then raise exception '请先登录后维护 BOM 分组' using errcode='42501'; end if;
  if not (app_private.is_platform_super() or app_private.has_permission('MdmBomMaintenance:ManageGroup')) then
    raise exception '当前账号无权维护 BOM 分组' using errcode='42501';
  end if;
  if p_id is null then
    v_tenant_id:=case
      when app_private.is_platform_super() then nullif(p_payload->>'tenant_id','')::uuid
      else app_private.auth_user_tenant_id()
    end;
    if v_tenant_id is null then raise exception '请选择 BOM 分组归属租户' using errcode='22023'; end if;
  else
    select tenant_id into v_tenant_id
    from public.mdm_master_group
    where id=p_id and domain='bom' and app_private.tenant_in_current_read_scope(tenant_id)
    for update;
    if not found then raise exception '待编辑的 BOM 分组不存在或无权访问' using errcode='P0002'; end if;
  end if;
  if v_code='' or v_code!~'^[A-Z][A-Z0-9_-]{0,39}$' then
    raise exception '分组编码格式不正确' using errcode='22023';
  end if;
  if v_name='' or char_length(v_name)>80 then
    raise exception '分组名称不能为空且不能超过 80 个字符' using errcode='22023';
  end if;
  if v_sort<0 or v_sort>999999 then raise exception '显示顺序须在 0 到 999999 之间' using errcode='22023'; end if;
  if char_length(v_remark)>500 then raise exception '备注不能超过 500 个字符' using errcode='22023'; end if;
  if v_parent_id is not null and not exists(
    select 1 from public.mdm_master_group
    where id=v_parent_id and tenant_id=v_tenant_id and domain='bom'
  ) then raise exception '上级分组不存在或不属于当前租户' using errcode='P0002'; end if;
  if p_id is not null and v_parent_id=p_id then raise exception '上级分组不能选择当前分组' using errcode='22023'; end if;
  if p_id is not null and v_parent_id is not null and exists(
    with recursive descendants as (
      select id from public.mdm_master_group
      where tenant_id=v_tenant_id and domain='bom' and parent_id=p_id
      union all
      select child.id from public.mdm_master_group child
      join descendants parent on parent.id=child.parent_id
      where child.tenant_id=v_tenant_id and child.domain='bom'
    )
    select 1 from descendants where id=v_parent_id
  ) then raise exception '上级分组不能选择当前分组的下级' using errcode='22023'; end if;

  if p_id is null then
    insert into public.mdm_master_group(tenant_id,domain,parent_id,code,name,sort,enabled,remark)
    values(v_tenant_id,'bom',v_parent_id,v_code,v_name,v_sort,v_enabled,v_remark)
    returning id into v_result;
  else
    update public.mdm_master_group
    set parent_id=v_parent_id,code=v_code,name=v_name,sort=v_sort,enabled=v_enabled,remark=v_remark
    where id=p_id and tenant_id=v_tenant_id returning id into v_result;
  end if;
  return v_result;
exception when unique_violation then
  raise exception 'BOM 分组编码已存在' using errcode='23505';
end
$_$;


ALTER FUNCTION "public"."mdm_save_bom_group_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

