--

--
-- Name: mdm_save_component_industry_group("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_component_industry_group"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
 v_tenant_id uuid; v_parent_id uuid:=nullif(p_payload->>'parent_id','')::uuid;
 v_code text:=upper(btrim(coalesce(p_payload->>'code','')));
 v_name text:=btrim(coalesce(p_payload->>'name',''));
 v_sort integer:=coalesce((p_payload->>'sort')::integer,10);
 v_enabled boolean:=coalesce((p_payload->>'enabled')::boolean,true);
 v_remark text:=btrim(coalesce(p_payload->>'remark',''));
 v_id uuid;
begin
 if auth.uid() is null or not (app_private.is_platform_super() or app_private.has_permission('MdmComponentType:ManageGroup')) then
   raise exception '当前账号无权维护行业分组' using errcode='42501';
 end if;
 if p_id is null then
   v_tenant_id:=case when app_private.is_platform_super() then nullif(p_payload->>'tenant_id','')::uuid
     else app_private.auth_user_tenant_id() end;
 else
   select tenant_id into v_tenant_id from public.mdm_master_group
   where id=p_id and domain='component-type' and app_private.tenant_in_current_read_scope(tenant_id) for update;
   if not found then raise exception '行业分组不存在或无权访问' using errcode='P0002'; end if;
 end if;
 if v_tenant_id is null then raise exception '请选择行业分组归属租户' using errcode='22023'; end if;
 if v_code !~ '^[A-Z][A-Z0-9_-]{0,39}$' or v_name='' or char_length(v_name)>80
 or v_sort not between 0 and 999999 or char_length(v_remark)>500 then
   raise exception '行业分组编码、名称或排序无效' using errcode='22023';
 end if;
 if v_parent_id is not null and not exists(select 1 from public.mdm_master_group
    where id=v_parent_id and tenant_id=v_tenant_id and domain='component-type') then
   raise exception '上级行业分组不存在或不属于当前租户' using errcode='23503';
 end if;
 if p_id is not null and (v_parent_id=p_id or exists(
   with recursive descendants as (
     select id from public.mdm_master_group where parent_id=p_id and tenant_id=v_tenant_id
     union all select child.id from public.mdm_master_group child
       join descendants parent on parent.id=child.parent_id
       where child.tenant_id=v_tenant_id and child.domain='component-type'
   ) select 1 from descendants where id=v_parent_id
 )) then raise exception '上级分组不能选择自身或下级' using errcode='22023'; end if;
 if p_id is null then
   insert into public.mdm_master_group(tenant_id,domain,parent_id,code,name,sort,enabled,remark)
   values(v_tenant_id,'component-type',v_parent_id,v_code,v_name,v_sort,v_enabled,v_remark)
   returning id into v_id;
 else
   update public.mdm_master_group set parent_id=v_parent_id,code=v_code,name=v_name,
     sort=v_sort,enabled=v_enabled,remark=v_remark
   where id=p_id and tenant_id=v_tenant_id and domain='component-type' returning id into v_id;
 end if;
 return v_id;
exception when unique_violation then raise exception '行业分组编码已存在' using errcode='23505';
end $_$;


ALTER FUNCTION "public"."mdm_save_component_industry_group"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_esop_category("jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_esop_category"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_parent_id uuid := nullif(p_payload ->> 'parent_id', '')::uuid;
  v_requested_tenant uuid := nullif(p_payload ->> 'tenant_id', '')::uuid;
  v_tenant uuid;
  v_row_tenant uuid;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text);
begin
  perform app_private.mdm_require_esop_write(
    case when v_id is null then 'MdmEsop:Add' else 'MdmEsop:Edit' end
  );

  if v_id is null then
    if app_private.is_platform_super() and v_requested_tenant is null then
      raise exception '平台管理员新增分类前必须选择目标租户' using errcode = '22023';
    end if;
    if not app_private.is_platform_super()
      and v_requested_tenant is not null
      and v_requested_tenant <> app_private.auth_user_tenant_id() then
      raise exception '不能为当前租户之外的数据新增分类' using errcode = '42501';
    end if;
    v_tenant := app_private.resolve_mutation_tenant_id(v_requested_tenant);
  else
    select category.tenant_id
    into v_row_tenant
    from public.mdm_esop_category category
    where category.id = v_id;

    if not found then
      raise exception '分类不存在或无权维护' using errcode = 'P0002';
    end if;

    v_tenant := app_private.resolve_mutation_tenant_id(v_row_tenant);
    if v_tenant <> v_row_tenant then
      raise exception '分类不存在或无权维护' using errcode = '42501';
    end if;
  end if;

  if v_parent_id is not null and not exists (
    select 1
    from public.mdm_esop_category category
    where category.id = v_parent_id
      and category.tenant_id = v_tenant
  ) then
    raise exception '上级分类不存在或不属于当前租户' using errcode = 'P0002';
  end if;

  if v_id is null then
    insert into public.mdm_esop_category (
      tenant_id,
      parent_id,
      category_code,
      category_name,
      description,
      status,
      sort,
      create_by,
      update_by
    )
    values (
      v_tenant,
      v_parent_id,
      upper(btrim(p_payload ->> 'category_code')),
      btrim(p_payload ->> 'category_name'),
      nullif(btrim(p_payload ->> 'description'), ''),
      coalesce(nullif(p_payload ->> 'status', ''), 'enabled'),
      coalesce((p_payload ->> 'sort')::integer, 10),
      v_actor,
      v_actor
    )
    returning id into v_id;
  else
    if v_parent_id is not null and exists (
      with recursive descendants as (
        select category.id
        from public.mdm_esop_category category
        where category.parent_id = v_id
          and category.tenant_id = v_tenant
        union all
        select child.id
        from public.mdm_esop_category child
        join descendants parent on child.parent_id = parent.id
        where child.tenant_id = v_tenant
      )
      select 1 from descendants where id = v_parent_id
    ) then
      raise exception '不能把分类移动到自身下级' using errcode = '23514';
    end if;

    update public.mdm_esop_category
    set parent_id = v_parent_id,
        category_code = upper(btrim(p_payload ->> 'category_code')),
        category_name = btrim(p_payload ->> 'category_name'),
        description = nullif(btrim(p_payload ->> 'description'), ''),
        status = coalesce(nullif(p_payload ->> 'status', ''), 'enabled'),
        sort = coalesce((p_payload ->> 'sort')::integer, 10),
        update_by = v_actor,
        update_time = now()
    where id = v_id
      and tenant_id = v_tenant;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."mdm_save_esop_category"("p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_esop_document("jsonb", "uuid"[], "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_esop_document"("p_document" "jsonb", "p_material_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_route_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_document ->> 'id', '')::uuid;
  v_requested_tenant uuid := nullif(p_document ->> 'tenant_id', '')::uuid;
  v_tenant uuid;
  v_row_tenant uuid;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text);
  v_category_id uuid := (p_document ->> 'category_id')::uuid;
  v_old_url text;
begin
  perform app_private.mdm_require_esop_write(
    case when v_id is null then 'MdmEsop:Add' else 'MdmEsop:Edit' end
  );

  if v_id is null then
    if app_private.is_platform_super() and v_requested_tenant is null then
      raise exception '平台管理员新增 ESOP 前必须选择目标租户' using errcode = '22023';
    end if;
    if not app_private.is_platform_super()
      and v_requested_tenant is not null
      and v_requested_tenant <> app_private.auth_user_tenant_id() then
      raise exception '不能为当前租户之外的数据新增 ESOP' using errcode = '42501';
    end if;
    v_tenant := app_private.resolve_mutation_tenant_id(v_requested_tenant);
  else
    select document.tenant_id, document.attachment_url
    into v_row_tenant, v_old_url
    from public.mdm_esop_document document
    where document.id = v_id
    for update;

    if not found then
      raise exception 'ESOP 文档不存在或无权维护' using errcode = 'P0002';
    end if;

    v_tenant := app_private.resolve_mutation_tenant_id(v_row_tenant);
    if v_tenant <> v_row_tenant then
      raise exception 'ESOP 文档不存在或无权维护' using errcode = '42501';
    end if;
  end if;

  if coalesce(array_length(p_material_ids, 1), 0) > 500
    or coalesce(array_length(p_route_ids, 1), 0) > 500 then
    raise exception '单份 ESOP 最多分别关联 500 个产品和 500 条工艺路线'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.mdm_esop_category category
    where category.id = v_category_id
      and category.tenant_id = v_tenant
      and category.status = 'enabled'
  ) then
    raise exception '文档分类不存在、已停用或不属于当前租户' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_material_ids, '{}'::uuid[])) value
    left join public.mdm_material material
      on material.id = value
     and material.tenant_id = v_tenant
    where material.id is null
  ) then
    raise exception '关联产品中存在无效或跨租户数据' using errcode = '23503';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_route_ids, '{}'::uuid[])) value
    left join public.mdm_process_route route
      on route.id = value
     and route.tenant_id = v_tenant
    where route.id is null
  ) then
    raise exception '关联工艺路线中存在无效或跨租户数据' using errcode = '23503';
  end if;

  if v_id is null then
    insert into public.mdm_esop_document (
      tenant_id,
      category_id,
      document_code,
      document_name,
      version_no,
      attachment_url,
      attachment_name,
      attachment_type,
      attachment_size,
      description,
      effective_date,
      status,
      create_by,
      update_by
    )
    values (
      v_tenant,
      v_category_id,
      upper(btrim(p_document ->> 'document_code')),
      btrim(p_document ->> 'document_name'),
      btrim(coalesce(p_document ->> 'version_no', 'V1.0')),
      btrim(p_document ->> 'attachment_url'),
      btrim(p_document ->> 'attachment_name'),
      nullif(btrim(p_document ->> 'attachment_type'), ''),
      nullif(p_document ->> 'attachment_size', '')::bigint,
      nullif(btrim(p_document ->> 'description'), ''),
      nullif(p_document ->> 'effective_date', '')::date,
      coalesce(nullif(p_document ->> 'status', ''), 'enabled'),
      v_actor,
      v_actor
    )
    returning id into v_id;
  else
    update public.mdm_esop_document
    set category_id = v_category_id,
        document_code = upper(btrim(p_document ->> 'document_code')),
        document_name = btrim(p_document ->> 'document_name'),
        version_no = btrim(coalesce(p_document ->> 'version_no', 'V1.0')),
        attachment_url = btrim(p_document ->> 'attachment_url'),
        attachment_name = btrim(p_document ->> 'attachment_name'),
        attachment_type = nullif(btrim(p_document ->> 'attachment_type'), ''),
        attachment_size = nullif(p_document ->> 'attachment_size', '')::bigint,
        description = nullif(btrim(p_document ->> 'description'), ''),
        effective_date = nullif(p_document ->> 'effective_date', '')::date,
        status = coalesce(nullif(p_document ->> 'status', ''), 'enabled'),
        upload_time = case
          when v_old_url is distinct from btrim(p_document ->> 'attachment_url') then now()
          else upload_time
        end,
        update_by = v_actor,
        update_time = now()
    where id = v_id
      and tenant_id = v_tenant;

    delete from public.mdm_esop_binding
    where document_id = v_id
      and tenant_id = v_tenant;
  end if;

  insert into public.mdm_esop_binding (
    tenant_id,
    document_id,
    target_type,
    material_id,
    create_by
  )
  select v_tenant, v_id, 'material', value, v_actor
  from (
    select distinct value
    from unnest(coalesce(p_material_ids, '{}'::uuid[])) value
  ) selected;

  insert into public.mdm_esop_binding (
    tenant_id,
    document_id,
    target_type,
    process_route_id,
    create_by
  )
  select v_tenant, v_id, 'process_route', value, v_actor
  from (
    select distinct value
    from unnest(coalesce(p_route_ids, '{}'::uuid[])) value
  ) selected;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."mdm_save_esop_document"("p_document" "jsonb", "p_material_ids" "uuid"[], "p_route_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: mdm_save_material_attribute_group("jsonb", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_material_attribute_group"("p_payload" "jsonb", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
 v_id uuid:=coalesce(p_id,gen_random_uuid()); v_tenant_id uuid:=nullif(btrim(p_payload->>'tenant_id'),'')::uuid;
 v_attribute jsonb; v_attribute_order bigint; v_attribute_id uuid; v_attribute_key text;
 v_value text; v_value_order bigint;
begin
 if v_tenant_id is null then raise exception '目标租户不能为空'; end if;
 if jsonb_typeof(coalesce(p_payload->'attributes','[]'::jsonb))<>'array' then raise exception '属性明细必须为数组'; end if;
 if jsonb_array_length(coalesce(p_payload->'attributes','[]'::jsonb))>50 then raise exception '属性明细最多 50 项'; end if;
 if p_id is null then
  insert into public.mdm_material_attribute_group(id,tenant_id,group_code,group_name,status,sort,text_color,tag_type,remark)
  values(v_id,v_tenant_id,upper(btrim(p_payload->>'group_code')),btrim(p_payload->>'group_name'),
   coalesce(nullif(p_payload->>'status',''),'enabled'),coalesce(nullif(p_payload->>'sort','')::integer,10),
   coalesce(p_payload->>'text_color',''),coalesce(nullif(p_payload->>'tag_type',''),'primary'),nullif(btrim(p_payload->>'remark'),''));
 else
  update public.mdm_material_attribute_group set
   group_code=upper(btrim(p_payload->>'group_code')),group_name=btrim(p_payload->>'group_name'),
   status=coalesce(nullif(p_payload->>'status',''),'enabled'),sort=coalesce(nullif(p_payload->>'sort','')::integer,10),
   text_color=coalesce(p_payload->>'text_color',''),tag_type=coalesce(nullif(p_payload->>'tag_type',''),'primary'),
   remark=nullif(btrim(p_payload->>'remark'),'')
  where id=p_id and tenant_id=v_tenant_id returning id into v_id;
  if not found then raise exception '属性组不存在或无权编辑'; end if;
  delete from public.mdm_material_attribute where group_id=v_id and tenant_id=v_tenant_id;
 end if;
 for v_attribute,v_attribute_order in
  select x.value,x.ordinality from jsonb_array_elements(coalesce(p_payload->'attributes','[]'::jsonb)) with ordinality x(value,ordinality)
 loop
  if nullif(btrim(v_attribute->>'name'),'') is null then raise exception '第 % 项属性名不能为空',v_attribute_order; end if;
  if jsonb_typeof(coalesce(v_attribute->'values','[]'::jsonb))<>'array' then raise exception '属性值必须为数组'; end if;
  if jsonb_array_length(coalesce(v_attribute->'values','[]'::jsonb))>100 then raise exception '单个属性最多 100 个属性值'; end if;
  v_attribute_key:=coalesce(nullif(btrim(v_attribute->>'key'),''),gen_random_uuid()::text);
  insert into public.mdm_material_attribute(tenant_id,group_id,attribute_key,attribute_name,required,enabled,sort)
  values(v_tenant_id,v_id,v_attribute_key,btrim(v_attribute->>'name'),coalesce((v_attribute->>'required')::boolean,false),
   coalesce((v_attribute->>'enabled')::boolean,true),(v_attribute_order*10)::integer) returning id into v_attribute_id;
  for v_value,v_value_order in
   select x.value,x.ordinality from jsonb_array_elements_text(coalesce(v_attribute->'values','[]'::jsonb)) with ordinality x(value,ordinality)
  loop
   if nullif(btrim(v_value),'') is not null then
    insert into public.mdm_material_attribute_value(tenant_id,attribute_id,attribute_value,sort)
    values(v_tenant_id,v_attribute_id,btrim(v_value),(v_value_order*10)::integer);
   end if;
  end loop;
 end loop;
 return v_id;
end; $$;


ALTER FUNCTION "public"."mdm_save_material_attribute_group"("p_payload" "jsonb", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_save_material_code_rule_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_material_code_rule_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_tenant_id uuid;
  v_rule_code text := upper(btrim(coalesce(p_payload->>'rule_code', '')));
  v_rule_name text := btrim(coalesce(p_payload->>'rule_name', ''));
  v_strategy text := coalesce(nullif(p_payload->>'strategy', ''), 'material_type');
  v_prefix text := upper(btrim(coalesce(p_payload->>'prefix', '')));
  v_segments jsonb := coalesce(p_payload->'segments', '[]'::jsonb);
  v_sequence_digits integer := coalesce((p_payload->>'sequence_digits')::integer, 5);
  v_code_length integer := coalesce((p_payload->>'code_length')::integer, 20);
  v_next_value bigint := coalesce((p_payload->>'next_value')::bigint, 1);
  v_example text := upper(coalesce(p_payload->>'example_code', ''));
  v_status text := coalesce(nullif(p_payload->>'status', ''), 'enabled');
  v_sort integer := coalesce((p_payload->>'sort')::integer, 10);
  v_remark text := nullif(btrim(coalesce(p_payload->>'remark', '')), '');
  v_result uuid;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后维护编码规则' using errcode = '42501';
  end if;
  if p_id is null
    and not (
      app_private.is_platform_super()
      or app_private.has_permission('MdmMaterialCodeRule:Add')
    )
  then
    raise exception '当前账号无权新增编码规则' using errcode = '42501';
  end if;
  if p_id is not null
    and not (
      app_private.is_platform_super()
      or app_private.has_permission('MdmMaterialCodeRule:Edit')
    )
  then
    raise exception '当前账号无权编辑编码规则' using errcode = '42501';
  end if;

  if p_id is null then
    v_tenant_id := app_private.resolve_mutation_tenant_id(null);
  else
    select tenant_id
    into v_tenant_id
    from public.mdm_material_code_rule
    where id = p_id
      and (app_private.is_platform_super() or tenant_id = app_private.auth_user_tenant_id())
    for update;
    if not found then
      raise exception '待编辑的编码规则不存在或无权访问' using errcode = 'P0002';
    end if;
  end if;

  if v_rule_code = '' or v_rule_code !~ '^[A-Z][A-Z0-9_]{0,39}$' then
    raise exception '规则编码格式不正确' using errcode = '22023';
  end if;
  if v_rule_name = '' or char_length(v_rule_name) > 100 then
    raise exception '规则名称不能为空且不能超过100个字符' using errcode = '22023';
  end if;
  if v_strategy not in ('material_type', 'material_category') then
    raise exception '归类策略不合法' using errcode = '22023';
  end if;
  if jsonb_typeof(v_segments) <> 'array' or jsonb_array_length(v_segments) > 5 then
    raise exception '号段配置不合法' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from jsonb_array_elements(v_segments) as segment(value)
    where segment.value->>'source' = v_strategy
  ) or exists (
    select 1
    from jsonb_array_elements(v_segments) as segment(value)
    where segment.value->>'source' in ('material_type', 'material_category')
      and segment.value->>'source' <> v_strategy
  ) then
    raise exception '号段中的业务前缀须与归类策略保持一致' using errcode = '22023';
  end if;
  if v_sequence_digits < 2 or v_sequence_digits > 12 or v_next_value < 1 then
    raise exception '流水位数或起始值不合法' using errcode = '22023';
  end if;
  if v_code_length < 4 or v_code_length > 60 then
    raise exception '编码总长度须在4到60位之间' using errcode = '22023';
  end if;
  if char_length(v_prefix) > 20 then
    raise exception '固定字段不能超过20个字符' using errcode = '22023';
  end if;
  if v_status not in ('enabled', 'disabled') then
    raise exception '启用状态不合法' using errcode = '22023';
  end if;
  if v_sort < 0 or v_sort > 999999 then
    raise exception '显示顺序须在0到999999之间' using errcode = '22023';
  end if;
  if char_length(coalesce(v_remark, '')) > 500 then
    raise exception '备注不能超过500个字符' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('mdm-material-code-rule:' || v_tenant_id::text, 0));

  if v_status = 'enabled' then
    update public.mdm_material_code_rule
    set status = 'disabled'
    where tenant_id = v_tenant_id
      and status = 'enabled'
      and (p_id is null or id <> p_id);
  end if;

  if p_id is null then
    insert into public.mdm_material_code_rule(
      tenant_id,
      rule_code,
      rule_name,
      strategy,
      prefix,
      segments,
      sequence_digits,
      code_length,
      next_value,
      example_code,
      status,
      sort,
      remark
    )
    values(
      v_tenant_id,
      v_rule_code,
      v_rule_name,
      v_strategy,
      v_prefix,
      v_segments,
      v_sequence_digits,
      v_code_length,
      v_next_value,
      v_example,
      v_status,
      v_sort,
      v_remark
    )
    returning id into v_result;
  else
    update public.mdm_material_code_rule
    set rule_code = v_rule_code,
        rule_name = v_rule_name,
        strategy = v_strategy,
        prefix = v_prefix,
        segments = v_segments,
        sequence_digits = v_sequence_digits,
        code_length = v_code_length,
        next_value = v_next_value,
        example_code = v_example,
        status = v_status,
        sort = v_sort,
        remark = v_remark
    where id = p_id
      and tenant_id = v_tenant_id
    returning id into v_result;
  end if;

  return v_result;
exception
  when unique_violation then
    raise exception '规则编码、名称重复，或当前租户已有启用规则' using errcode = '23505';
end
$_$;


ALTER FUNCTION "public"."mdm_save_material_code_rule_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_material_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_material_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare v_material public.mdm_material%rowtype; v_original public.mdm_material%rowtype; v_target_tenant uuid; v_update_set text; v_invalid_key text;
begin
 if (select auth.uid()) is null then raise exception '请先登录后再保存物料' using errcode='42501'; end if;
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception '提交内容格式不正确，请刷新后重试' using errcode='22023'; end if;
 select key into v_invalid_key from jsonb_object_keys(p_payload) as key where key not in (select a.attname::text from pg_catalog.pg_attribute a where a.attrelid='public.mdm_material'::regclass and a.attnum>0 and not a.attisdropped) limit 1;
 if v_invalid_key is not null then raise exception '提交字段与服务配置不一致，请刷新后重试' using errcode='22023'; end if;
 if p_id is null then
  if not app_private.has_permission('MdmMaterialArchive:Add') then raise exception '当前账号没有新增物料的权限' using errcode='42501'; end if;
  v_target_tenant:=case when app_private.is_platform_super() then nullif(p_payload->>'tenant_id','')::uuid else app_private.auth_user_tenant_id() end;
  if v_target_tenant is null then raise exception '请选择物料归属租户' using errcode='22023'; end if;
  v_material:=jsonb_populate_record(null::public.mdm_material,p_payload-'id'-'create_by'-'create_time'-'update_by'-'update_time');
  v_material.id:=gen_random_uuid(); v_material.tenant_id:=v_target_tenant; v_material.material_code:=nullif(btrim(v_material.material_code),'');
  if v_material.material_code is null then
   if v_material.code_rule_id is null then raise exception '请选择编码规则自动生成编码，或手工填写物料编码' using errcode='22023'; end if;
   v_material.material_code:=app_private.mdm_generate_material_code_internal(v_material.code_rule_id,v_material.material_type_id,v_material.category_id);
  end if;
  v_material.status:=coalesce(v_material.status,'enabled'); v_material.sort:=coalesce(v_material.sort,10);
  v_material.image_urls:=coalesce(v_material.image_urls,'[]'::jsonb); v_material.attribute_values:=coalesce(v_material.attribute_values,'{}'::jsonb); v_material.unit_conversions:=coalesce(v_material.unit_conversions,'[]'::jsonb);
  v_material.currency_code:=coalesce(nullif(btrim(v_material.currency_code),''),'CNY'); v_material.material_source:=coalesce(nullif(btrim(v_material.material_source),''),'purchase');
  v_material.effective_date:=coalesce(v_material.effective_date,current_date); v_material.expiration_date:=coalesce(v_material.expiration_date,date '9999-12-31');
  v_material.allow_negative_inventory:=coalesce(v_material.allow_negative_inventory,false); v_material.min_stock_alert_enabled:=coalesce(v_material.min_stock_alert_enabled,false);
  v_material.safety_stock_alert_enabled:=coalesce(v_material.safety_stock_alert_enabled,false); v_material.reorder_point_alert_enabled:=coalesce(v_material.reorder_point_alert_enabled,false);
  v_material.max_stock_alert_enabled:=coalesce(v_material.max_stock_alert_enabled,false); v_material.batch_management_enabled:=coalesce(v_material.batch_management_enabled,false);
  v_material.serial_management_enabled:=coalesce(v_material.serial_management_enabled,false); v_material.shelf_life_management_enabled:=coalesce(v_material.shelf_life_management_enabled,false);
  v_material.expiry_alert_enabled:=coalesce(v_material.expiry_alert_enabled,false); v_material.barcode_management_enabled:=coalesce(v_material.barcode_management_enabled,false);
  v_material.key_component:=coalesce(v_material.key_component,false); v_material.minimum_issue_batch:=coalesce(v_material.minimum_issue_batch,1);
  v_material.create_time:=now(); v_material.update_time:=now();
 else
  if not app_private.has_permission('MdmMaterialArchive:Edit') then raise exception '当前账号没有编辑物料的权限' using errcode='42501'; end if;
  select * into v_original from public.mdm_material where id=p_id and app_private.tenant_in_current_read_scope(tenant_id) for update;
  if not found then raise exception '物料不存在或当前账号无权维护' using errcode='P0002'; end if;
  v_material:=jsonb_populate_record(v_original,p_payload-'id'-'tenant_id'-'create_by'-'create_time'-'update_by'-'update_time');
  v_material.id:=v_original.id; v_material.tenant_id:=v_original.tenant_id; v_material.create_by:=v_original.create_by; v_material.create_time:=v_original.create_time; v_material.update_by:=v_original.update_by; v_material.update_time:=v_original.update_time;
 end if;
 if v_material.category_id is null then raise exception '请选择物料分类' using errcode='22023'; end if;
 if v_material.material_type_id is null then raise exception '请选择物料类型' using errcode='22023'; end if;
 if v_material.base_unit_id is null then raise exception '请选择基本单位' using errcode='22023'; end if;
 if nullif(btrim(v_material.material_name),'') is null then raise exception '请输入物料名称' using errcode='22023'; end if;
 if nullif(btrim(v_material.material_code),'') is null then raise exception '请输入物料编码' using errcode='22023'; end if;
 select mt.type_code into v_material.material_type from public.mdm_material_type mt where mt.id=v_material.material_type_id and mt.tenant_id=v_material.tenant_id and mt.status='enabled';
 if not found then raise exception '所选物料类型不存在、已停用或不属于当前租户' using errcode='22023'; end if;
 select u.unit_code into v_material.basic_unit from public.mdm_unit_of_measure u where u.id=v_material.base_unit_id and u.tenant_id=v_material.tenant_id and u.status='enabled';
 if not found then raise exception '所选基本单位不存在、已停用或不属于当前租户' using errcode='22023'; end if;
 if not exists(select 1 from public.mdm_material_category c where c.id=v_material.category_id and c.tenant_id=v_material.tenant_id and c.status='enabled') then raise exception '所选物料分类不存在、已停用或不属于当前租户' using errcode='22023'; end if;
 if v_material.material_group_id is not null and not exists(select 1 from public.mdm_master_group g where g.id=v_material.material_group_id and g.tenant_id=v_material.tenant_id and g.domain='material' and g.enabled) then raise exception '所选物料组不存在、已停用或不属于当前租户' using errcode='22023'; end if;
 if v_material.batch_rule_id is not null and not exists(select 1 from public.mdm_supply_chain_code_rule r where r.id=v_material.batch_rule_id and r.tenant_id=v_material.tenant_id and r.status='enabled' and r.apply_batch) then raise exception '所选批号规则不可用' using errcode='22023'; end if;
 if v_material.serial_rule_id is not null and not exists(select 1 from public.mdm_supply_chain_code_rule r where r.id=v_material.serial_rule_id and r.tenant_id=v_material.tenant_id and r.status='enabled' and r.apply_serial) then raise exception '所选序列号规则不可用' using errcode='22023'; end if;
 if p_id is null then
  insert into public.mdm_material select (v_material).*;
 else
  select string_agg(format('%1$I = ($1).%1$I',a.attname),', ' order by a.attnum) into v_update_set from pg_catalog.pg_attribute a where a.attrelid='public.mdm_material'::regclass and a.attnum>0 and not a.attisdropped and a.attname not in ('id','tenant_id','create_by','create_time','update_by','update_time');
  execute format('update public.mdm_material set %s where id=$2',v_update_set) using v_material,p_id;
 end if;
 return v_material.id;
end $_$;


ALTER FUNCTION "public"."mdm_save_material_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_personnel_common_work_centers("uuid", "uuid", "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_personnel_common_work_centers"("p_personnel_id" "uuid", "p_department_id" "uuid", "p_work_center_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tenant_value uuid;
  current_department_id uuid;
  department_value uuid;
  normalized_ids uuid[];
  had_configuration boolean;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再保存常用工作中心' using errcode = '42501';
  end if;
  if p_personnel_id is null then
    raise exception '请选择需要配置的员工' using errcode = '22023';
  end if;

  normalized_ids := array(
    select distinct center_id
    from unnest(coalesce(p_work_center_ids, array[]::uuid[])) center_id
    where center_id is not null
  );

  select person.tenant_id, person.department_id
  into tenant_value, current_department_id
  from public.mdm_production_personnel person
  where person.id = p_personnel_id
    and app_private.tenant_in_current_read_scope(person.tenant_id)
    and person.enabled is true
  for update;
  if not found then
    raise exception '未找到可配置的人员，请刷新后重试' using errcode = 'P0001';
  end if;

  department_value := coalesce(p_department_id, current_department_id);

  select exists (
    select 1
    from public.mdm_personnel_common_work_center configured
    where configured.tenant_id = tenant_value
      and configured.personnel_id = p_personnel_id
  ) into had_configuration;

  if had_configuration then
    if app_private.has_permission('MdmPersonnelWorkCenter:Edit') is not true then
      raise exception '当前账号没有编辑常用工作中心的权限' using errcode = '42501';
    end if;
  else
    if cardinality(normalized_ids) = 0 then
      raise exception '请至少选择一个常用工作中心' using errcode = '22023';
    end if;
    if app_private.has_permission('MdmPersonnelWorkCenter:Add') is not true then
      raise exception '当前账号没有新增常用工作中心配置的权限' using errcode = '42501';
    end if;
  end if;

  if department_value is distinct from current_department_id
    and app_private.has_permission('MdmPersonnelWorkCenter:Edit') is not true then
    raise exception '当前账号没有修改人员所属部门的权限' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.mdm_production_department department
    where department.tenant_id = tenant_value
      and department.id = department_value
  ) then
    raise exception '所属部门不存在或不属于当前租户，请重新选择' using errcode = '22023';
  end if;

  if department_value is distinct from current_department_id
    and not exists (
      select 1
      from public.mdm_production_department department
      where department.tenant_id = tenant_value
        and department.id = department_value
        and department.enabled is true
    ) then
    raise exception '所选部门已禁用，请重新选择' using errcode = '22023';
  end if;

  if (
    select count(*)
    from public.mdm_work_center center
    where center.tenant_id = tenant_value
      and center.id = any(normalized_ids)
  ) <> cardinality(normalized_ids) then
    raise exception '部分工作中心不存在或不属于当前租户，请刷新后重试' using errcode = '22023';
  end if;

  if department_value is distinct from current_department_id then
    update public.mdm_production_personnel
    set department_id = department_value
    where tenant_id = tenant_value
      and id = p_personnel_id;
  end if;

  delete from public.mdm_personnel_common_work_center configured
  where configured.tenant_id = tenant_value
    and configured.personnel_id = p_personnel_id;

  insert into public.mdm_personnel_common_work_center(
    tenant_id,
    personnel_id,
    work_center_id
  )
  select tenant_value, p_personnel_id, center_id
  from unnest(normalized_ids) center_id;

  return cardinality(normalized_ids);
end;
$$;


ALTER FUNCTION "public"."mdm_save_personnel_common_work_centers"("p_personnel_id" "uuid", "p_department_id" "uuid", "p_work_center_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: mdm_save_production_equipment_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_production_equipment_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant uuid;
  v_department public.mdm_production_department%rowtype;
  v_code text := upper(btrim(coalesce(p_payload->>'equipment_code', '')));
  v_name text := btrim(coalesce(p_payload->>'equipment_name', ''));
  v_result uuid;
  v_actor text := coalesce(auth.jwt()->>'email', auth.uid()::text);
  v_sync_work_center boolean := coalesce((p_payload->>'sync_work_center')::boolean, false);
  v_existing_sync boolean := false;
  v_work_center_id uuid;
begin
  if auth.uid() is null then raise exception '请先登录后再维护生产设备' using errcode = '42501'; end if;
  if not app_private.has_permission(case when p_id is null then 'MdmProductionEquipment:Add' else 'MdmProductionEquipment:Edit' end) then
    raise exception '当前账号没有维护生产设备的权限' using errcode = '42501';
  end if;

  if p_id is not null then
    select equipment.tenant_id, equipment.sync_work_center, equipment.work_center_id
    into v_tenant, v_existing_sync, v_work_center_id
    from public.mdm_equipment equipment
    where equipment.id = p_id
    for update;
  end if;

  v_tenant := app_private.resolve_mutation_tenant_id(coalesce(
    v_tenant, nullif(p_payload->>'tenant_id', '')::uuid
  ));
  if v_tenant is null then raise exception '请选择明确的目标租户' using errcode = '22023'; end if;

  select * into v_department
  from public.mdm_production_department
  where id = nullif(p_payload->>'production_department_id', '')::uuid
    and tenant_id = v_tenant and enabled;
  if not found then raise exception '请选择当前租户下已启用的部门或产线' using errcode = '23503'; end if;
  if v_name = '' then raise exception '请输入设备名称' using errcode = '23514'; end if;
  if v_code = '' then v_code := app_private.next_document_number('mdm.production-equipment', v_tenant); end if;

  if not exists (
    select 1 from public.mdm_equipment_category
    where id = (p_payload->>'category_id')::uuid
      and tenant_id = v_tenant and status = 'enabled'
  ) then raise exception '设备分类不存在或已停用' using errcode = '23503'; end if;
  if nullif(p_payload->>'location_id', '') is not null and not exists (
    select 1 from public.mdm_storage_location
    where id = (p_payload->>'location_id')::uuid
      and tenant_id = v_tenant and status = 'enabled'
  ) then raise exception '存放位置不存在或已停用' using errcode = '23503'; end if;
  if nullif(p_payload->>'responsible_employee_id', '') is not null and not exists (
    select 1 from public.mdm_employee
    where id = (p_payload->>'responsible_employee_id')::uuid and tenant_id = v_tenant
  ) then raise exception '设备管理员不属于当前租户' using errcode = '23503'; end if;
  if nullif(p_payload->>'supplier_id', '') is not null and not exists (
    select 1 from public.mdm_supplier
    where id = (p_payload->>'supplier_id')::uuid and tenant_id = v_tenant
  ) then raise exception '供应商不属于当前租户' using errcode = '23503'; end if;

  if p_id is null and v_sync_work_center then
    begin
      insert into public.mdm_work_center(
        tenant_id, code, name, department_id, policy, sort, remark, create_by, update_by
      )
      values (
        v_tenant, v_code, v_name, v_department.id,
        coalesce(
          (select defaults.policy from public.mdm_work_center_defaults defaults where defaults.tenant_id = v_tenant),
          jsonb_build_object(
            'reportMode', '手动开始手动结束',
            'deviation', '调整到下一班次',
            'materialCheck', '无',
            'timeAllocation', '分摊',
            'goodDefault', '无',
            'quantityCheck', '不检查',
            'specialFields', jsonb_build_array('无'),
            'parallel', '不允许',
            'progressLimit', '限额100%',
            'shiftLock', '不锁定',
            'taskOrder', '不管控',
            'autoChangeover', '否',
            'inspectionSave', '仅全部项完成可保存',
            'startControl', jsonb_build_array('不控制'),
            'reportControl', jsonb_build_array('不控制'),
            'yellowPause', '否',
            'personAllocation', '标准分配',
            'achievement', '按产能计算',
            'clearBatch', '不清除',
            'quickJoin', '关闭',
            'planOrder', '按分配时间',
            'autoReport', '关闭',
            'autoStart', '关闭',
            'operationLimit', 0,
            'operationUnit', '秒',
            'customLimit', 100,
            'groupTag', '',
            'reportTime', '18:00'
          )
        ),
        coalesce(nullif(p_payload->>'sort', '')::integer, 10),
        '由生产设备同步生成', v_actor, v_actor
      )
      returning id into v_work_center_id;
    exception when unique_violation then
      raise exception '同编号或同名称的工作中心已存在，请调整设备编号或名称后重试'
        using errcode = '23505';
    end;
  elsif p_id is not null and v_existing_sync then
    if v_work_center_id is null then
      raise exception '同步工作中心关系不完整，请联系管理员处理' using errcode = '23503';
    end if;
    update public.mdm_work_center
    set name = v_name,
        department_id = v_department.id,
        sort = coalesce(nullif(p_payload->>'sort', '')::integer, 10),
        update_by = v_actor,
        update_time = now()
    where id = v_work_center_id and tenant_id = v_tenant;
    if not found then raise exception '同步工作中心不存在或不属于当前租户' using errcode = '23503'; end if;
    v_sync_work_center := true;
  else
    v_work_center_id := nullif(p_payload->>'work_center_id', '')::uuid;
  end if;

  if v_work_center_id is not null and not exists (
    select 1 from public.mdm_work_center
    where id = v_work_center_id and tenant_id = v_tenant and department_id = v_department.id
  ) then raise exception '工作中心不属于所选产线' using errcode = '23503'; end if;

  if p_id is null then
    insert into public.mdm_equipment(
      tenant_id, category_id, location_id, using_organization_id, managing_organization_id,
      responsible_employee_id, supplier_id, equipment_code, equipment_name, photo_url,
      equipment_kind, production_department_id, work_center_id, equipment_brand, model,
      manufacturer, factory_no, fixed_asset_no, manufacture_date, installation_date,
      acceptance_date, enable_date, traffic_light_card_no, andon_box_no,
      pulse_interval_seconds, standard_utilization, sync_work_center, operation_status,
      status, remark, sort, create_by, update_by
    )
    values (
      v_tenant, (p_payload->>'category_id')::uuid,
      nullif(p_payload->>'location_id', '')::uuid,
      v_department.organization_id, v_department.organization_id,
      nullif(p_payload->>'responsible_employee_id', '')::uuid,
      nullif(p_payload->>'supplier_id', '')::uuid,
      v_code, v_name, nullif(btrim(p_payload->>'photo_url'), ''), 'general',
      v_department.id, v_work_center_id,
      nullif(btrim(p_payload->>'equipment_brand'), ''),
      nullif(btrim(p_payload->>'model'), ''),
      nullif(btrim(p_payload->>'manufacturer'), ''),
      nullif(btrim(p_payload->>'factory_no'), ''),
      nullif(btrim(p_payload->>'fixed_asset_no'), ''),
      nullif(p_payload->>'manufacture_date', '')::date,
      nullif(p_payload->>'installation_date', '')::date,
      nullif(p_payload->>'acceptance_date', '')::date,
      nullif(p_payload->>'enable_date', '')::date,
      nullif(btrim(p_payload->>'traffic_light_card_no'), ''),
      nullif(btrim(p_payload->>'andon_box_no'), ''),
      nullif(p_payload->>'pulse_interval_seconds', '')::integer,
      nullif(p_payload->>'standard_utilization', '')::numeric,
      v_sync_work_center,
      coalesce(nullif(p_payload->>'operation_status', ''), 'normal'),
      coalesce(nullif(p_payload->>'status', ''), 'enabled'),
      nullif(btrim(p_payload->>'remark'), ''),
      coalesce(nullif(p_payload->>'sort', '')::integer, 10),
      v_actor, v_actor
    )
    returning id into v_result;
  else
    update public.mdm_equipment
    set category_id = (p_payload->>'category_id')::uuid,
        location_id = nullif(p_payload->>'location_id', '')::uuid,
        using_organization_id = v_department.organization_id,
        managing_organization_id = v_department.organization_id,
        responsible_employee_id = nullif(p_payload->>'responsible_employee_id', '')::uuid,
        supplier_id = nullif(p_payload->>'supplier_id', '')::uuid,
        equipment_name = v_name,
        photo_url = nullif(btrim(p_payload->>'photo_url'), ''),
        production_department_id = v_department.id,
        work_center_id = v_work_center_id,
        equipment_brand = nullif(btrim(p_payload->>'equipment_brand'), ''),
        model = nullif(btrim(p_payload->>'model'), ''),
        manufacturer = nullif(btrim(p_payload->>'manufacturer'), ''),
        factory_no = nullif(btrim(p_payload->>'factory_no'), ''),
        fixed_asset_no = nullif(btrim(p_payload->>'fixed_asset_no'), ''),
        manufacture_date = nullif(p_payload->>'manufacture_date', '')::date,
        installation_date = nullif(p_payload->>'installation_date', '')::date,
        acceptance_date = nullif(p_payload->>'acceptance_date', '')::date,
        enable_date = nullif(p_payload->>'enable_date', '')::date,
        traffic_light_card_no = nullif(btrim(p_payload->>'traffic_light_card_no'), ''),
        andon_box_no = nullif(btrim(p_payload->>'andon_box_no'), ''),
        pulse_interval_seconds = nullif(p_payload->>'pulse_interval_seconds', '')::integer,
        standard_utilization = nullif(p_payload->>'standard_utilization', '')::numeric,
        sync_work_center = v_sync_work_center,
        operation_status = coalesce(nullif(p_payload->>'operation_status', ''), 'normal'),
        status = coalesce(nullif(p_payload->>'status', ''), 'enabled'),
        remark = nullif(btrim(p_payload->>'remark'), ''),
        sort = coalesce(nullif(p_payload->>'sort', '')::integer, 10),
        update_by = v_actor,
        update_time = now()
    where id = p_id and tenant_id = v_tenant
    returning id into v_result;
    if v_result is null then raise exception '设备不存在或无权编辑' using errcode = 'P0002'; end if;
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "public"."mdm_save_production_equipment_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: mdm_save_shift_schedule_secure("uuid", "jsonb", "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_shift_schedule_secure"("p_id" "uuid", "p_payload" "jsonb", "p_personnel_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid:=coalesce(p_id,gen_random_uuid()); v_tenant uuid; v_department uuid;
  v_pattern uuid; v_shift_index integer; v_date_mode text; v_start date; v_end date;
  v_weekdays smallint[]; v_include_statutory_holidays boolean; v_note text;
  v_permission text:=case when p_id is null then 'MdmShiftScheduling:Add' else 'MdmShiftScheduling:Edit' end;
  v_personnel uuid;
begin
  if auth.uid() is null or not app_private.has_permission(v_permission) then
    raise exception '没有排班维护权限' using errcode='42501';
  end if;
  v_department:=(p_payload->>'department_id')::uuid;
  v_pattern:=(p_payload->>'pattern_id')::uuid;
  v_shift_index:=(p_payload->>'shift_index')::integer;
  v_date_mode:=p_payload->>'date_mode';
  v_start:=(p_payload->>'start_date')::date;
  v_end:=nullif(p_payload->>'end_date','')::date;
  v_note:=left(btrim(coalesce(p_payload->>'note','')),300);
  if p_payload?'weekdays' then
    if jsonb_typeof(p_payload->'weekdays')<>'array' then raise exception '参与星期格式无效'; end if;
    select array_agg(distinct weekday order by weekday) into v_weekdays
    from (
      select value::smallint weekday
      from jsonb_array_elements_text(p_payload->'weekdays')
    ) parsed_weekdays;
  else
    v_weekdays:=array[1,2,3,4,5,6,0]::smallint[];
  end if;
  v_include_statutory_holidays:=case
    when p_payload?'include_statutory_holidays'
      then (p_payload->>'include_statutory_holidays')::boolean
    else true end;
  if cardinality(v_weekdays) is null or cardinality(v_weekdays) not between 1 and 7
    or array_position(v_weekdays,null) is not null
    or exists(select 1 from unnest(v_weekdays) weekday where weekday not between 0 and 6) then
    raise exception '请至少选择一个有效的参与星期';
  end if;
  if cardinality(p_personnel_ids) is null or cardinality(p_personnel_ids) not between 1 and 500
    or array_position(p_personnel_ids,null) is not null then
    raise exception '请选择 1 至 500 名班组人员';
  end if;
  select tenant_id into v_tenant from public.mdm_production_department
  where id=v_department and enabled and app_private.tenant_in_current_read_scope(tenant_id);
  if v_tenant is null then raise exception '部门或产线不可访问'; end if;
  if p_id is not null and not exists(
    select 1 from public.mdm_shift_schedule
    where id=p_id and tenant_id=v_tenant and deleted_at is null
  ) then raise exception '排班不存在或不可编辑'; end if;
  for v_personnel in select distinct unnest(p_personnel_ids) order by 1 loop
    perform pg_advisory_xact_lock(hashtextextended(v_personnel::text,7319));
  end loop;
  if p_id is null then
    insert into public.mdm_shift_schedule(
      id,tenant_id,department_id,pattern_id,shift_index,shift_name,shift_start_time,
      shift_end_time,date_mode,start_date,end_date,weekdays,include_statutory_holidays,note
    ) values(
      v_id,v_tenant,v_department,v_pattern,v_shift_index,'待校验','00:00','00:00',
      v_date_mode,v_start,v_end,v_weekdays,v_include_statutory_holidays,v_note
    );
  else
    delete from public.mdm_shift_schedule_member where schedule_id=v_id and tenant_id=v_tenant;
    update public.mdm_shift_schedule
    set department_id=v_department,pattern_id=v_pattern,shift_index=v_shift_index,
      date_mode=v_date_mode,start_date=v_start,end_date=v_end,weekdays=v_weekdays,
      include_statutory_holidays=v_include_statutory_holidays,note=v_note
    where id=p_id and tenant_id=v_tenant and deleted_at is null;
  end if;
  insert into public.mdm_shift_schedule_member(tenant_id,schedule_id,personnel_id)
  select v_tenant,v_id,personnel_id
  from (select distinct unnest(p_personnel_ids) personnel_id) people;
  return v_id;
end
$$;


ALTER FUNCTION "public"."mdm_save_shift_schedule_secure"("p_id" "uuid", "p_payload" "jsonb", "p_personnel_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: mdm_save_statutory_holiday_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_save_statutory_holiday_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.resolve_mutation_tenant_id(coalesce((select target.tenant_id from public.smis_statutory_holiday target where target.id = p_id),(select o.tenant_id from public.mdm_organization o where o.id=nullif(p_payload->>'organization_id','')::uuid)));
  v_id uuid;
  v_organization_id uuid := nullif(p_payload->>'organization_id', '')::uuid;
  v_type text := btrim(coalesce(p_payload->>'holiday_type', ''));
  v_start date := nullif(p_payload->>'start_date', '')::date;
  v_end date := nullif(p_payload->>'end_date', '')::date;
begin
  if p_id is null and not app_private.has_permission('MdmStatutoryHoliday:Add') then
    raise exception '当前账号没有新增法定节假日的权限' using errcode = '42501';
  end if;
  if p_id is not null and not app_private.has_permission('MdmStatutoryHoliday:Edit') then
    raise exception '当前账号没有编辑法定节假日的权限' using errcode = '42501';
  end if;
  if v_organization_id is null or not exists (
    select 1 from public.mdm_organization organization
    where organization.id = v_organization_id and organization.tenant_id = v_tenant_id and organization.status = '1'
  ) then raise exception '请选择当前租户的有效公司或组织' using errcode = '22023'; end if;
  if not app_private.is_enabled_dictionary_value('smisHolidayType', v_type)
    and not (
      p_id is not null
      and exists (
        select 1
        from public.smis_statutory_holiday existing_holiday
        where existing_holiday.id = p_id
          and existing_holiday.tenant_id = v_tenant_id
          and btrim(existing_holiday.holiday_type) = v_type
      )
    ) then
    raise exception '假期类型无效或已停用' using errcode = '22023';
  end if;
  if v_start is null or v_end is null or v_end < v_start then
    raise exception '结束日期不能早于开始日期' using errcode = '22023';
  end if;

  if p_id is null then
    insert into public.smis_statutory_holiday(
      tenant_id, organization_id, holiday_type, start_date, end_date, remark
    ) values (
      v_tenant_id, v_organization_id, v_type, v_start, v_end, nullif(btrim(p_payload->>'remark'), '')
    ) returning id into v_id;
  else
    update public.smis_statutory_holiday set
      organization_id = v_organization_id,
      holiday_type = v_type,
      start_date = v_start,
      end_date = v_end,
      remark = nullif(btrim(p_payload->>'remark'), '')
    where id = p_id and tenant_id = v_tenant_id returning id into v_id;
    if v_id is null then raise exception '法定节假日记录不存在或已删除' using errcode = 'P0002'; end if;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."mdm_save_statutory_holiday_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

