--

--
-- Name: mdm_set_esop_documents_enabled("uuid"[], boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_set_esop_documents_enabled"("p_ids" "uuid"[], "p_enabled" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count integer;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text);
begin
  perform app_private.mdm_require_esop_write(
    case when p_enabled then 'MdmEsop:Enable' else 'MdmEsop:Disable' end
  );

  if coalesce(array_length(p_ids, 1), 0) > 500 then
    raise exception '单次最多操作 500 份 ESOP' using errcode = '22023';
  end if;

  update public.mdm_esop_document document
  set status = case when p_enabled then 'enabled' else 'disabled' end,
      update_by = v_actor,
      update_time = now()
  where document.id = any(coalesce(p_ids, '{}'::uuid[]))
    and app_private.tenant_in_current_read_scope(document.tenant_id);

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."mdm_set_esop_documents_enabled"("p_ids" "uuid"[], "p_enabled" boolean) OWNER TO "postgres";

--

--
-- Name: mdm_set_production_calendar("uuid", "uuid", "date"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_set_production_calendar"("p_department_id" "uuid", "p_pattern_id" "uuid", "p_dates" "date"[]) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare affected integer;
begin
  if auth.uid() is null or not app_private.has_permission('MdmFactoryCalendar:Configure') then raise exception '没有排班设置权限' using errcode='42501'; end if;
  if cardinality(p_dates) is null or cardinality(p_dates) not between 1 and 3660 or array_position(p_dates,null) is not null then raise exception '请选择 1 至 3660 个有效日期'; end if;
  if exists(select 1 from unnest(p_dates) d where d <= (current_timestamp at time zone 'Asia/Shanghai')::date) then raise exception '只能设置明天及以后的生产日历'; end if;
  insert into public.mdm_production_calendar(department_id,pattern_id,work_date)
  select p_department_id,p_pattern_id,d from (select distinct unnest(p_dates) d) dates
  on conflict(tenant_id,department_id,work_date) do update set pattern_id=excluded.pattern_id;
  get diagnostics affected=row_count;
  return affected;
end $$;


ALTER FUNCTION "public"."mdm_set_production_calendar"("p_department_id" "uuid", "p_pattern_id" "uuid", "p_dates" "date"[]) OWNER TO "postgres";

--

--
-- Name: mdm_set_production_calendar_day_type_secure("uuid", "date", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_set_production_calendar_day_type_secure"("p_department_id" "uuid", "p_work_date" "date", "p_day_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant uuid; v_id uuid;
begin
 if auth.uid() is null or not app_private.has_permission('MdmFactoryCalendar:Configure') then raise exception '没有日历设置权限' using errcode='42501'; end if;
 select d.tenant_id into v_tenant from public.mdm_production_department d where d.id=p_department_id and d.enabled and (app_private.is_platform_super() or d.tenant_id=app_private.auth_user_tenant_id());
 if v_tenant is null then raise exception '生产组织不存在、已停用或无权操作' using errcode='42501'; end if;
 if p_work_date is null or p_work_date not between date '1900-01-01' and date '2200-12-31' or p_day_type is null or p_day_type not in ('rest_day','statutory_holiday','work_day','half_work_day') then raise exception '日期或日类型无效' using errcode='22023'; end if;
 insert into public.mdm_production_calendar_day_setting(tenant_id,department_id,work_date,day_type) values(v_tenant,p_department_id,p_work_date,p_day_type)
 on conflict(tenant_id,department_id,work_date) do update set day_type=excluded.day_type returning id into v_id;
 return v_id;
end $$;


ALTER FUNCTION "public"."mdm_set_production_calendar_day_type_secure"("p_department_id" "uuid", "p_work_date" "date", "p_day_type" "text") OWNER TO "postgres";

