--
-- Name: mdm_set_production_equipment_enabled_secure("uuid"[], boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_set_production_equipment_enabled_secure"("p_ids" "uuid"[], "p_enabled" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_count integer; v_actor text:=coalesce(auth.jwt()->>'email',auth.uid()::text);
begin
  if auth.uid() is null or not app_private.has_permission(case when p_enabled then 'MdmProductionEquipment:Enable' else 'MdmProductionEquipment:Disable' end) then
    raise exception '当前账号没有变更设备状态的权限' using errcode='42501';
  end if;
  if coalesce(cardinality(p_ids),0)=0 or cardinality(p_ids)>500 then raise exception '每次请选择 1 至 500 台设备' using errcode='22023'; end if;
  update public.mdm_equipment set status=case when p_enabled then 'enabled' else 'disabled' end,update_by=v_actor,update_time=now()
  where id=any(p_ids) and app_private.tenant_in_current_read_scope(tenant_id);
  get diagnostics v_count=row_count; return v_count;
end $$;


