--

--
-- Name: mdm_switch_material_code_rule_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_switch_material_code_rule_secure"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid;
begin
  if (select auth.uid()) is null then raise exception '请先登录后切换编码规则' using errcode='42501'; end if;
  if not (app_private.is_platform_super() or app_private.has_permission('MdmMaterialCodeRule:Enable'))
    then raise exception '当前账号无权启用编码规则' using errcode='42501'; end if;
  select tenant_id into v_tenant_id from public.mdm_material_code_rule where id=p_id
    and (app_private.is_platform_super() or tenant_id=app_private.auth_user_tenant_id()) for update;
  if not found then raise exception '编码规则不存在或无权访问' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mdm-material-code-rule:'||v_tenant_id::text,0));
  update public.mdm_material_code_rule set status='disabled'
  where tenant_id=v_tenant_id and status='enabled' and id<>p_id;
  update public.mdm_material_code_rule set status='enabled' where id=p_id and tenant_id=v_tenant_id;
  return p_id;
end $$;


ALTER FUNCTION "public"."mdm_switch_material_code_rule_secure"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: mdm_bom; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."mdm_bom" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "bom_code" "text" NOT NULL,
    "material_id" "uuid" NOT NULL,
    "version" "text" DEFAULT ''::"text" NOT NULL,
    "purpose" "text" DEFAULT 'production'::"text" NOT NULL,
    "status" "text" DEFAULT 'design'::"text" NOT NULL,
    "base_quantity" numeric(20,6) DEFAULT 1 NOT NULL,
    "base_unit_id" "uuid" NOT NULL,
    "effective_from" "date",
    "effective_to" "date",
    "description" "text",
    "sort" integer DEFAULT 10 NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "group_id" "uuid",
    "process_route_id" "uuid",
    "project_id" "uuid",
    "source_quotation_id" "uuid",
    CONSTRAINT "mdm_bom_code_check" CHECK ((("bom_code" = "upper"("btrim"("bom_code"))) AND ("bom_code" ~ '^[A-Z0-9][A-Z0-9._-]{1,59}$'::"text"))),
    CONSTRAINT "mdm_bom_date_check" CHECK ((("effective_to" IS NULL) OR ("effective_from" IS NULL) OR ("effective_to" >= "effective_from"))),
    CONSTRAINT "mdm_bom_purpose_check" CHECK (("purpose" = ANY (ARRAY['production'::"text", 'design'::"text", 'process'::"text", 'sales'::"text", 'spare_part'::"text"]))),
    CONSTRAINT "mdm_bom_quantity_check" CHECK ((("base_quantity" > (0)::numeric) AND ("base_quantity" = "trunc"("base_quantity")))),
    CONSTRAINT "mdm_bom_sort_check" CHECK ((("sort" >= 0) AND ("sort" <= 999999))),
    CONSTRAINT "mdm_bom_status_check" CHECK (("status" = ANY (ARRAY['design'::"text", 'review'::"text", 'effective'::"text", 'changing'::"text", 'archived'::"text", 'void'::"text"]))),
    CONSTRAINT "mdm_bom_version_check" CHECK (("char_length"("version") <= 30))
);


ALTER TABLE "public"."mdm_bom" OWNER TO "postgres";

--

--
-- Name: TABLE "mdm_bom"; Type: COMMENT; Schema: public
--

--

COMMENT ON TABLE "public"."mdm_bom" IS 'Tenant-scoped bill-of-material header and lifecycle record.';


--

--
-- Name: mdm_transition_bom("uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."mdm_transition_bom"("p_bom_id" "uuid", "p_target_status" "text") RETURNS "public"."mdm_bom"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.mdm_bom%rowtype;
  v_current_status text;
  v_required_permission text;
  v_actor text := coalesce(nullif(auth.jwt()->>'email', ''), auth.uid()::text, 'system');
begin
  if auth.uid() is null then
    raise exception '请先登录后操作 BOM' using errcode = '42501';
  end if;

  select *
    into v_row
  from public.mdm_bom
  where id = p_bom_id
    and app_private.tenant_in_current_read_scope(tenant_id)
  for update;

  if not found then
    raise exception 'BOM 不存在或无权操作' using errcode = 'P0002';
  end if;

  v_current_status := v_row.status;
  if not (
    (v_current_status in ('design', 'changing') and p_target_status = 'review')
    or (v_current_status = 'review' and p_target_status = 'effective')
    or (v_current_status = 'effective' and p_target_status = 'changing')
    or (v_current_status in ('effective', 'changing') and p_target_status = 'archived')
    or (v_current_status in ('design', 'review', 'effective', 'changing') and p_target_status = 'void')
  ) then
    raise exception '当前 BOM 状态不允许执行此生命周期操作' using errcode = '55000';
  end if;

  v_required_permission := case p_target_status
    when 'review' then 'MdmBomMaintenance:Submit'
    when 'effective' then 'MdmBomMaintenance:Approve'
    when 'changing' then 'MdmBomMaintenance:Edit'
    when 'archived' then 'MdmBomMaintenance:Archive'
    when 'void' then 'MdmBomMaintenance:Archive'
  end;

  if v_required_permission is null or not app_private.has_permission(v_required_permission) then
    raise exception '当前账号没有执行此生命周期操作的权限' using errcode = '42501';
  end if;

  update public.mdm_bom
  set status = p_target_status,
      update_by = v_actor,
      update_time = now()
  where id = p_bom_id
  returning * into v_row;

  return v_row;
end
$$;


ALTER FUNCTION "public"."mdm_transition_bom"("p_bom_id" "uuid", "p_target_status" "text") OWNER TO "postgres";

