--

--
-- Name: set_field_permissions("text", "text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."set_field_permissions"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_permissions" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_actor_user_id uuid := app_private.current_app_user_id();
  v_resource public.sys_permission_resource%rowtype;
  v_before jsonb;
  v_after jsonb;
begin
  if not app_private.can_manage_field_permissions() then
    raise exception 'Missing permission: System:FieldPermission:Manage';
  end if;

  if p_subject_type not in ('role', 'user') then
    raise exception 'Invalid permission subject type';
  end if;

  if p_permissions is null or jsonb_typeof(p_permissions) <> 'object' then
    raise exception 'Permissions must be a JSON object';
  end if;

  select * into v_resource
  from public.sys_permission_resource
  where tenant_id = v_tenant_id
    and resource_key = p_resource_key
    and enabled is true;

  if not found then
    raise exception 'Permission resource not found';
  end if;

  if p_subject_type = 'role' then
    if not exists (
      select 1 from public.sys_role
      where id = p_subject_id and tenant_id = v_tenant_id and enabled is true
    ) then
      raise exception 'Role not found or access denied';
    end if;

    select coalesce(jsonb_object_agg(field_row.field_key, permission_row.access_level), '{}'::jsonb)
      into v_before
    from public.sys_role_field_permission permission_row
    join public.sys_permission_field field_row on field_row.id = permission_row.field_id
    where permission_row.tenant_id = v_tenant_id
      and permission_row.role_id = p_subject_id
      and permission_row.resource_id = v_resource.id;

    delete from public.sys_role_field_permission
    where tenant_id = v_tenant_id
      and role_id = p_subject_id
      and resource_id = v_resource.id;

    insert into public.sys_role_field_permission (
      tenant_id, role_id, resource_id, field_id, access_level, create_by, update_by
    )
    select v_tenant_id, p_subject_id, v_resource.id, field_row.id,
           permission_item.value, 'platform-owner@example.com', 'platform-owner@example.com'
    from jsonb_each_text(p_permissions) permission_item
    join public.sys_permission_field field_row
      on field_row.tenant_id = v_tenant_id
     and field_row.resource_id = v_resource.id
     and field_row.field_key = permission_item.key
     and field_row.enabled is true
     and field_row.sensitive is true
    where permission_item.value in ('hidden', 'masked', 'read', 'edit');
  else
    if not exists (
      select 1 from public.sys_user
      where id = p_subject_id
        and tenant_id = v_tenant_id
        and status = '1'
        and deleted_at is null
    ) then
      raise exception 'User not found or access denied';
    end if;

    select coalesce(jsonb_object_agg(field_row.field_key, permission_row.access_level), '{}'::jsonb)
      into v_before
    from public.sys_user_field_permission permission_row
    join public.sys_permission_field field_row on field_row.id = permission_row.field_id
    where permission_row.tenant_id = v_tenant_id
      and permission_row.user_id = p_subject_id
      and permission_row.resource_id = v_resource.id;

    delete from public.sys_user_field_permission
    where tenant_id = v_tenant_id
      and user_id = p_subject_id
      and resource_id = v_resource.id;

    insert into public.sys_user_field_permission (
      tenant_id, user_id, resource_id, field_id, access_level, create_by, update_by
    )
    select v_tenant_id, p_subject_id, v_resource.id, field_row.id,
           permission_item.value, 'platform-owner@example.com', 'platform-owner@example.com'
    from jsonb_each_text(p_permissions) permission_item
    join public.sys_permission_field field_row
      on field_row.tenant_id = v_tenant_id
     and field_row.resource_id = v_resource.id
     and field_row.field_key = permission_item.key
     and field_row.enabled is true
     and field_row.sensitive is true
    where permission_item.value in ('hidden', 'masked', 'read', 'edit');
  end if;

  if exists (
    select 1
    from jsonb_each_text(p_permissions) permission_item
    where permission_item.value is null
       or permission_item.value not in ('hidden', 'masked', 'read', 'edit')
  ) or (
    select count(*) from jsonb_each_text(p_permissions)
  ) <> (
    select count(*)
    from jsonb_each_text(p_permissions) permission_item
    join public.sys_permission_field field_row
      on field_row.tenant_id = v_tenant_id
     and field_row.resource_id = v_resource.id
     and field_row.field_key = permission_item.key
     and field_row.enabled is true
     and field_row.sensitive is true
  ) then
    raise exception 'Permissions contain an unknown field or access level';
  end if;

  v_after := p_permissions;

  insert into public.sys_permission_audit_log (
    tenant_id,
    actor_user_id,
    target_type,
    target_id,
    resource_id,
    action,
    before_value,
    after_value,
    create_by
  )
  values (
    v_tenant_id,
    v_actor_user_id,
    p_subject_type || '_field',
    p_subject_id,
    v_resource.id,
    case when p_permissions = '{}'::jsonb then 'clear' else 'replace' end,
    v_before,
    v_after,
    coalesce((select auth.jwt() ->> 'email'), 'unknown')
  );
end;
$$;


ALTER FUNCTION "public"."set_field_permissions"("p_resource_key" "text", "p_subject_type" "text", "p_subject_id" "uuid", "p_permissions" "jsonb") OWNER TO "postgres";

--

--
-- Name: set_role_menus("uuid", "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."set_role_menus"("p_role_id" "uuid", "p_menu_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
declare
  v_tenant_id uuid;
  v_role_code text;
  v_current_tenant_id uuid := app_private.current_user_tenant_id();
  v_is_platform_super boolean := app_private.is_platform_super();
begin
  if not app_private.has_permission('System:Role:AssignPermission') then
    raise exception 'Missing permission: System:Role:AssignPermission';
  end if;

  select role.tenant_id, upper(role.role_code)
    into v_tenant_id, v_role_code
  from public.sys_role as role
  where role.id = p_role_id;

  if not found then
    raise exception 'Role not found or access denied';
  end if;

  if v_tenant_id is null then
    raise exception 'Role tenant is missing';
  end if;

  if v_role_code = 'R_SUPER' then
    raise exception 'Super admin role has all permissions and does not support menu allocation';
  end if;

  if v_role_code = 'R_REGISTER' and not v_is_platform_super then
    raise exception 'Default register role menus can only be assigned by platform super administrator';
  end if;

  if not v_is_platform_super and v_tenant_id is distinct from v_current_tenant_id then
    raise exception 'Cannot assign menus to a role outside the current tenant';
  end if;

  delete from public.sys_role_menu
  where role_id = p_role_id;

  if coalesce(cardinality(p_menu_ids), 0) > 0 then
    insert into public.sys_role_menu (role_id, menu_id, tenant_id)
    select p_role_id, menu_id, v_tenant_id
    from (
      select distinct unnest(p_menu_ids) as menu_id
    ) selected
    where menu_id is not null
    on conflict (role_id, menu_id) do nothing;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_role_menus"("p_role_id" "uuid", "p_menu_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: set_vehicle_parts_category_level(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."set_vehicle_parts_category_level"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_level integer;
begin
  if new.parent_id is null then
    new.category_level := 1;
  else
    select category_level into parent_level
    from public.mdm_part_category
    where id = new.parent_id;

    if parent_level is null then
      raise exception 'Parent category % does not exist', new.parent_id;
    end if;

    new.category_level := parent_level + 1;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."set_vehicle_parts_category_level"() OWNER TO "postgres";

