--
-- Name: trg_create_tenant_root_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_create_tenant_root_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  insert into public.mdm_organization (
    tenant_id,
    organization_code,
    organization_name,
    organization_type,
    status,
    sort,
    description,
    is_system,
    create_by,
    update_by
  ) values (
    new.id,
    'ROOT',
    new.tenant_name,
    'company',
    '1',
    0,
    '租户根组织，由系统自动维护',
    true,
    coalesce(new.create_by, 'platform-owner@example.com'),
    coalesce(new.update_by, new.create_by, 'platform-owner@example.com')
  )
  on conflict (tenant_id, organization_code) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_create_tenant_root_organization"() OWNER TO "postgres";

--

--
-- Name: trg_default_system_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_default_system_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.organization_id is null then
    select o.id
    into new.organization_id
    from public.mdm_organization o
    where o.tenant_id = new.tenant_id
      and o.is_system is true
    limit 1;
  end if;

  if new.organization_id is not null and not exists (
    select 1
    from public.mdm_organization o
    where o.id = new.organization_id
      and o.tenant_id = new.tenant_id
  ) then
    raise exception '用户或角色不能关联到其他租户的组织';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_default_system_organization"() OWNER TO "postgres";

--

--
-- Name: trg_guard_sys_user_authorization_fields(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_guard_sys_user_authorization_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_is_service_role boolean := current_user in ('postgres', 'service_role')
    or coalesce(auth.jwt() ->> 'role', '') = 'service_role';
  v_is_self boolean := old.auth_user_id = auth.uid();
  v_roles_changed boolean := new.user_roles is distinct from old.user_roles;
  v_authorization_changed boolean :=
    new.tenant_id is distinct from old.tenant_id
    or new.organization_id is distinct from old.organization_id
    or new.user_type is distinct from old.user_type
    or new.status is distinct from old.status
    or new.auth_user_id is distinct from old.auth_user_id;
  v_profile_changed boolean :=
    new.user_name is distinct from old.user_name
    or new.nick_name is distinct from old.nick_name
    or new.user_gender is distinct from old.user_gender
    or new.user_phone is distinct from old.user_phone
    or new.user_email is distinct from old.user_email
    or new.extra is distinct from old.extra
    or new.remark is distinct from old.remark
    or new.avatar is distinct from old.avatar;
begin
  if v_is_service_role then
    return new;
  end if;

  if new.id is distinct from old.id
    or new.create_by is distinct from old.create_by
    or new.create_time is distinct from old.create_time
  then
    raise exception '用户主键和创建信息不可修改';
  end if;

  if v_roles_changed
    and not app_private.has_permission('System:User:AssignRole')
  then
    raise exception '缺少用户角色分配权限';
  end if;

  if v_authorization_changed
    and not app_private.has_permission('System:User:Edit')
  then
    raise exception '缺少用户管理权限，不能修改租户、组织、类型或账号状态';
  end if;

  if v_profile_changed
    and not v_is_self
    and not app_private.has_permission('System:User:Edit')
  then
    raise exception '缺少用户编辑权限';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_guard_sys_user_authorization_fields"() OWNER TO "postgres";

--

--
-- Name: trg_guard_system_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_guard_system_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' and old.is_system then
    raise exception '租户根组织不允许删除';
  end if;

  if tg_op = 'UPDATE' and old.is_system and (
    new.tenant_id is distinct from old.tenant_id
    or new.parent_id is distinct from old.parent_id
    or new.organization_code is distinct from old.organization_code
    or new.organization_type is distinct from old.organization_type
    or new.status is distinct from old.status
    or not new.is_system
  ) then
    raise exception '租户根组织的编码、类型、层级和状态受系统保护';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."trg_guard_system_organization"() OWNER TO "postgres";

--

--
-- Name: trg_guard_tms_cash_payment_application(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_guard_tms_cash_payment_application"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_app record;
begin
  if tg_op <> 'INSERT' or new.direction <> 'payment' then return new; end if;
  if new.payment_application_id is null then
    if not app_private.is_platform_super() then
      raise exception '承运商付款必须先提交付款申请并完成审批';
    end if;
    return new;
  end if;
  if coalesce(pg_catalog.current_setting('app.payment_application_engine',true),'off') <> 'on' then
    raise exception '付款流水只能由已批准付款申请生成';
  end if;
  select * into v_app from public.tms_carrier_payment_application
  where id=new.payment_application_id for update;
  if not found or v_app.status <> 'approved' then raise exception '付款申请不存在或尚未批准'; end if;
  if new.tenant_id is distinct from v_app.tenant_id
     or new.carrier_id is distinct from v_app.carrier_id
     or round(new.amount,2) is distinct from v_app.amount then
    raise exception '付款流水与付款申请的租户、承运商或金额不一致';
  end if;
  return new;
end; $$;


ALTER FUNCTION "public"."trg_guard_tms_cash_payment_application"() OWNER TO "postgres";

--

--
-- Name: trg_set_create_time_and_by(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_set_create_time_and_by"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- set create_time if column exists and is null
  IF TG_ARGV[0] = 'true' THEN
    BEGIN
      IF NEW.create_time IS NULL THEN
        NEW.create_time := now();
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  -- set create_by if column exists and is null
  -- Use auth.jwt() ->> 'email' as the source of truth
  IF TG_ARGV[1] = 'true' THEN
    BEGIN
      IF NEW.create_by IS NULL OR NEW.create_by = '' THEN
        -- prefer JWT email; fallback to 'unknown' if not present
        NEW.create_by := COALESCE((auth.jwt() ->> 'email'), 'unknown');
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_set_create_time_and_by"() OWNER TO "postgres";

--

--
-- Name: trg_set_update_time_and_by(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_set_update_time_and_by"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  begin
    new.update_time := now();
  exception when undefined_column then
    null;
  end;

  begin
    new.update_by := coalesce(
      nullif(public.get_app_user_display_name(), ''),
      nullif(auth.jwt() ->> 'email', ''),
      nullif(old.update_by, ''),
      'unknown'
    );
  exception when undefined_column then
    null;
  end;

  return new;
end
$$;


ALTER FUNCTION "public"."trg_set_update_time_and_by"() OWNER TO "postgres";

--

--
-- Name: trg_validate_sys_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_sys_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.parent_id = new.id then
    raise exception '组织不能将自身设置为上级组织';
  end if;

  if new.leader_user_id is not null and not exists (
    select 1
    from public.sys_user u
    where u.id = new.leader_user_id
      and u.tenant_id = new.tenant_id
  ) then
    raise exception '组织负责人必须属于同一租户';
  end if;

  if new.parent_id is not null and exists (
    with recursive ancestors as (
      select o.id, o.parent_id
      from public.mdm_organization o
      where o.id = new.parent_id

      union all

      select parent.id, parent.parent_id
      from public.mdm_organization parent
      join ancestors child on child.parent_id = parent.id
    )
    select 1 from ancestors where id = new.id
  ) then
    raise exception '组织层级不能形成循环';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_validate_sys_organization"() OWNER TO "postgres";

--

--
-- Name: trg_validate_tms_carrier_payment_application(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_tms_carrier_payment_application"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_carrier record;
  v_engine text := coalesce(pg_catalog.current_setting('app.workflow_engine', true), 'off');
  v_payment_engine text := coalesce(pg_catalog.current_setting('app.payment_application_engine', true), 'off');
begin
  select c.tenant_id, c.company_name, c.enabled
  into v_carrier
  from public.mdm_carrier c
  where c.id = new.carrier_id;
  if not found then raise exception '付款承运商不存在'; end if;
  if (tg_op = 'INSERT' or new.carrier_id is distinct from old.carrier_id) and not v_carrier.enabled then
    raise exception '付款承运商已停用';
  end if;
  if not app_private.is_platform_super()
     and v_carrier.tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权为其他租户创建付款申请';
  end if;

  new.tenant_id := v_carrier.tenant_id;
  if tg_op = 'INSERT' or new.carrier_id is distinct from old.carrier_id then
    new.carrier_name_snapshot := v_carrier.company_name;
  else
    new.carrier_name_snapshot := old.carrier_name_snapshot;
  end if;
  new.amount := round(new.amount, 2);

  new.remark := nullif(btrim(new.remark), '');
  if new.planned_payment_date is null then raise exception '请选择计划付款日期'; end if;
  if coalesce(new.amount, 0) <= 0 then raise exception '申请付款金额必须大于 0'; end if;
  if jsonb_typeof(coalesce(new.basis_urls, '[]'::jsonb)) <> 'array' then
    raise exception '付款依据格式不正确';
  end if;

  if tg_op = 'UPDATE' then
    if v_engine <> 'on' and (
      new.submitted_at is distinct from old.submitted_at
      or new.submitted_by is distinct from old.submitted_by
      or new.reviewed_at is distinct from old.reviewed_at
      or new.reviewed_by is distinct from old.reviewed_by
      or new.review_remark is distinct from old.review_remark
    ) then raise exception '审批信息只能由审批引擎更新'; end if;
    if v_payment_engine <> 'on' and (
      new.paid_transaction_id is distinct from old.paid_transaction_id
      or new.paid_at is distinct from old.paid_at
      or new.paid_by is distinct from old.paid_by
      or new.cancelled_at is distinct from old.cancelled_at
      or new.cancelled_by is distinct from old.cancelled_by
      or new.cancel_reason is distinct from old.cancel_reason
    ) then raise exception '付款执行信息只能由付款执行服务更新'; end if;
    if old.status not in ('draft', 'rejected') and (
      new.carrier_id is distinct from old.carrier_id
      or new.amount is distinct from old.amount
      or new.planned_payment_date is distinct from old.planned_payment_date
      or new.payment_method is distinct from old.payment_method
      or new.basis_urls is distinct from old.basis_urls
    ) then
      raise exception '审批中或已审批的付款申请不能修改核心信息';
    end if;

    if new.status is distinct from old.status then
      if new.status in ('pending_review', 'approved', 'rejected', 'draft') and v_engine <> 'on' then
        raise exception '付款申请状态必须由审批引擎更新';
      end if;
      if new.status in ('paid', 'cancelled') and v_payment_engine <> 'on' then
        raise exception '付款申请状态必须由付款执行服务更新';
      end if;
      if not (
        (old.status in ('draft', 'rejected') and new.status in ('pending_review', 'cancelled'))
        or (old.status = 'pending_review' and new.status in ('approved', 'rejected', 'draft', 'cancelled'))
        or (old.status = 'approved' and new.status in ('paid', 'cancelled'))
      ) then
        raise exception '不允许将付款申请从 % 变更为 %', old.status, new.status;
      end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."trg_validate_tms_carrier_payment_application"() OWNER TO "postgres";

--

--
-- Name: trg_validate_tms_carrier_statement(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_tms_carrier_statement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_carrier_tenant_id uuid;
  v_carrier_name text;
  v_actor text;
begin
  select c.tenant_id, c.company_name
    into v_carrier_tenant_id, v_carrier_name
  from public.mdm_carrier c
  where c.id = new.carrier_id;

  if not found then
    raise exception '对账承运商不存在';
  end if;
  if new.period_start > new.period_end then
    raise exception '账期开始日期不能晚于结束日期';
  end if;

  if tg_op = 'INSERT' then
    new.tenant_id := v_carrier_tenant_id;
    new.carrier_name_snapshot := v_carrier_name;
    new.status := 'draft';
    new.settled_amount := 0;
    new.submitted_at := null;
    new.submitted_by := null;
    new.reviewed_at := null;
    new.reviewed_by := null;
    new.review_remark := null;
    new.voided_at := null;
    new.voided_by := null;
    new.void_reason := null;
    return new;
  end if;

  if old.status = 'voided' then
    raise exception '已作废承运商对账单不可修改';
  end if;
  if new.tenant_id is distinct from old.tenant_id
     or new.statement_no is distinct from old.statement_no
     or new.carrier_id is distinct from old.carrier_id
     or new.carrier_name_snapshot is distinct from old.carrier_name_snapshot
     or new.period_start is distinct from old.period_start
     or new.period_end is distinct from old.period_end then
    raise exception '对账单承运商、账期和单号不可修改';
  end if;
  if new.settled_amount is distinct from old.settled_amount and pg_trigger_depth() <= 1 then
    raise exception '已结金额只能由付款核销流程更新';
  end if;

  new.submitted_at := old.submitted_at;
  new.submitted_by := old.submitted_by;
  new.reviewed_at := old.reviewed_at;
  new.reviewed_by := old.reviewed_by;
  new.voided_at := old.voided_at;
  new.voided_by := old.voided_by;

  if new.status is distinct from old.status and not (
    (old.status = 'draft' and new.status in ('pending_review', 'voided'))
    or (old.status = 'pending_review' and new.status in ('draft', 'confirmed', 'voided'))
    or (old.status = 'confirmed' and new.status in ('partially_settled', 'settled', 'voided'))
    or (old.status = 'partially_settled' and new.status in ('confirmed', 'settled', 'voided'))
    or (old.status = 'settled' and new.status in ('confirmed', 'partially_settled', 'voided'))
  ) then
    raise exception '不允许的承运商对账单状态流转：% -> %', old.status, new.status;
  end if;

  v_actor := coalesce(
    nullif(public.get_app_user_display_name(), ''),
    nullif(auth.jwt() ->> 'email', ''),
    'unknown'
  );
  if new.status = 'pending_review' and old.status <> 'pending_review' then
    new.submitted_at := now();
    new.submitted_by := v_actor;
    new.reviewed_at := null;
    new.reviewed_by := null;
    new.review_remark := null;
  elsif old.status = 'pending_review' and new.status = 'confirmed' then
    new.reviewed_at := now();
    new.reviewed_by := v_actor;
  elsif old.status = 'pending_review' and new.status = 'draft' then
    if btrim(coalesce(new.review_remark, '')) = '' then
      raise exception '驳回原因不能为空';
    end if;
    new.reviewed_at := now();
    new.reviewed_by := v_actor;
  elsif new.status = 'voided' then
    if btrim(coalesce(new.void_reason, '')) = '' then
      raise exception '作废原因不能为空';
    end if;
    new.voided_at := now();
    new.voided_by := v_actor;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."trg_validate_tms_carrier_statement"() OWNER TO "postgres";

--

--
-- Name: trg_validate_tms_waybill_cost(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_tms_waybill_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_waybill_tenant_id uuid;
  v_waybill_carrier_id uuid;
  v_waybill_driver_id uuid;
  v_actor text;
begin
  select w.tenant_id, w.carrier_id, w.driver_id
    into v_waybill_tenant_id, v_waybill_carrier_id, v_waybill_driver_id
  from public.tms_waybill w
  where w.id = new.waybill_id;

  if not found then
    raise exception '关联运单不存在';
  end if;

  if tg_op = 'INSERT' then
    new.tenant_id := v_waybill_tenant_id;
    new.audit_status := 'draft';
    new.carrier_id := coalesce(new.carrier_id, v_waybill_carrier_id);
    new.driver_id := coalesce(new.driver_id, v_waybill_driver_id);
  elsif new.tenant_id is distinct from old.tenant_id then
    raise exception '费用所属租户不可修改';
  elsif new.waybill_id is distinct from old.waybill_id then
    new.tenant_id := v_waybill_tenant_id;
    new.carrier_id := coalesce(new.carrier_id, v_waybill_carrier_id);
    new.driver_id := coalesce(new.driver_id, v_waybill_driver_id);
  end if;

  if new.tenant_id is distinct from v_waybill_tenant_id then
    raise exception '费用与运单必须属于同一租户';
  end if;

  if new.carrier_id is not null and not exists (
    select 1 from public.mdm_carrier c
    where c.id = new.carrier_id and c.tenant_id = new.tenant_id
  ) then
    raise exception '承运商与费用必须属于同一租户';
  end if;

  if new.driver_id is not null and not exists (
    select 1 from public.mdm_driver d
    where d.id = new.driver_id and d.tenant_id = new.tenant_id
  ) then
    raise exception '司机与费用必须属于同一租户';
  end if;

  if tg_op = 'UPDATE' then
    if old.audit_status = 'voided' then
      raise exception '已作废费用不可修改';
    end if;

    if old.audit_status in ('pending_review', 'approved') and (
      new.waybill_id is distinct from old.waybill_id
      or new.cost_type is distinct from old.cost_type
      or new.amount is distinct from old.amount
      or new.occurred_on is distinct from old.occurred_on
      or new.payee_name is distinct from old.payee_name
      or new.carrier_id is distinct from old.carrier_id
      or new.driver_id is distinct from old.driver_id
      or new.remark is distinct from old.remark
      or new.attachments is distinct from old.attachments
    ) then
      raise exception '待审核或已审核费用不可修改业务字段';
    end if;

    if new.audit_status is distinct from old.audit_status and not (
      (old.audit_status = 'draft' and new.audit_status in ('pending_review', 'voided'))
      or (old.audit_status = 'pending_review' and new.audit_status in ('approved', 'rejected', 'draft'))
      or (old.audit_status = 'rejected' and new.audit_status in ('draft', 'pending_review', 'voided'))
      or (old.audit_status = 'approved' and new.audit_status = 'voided')
    ) then
      raise exception '不允许的费用审核状态流转：% -> %', old.audit_status, new.audit_status;
    end if;

    v_actor := coalesce(
      nullif(public.get_app_user_display_name(), ''),
      nullif(auth.jwt() ->> 'email', ''),
      'unknown'
    );

    if new.audit_status = 'pending_review' and old.audit_status <> 'pending_review' then
      new.submitted_at := now();
      new.submitted_by := v_actor;
      new.reviewed_at := null;
      new.reviewed_by := null;
      new.review_remark := null;
    elsif new.audit_status in ('approved', 'rejected')
      and new.audit_status is distinct from old.audit_status then
      new.reviewed_at := now();
      new.reviewed_by := v_actor;
    elsif new.audit_status = 'draft'
      and old.audit_status in ('rejected', 'pending_review') then
      new.reviewed_at := null;
      new.reviewed_by := null;
      new.review_remark := null;
    end if;
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."trg_validate_tms_waybill_cost"() OWNER TO "postgres";

--

--
-- Name: trg_validate_tms_waybill_status_transition(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_tms_waybill_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = old.status then
    return new;
  end if;

  if (old.status = 'pending' and new.status in ('accepted', 'cancelled'))
     or (old.status = 'accepted' and new.status in ('loading', 'cancelled'))
     or (old.status = 'loading' and new.status in ('transporting', 'cancelled'))
     or (old.status = 'transporting' and new.status in ('unloading', 'cancelled'))
     or (old.status = 'unloading' and new.status in ('signed', 'cancelled'))
     or (old.status = 'signed' and new.status in ('completed', 'cancelled')) then
    return new;
  end if;

  raise exception '运单状态不允许从 % 直接变更为 %', old.status, new.status;
end;
$$;


ALTER FUNCTION "public"."trg_validate_tms_waybill_status_transition"() OWNER TO "postgres";

--

--
-- Name: ai_feedback_resolution; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."ai_feedback_resolution" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "feedback_id" bigint NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "issue_type" "text",
    "resolution_note" "text",
    "handled_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    CONSTRAINT "ai_feedback_resolution_closed_audit_check" CHECK (((("status" = ANY (ARRAY['resolved'::"text", 'dismissed'::"text"])) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL)) OR (("status" <> ALL (ARRAY['resolved'::"text", 'dismissed'::"text"])) AND ("resolved_by" IS NULL) AND ("resolved_at" IS NULL)))),
    CONSTRAINT "ai_feedback_resolution_closed_note_check" CHECK ((("status" <> ALL (ARRAY['resolved'::"text", 'dismissed'::"text"])) OR ("length"(TRIM(BOTH FROM COALESCE("resolution_note", ''::"text"))) >= 3))),
    CONSTRAINT "ai_feedback_resolution_issue_type_check" CHECK ((("issue_type" IS NULL) OR ("issue_type" = ANY (ARRAY['incorrect'::"text", 'incomplete'::"text", 'irrelevant'::"text", 'unsafe'::"text", 'slow'::"text", 'data_quality'::"text", 'other'::"text"])))),
    CONSTRAINT "ai_feedback_resolution_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'resolved'::"text", 'dismissed'::"text"])))
);


ALTER TABLE "public"."ai_feedback_resolution" OWNER TO "postgres";

--

--
-- Name: upsert_ai_feedback_resolution(bigint, "text", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."upsert_ai_feedback_resolution"("p_feedback_id" bigint, "p_status" "text", "p_issue_type" "text" DEFAULT NULL::"text", "p_resolution_note" "text" DEFAULT NULL::"text") RETURNS "public"."ai_feedback_resolution"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_tenant_id uuid;
  result public.ai_feedback_resolution;
  normalized_note text := nullif(trim(coalesce(p_resolution_note, '')), '');
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  if not (
    (select app_private.is_platform_super())
    or (select app_private.is_tenant_admin())
  ) then
    raise exception 'Only platform or tenant administrators can handle AI feedback';
  end if;

  select feedback.tenant_id
  into target_tenant_id
  from public.ai_feedback feedback
  where feedback.id = p_feedback_id;

  if target_tenant_id is null then
    raise exception 'AI feedback does not exist or is outside the current scope';
  end if;

  insert into public.ai_feedback_resolution (
    feedback_id,
    status,
    issue_type,
    resolution_note,
    handled_by,
    resolved_by,
    resolved_at,
    tenant_id
  ) values (
    p_feedback_id,
    p_status,
    p_issue_type,
    normalized_note,
    (select auth.uid()),
    case when p_status in ('resolved', 'dismissed') then (select auth.uid()) else null end,
    case when p_status in ('resolved', 'dismissed') then current_timestamp else null end,
    target_tenant_id
  )
  on conflict (feedback_id) do update
  set status = excluded.status,
      issue_type = excluded.issue_type,
      resolution_note = excluded.resolution_note,
      handled_by = excluded.handled_by,
      resolved_by = excluded.resolved_by,
      resolved_at = excluded.resolved_at
  returning * into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."upsert_ai_feedback_resolution"("p_feedback_id" bigint, "p_status" "text", "p_issue_type" "text", "p_resolution_note" "text") OWNER TO "postgres";

--

--
-- Name: validate_tms_carrier_payment_application_submission("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_app record;
  v_item record;
  v_item_count integer;
  v_total numeric(14,2);
  v_outstanding numeric(14,2);
  v_reserved numeric(14,2);
begin
  select * into v_app from public.tms_carrier_payment_application
  where id=p_application_id for update;
  if not found then raise exception '付款申请不存在'; end if;
  if v_app.status not in ('draft','rejected') then raise exception '只有草稿或已驳回申请可以提交审批'; end if;
  if not app_private.is_platform_super() and v_app.tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权提交其他租户付款申请';
  end if;
  select count(*)::integer, coalesce(sum(applied_amount),0)::numeric(14,2)
  into v_item_count, v_total
  from public.tms_carrier_payment_application_item where application_id=p_application_id;
  if v_item_count < 1 then raise exception '请至少选择一份待付款对账单'; end if;
  if v_total is distinct from v_app.amount then raise exception '付款分配合计必须等于申请金额'; end if;

  for v_item in
    select i.*, s.status statement_status, s.settled_amount,
      coalesce((select sum(si.line_amount) from public.tms_carrier_statement_item si
                where si.statement_id=s.id and si.is_active),0)::numeric(14,2) statement_amount
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_statement s on s.id=i.statement_id
    where i.application_id=p_application_id order by i.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_item.statement_id::text, 841329));
    if v_item.statement_status not in ('confirmed','partially_settled') then
      raise exception '对账单 % 当前状态不允许付款', v_item.statement_no_snapshot;
    end if;
    v_outstanding := greatest(v_item.statement_amount-v_item.settled_amount,0)::numeric(14,2);
    select coalesce(sum(i.applied_amount),0)::numeric(14,2) into v_reserved
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_payment_application a on a.id=i.application_id
    where i.statement_id=v_item.statement_id
      and a.status in ('pending_review','approved')
      and a.id<>p_application_id;
    if v_item.applied_amount > v_outstanding-v_reserved then
      raise exception '对账单 % 可申请余额不足，当前可申请 %',
        v_item.statement_no_snapshot, greatest(v_outstanding-v_reserved,0);
    end if;
  end loop;
  return true;
end;
$$;


ALTER FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") OWNER TO "postgres";

--

--
-- Name: validate_tms_expense_reimbursement_submission_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_expense_reimbursement_submission_secure"("p_reimbursement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_reimbursement public.tms_expense_reimbursement%rowtype;
  v_access jsonb;
begin
  select reimbursement_row.*
  into v_reimbursement
  from public.tms_expense_reimbursement reimbursement_row
  where reimbursement_row.id = p_reimbursement_id
    and reimbursement_row.tenant_id = v_tenant_id;
  if not found then raise exception '费用报销单不存在或无权访问'; end if;
  if v_reimbursement.status not in ('draft', 'rejected') then
    raise exception '当前费用报销单状态不允许提交审批';
  end if;
  v_access := app_private.field_access_map(
    'tms.expense_reimbursement', v_reimbursement.created_by_user_id
  );
  if coalesce(v_access->>'reimbursementAmounts', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取报销金额并提交审批'
      using errcode = '42501';
  end if;
  if coalesce(v_access->>'payeeDetails', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取收款信息并提交审批'
      using errcode = '42501';
  end if;
  return jsonb_build_object(
    'amount', v_reimbursement.total_amount,
    'reimbursementNo', v_reimbursement.reimbursement_no,
    'paymentMethod', v_reimbursement.payment_method,
    'plannedPaymentDate', v_reimbursement.planned_payment_date,
    'itemCount', (
      select count(*)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        and item_row.tenant_id = v_reimbursement.tenant_id
    ),
    'waybillCount', (
      select count(distinct item_row.waybill_id)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        and item_row.tenant_id = v_reimbursement.tenant_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."validate_tms_expense_reimbursement_submission_secure"("p_reimbursement_id" "uuid") OWNER TO "postgres";

--

--
-- Name: validate_tms_waybill_cost_submission_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_waybill_cost_submission_secure"("p_cost_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cost public.tms_waybill_cost%rowtype;
begin
  if not app_private.can_execute_business_action(
    'FinanceWaybillCost', 'FinanceWaybillCost:Submit', null, false
  ) then
    raise exception 'Missing waybill cost submit permission' using errcode = '42501';
  end if;
  select cost_row.* into v_cost
  from public.tms_waybill_cost cost_row
  where cost_row.id = p_cost_id and cost_row.tenant_id = v_tenant_id;
  if not found then raise exception '运单费用不存在或无权访问'; end if;
  if v_cost.audit_status not in ('draft', 'rejected') then
    raise exception '当前运单费用状态不允许提交审批';
  end if;
  if app_private.resolve_field_access(
    'tms.waybill_cost', 'costAmounts', v_cost.created_by_user_id
  ) not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取费用金额并提交审批'
      using errcode = '42501';
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."validate_tms_waybill_cost_submission_secure"("p_cost_id" "uuid") OWNER TO "postgres";

