CREATE TABLE IF NOT EXISTS "public"."mdm_employee" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "organization_id" "uuid",
    "employee_no" "text" NOT NULL,
    "employee_name" "text" NOT NULL,
    "avatar_url" "text",
    "job_title" "text",
    "employment_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "employment_type" "text" DEFAULT 'full_time'::"text" NOT NULL,
    "gender" "text",
    "birth_date" "date",
    "phone" "text" NOT NULL,
    "email" "text" NOT NULL,
    "id_card_no" "text" NOT NULL,
    "education_level" "text",
    "school_name" "text",
    "major_name" "text",
    "marital_status" "text",
    "political_status" "text",
    "native_place" "text",
    "home_address" "text",
    "hire_date" "date",
    "probation_end_date" "date",
    "leave_date" "date",
    "contract_start_date" "date",
    "contract_end_date" "date",
    "emergency_contact_name" "text",
    "emergency_contact_relation" "text",
    "emergency_contact_phone" "text",
    "remark" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ethnicity" "text",
    "position_id" "uuid" NOT NULL,
    "created_by_user_id" "uuid",
    CONSTRAINT "hr_employee_dates_check" CHECK (((("contract_end_date" IS NULL) OR ("contract_start_date" IS NULL) OR ("contract_end_date" >= "contract_start_date")) AND (("leave_date" IS NULL) OR ("hire_date" IS NULL) OR ("leave_date" >= "hire_date")))),
    CONSTRAINT "hr_employee_email_format_check" CHECK (("email" ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'::"text")),
    CONSTRAINT "hr_employee_email_required_check" CHECK (("btrim"("email") <> ''::"text")),
    CONSTRAINT "hr_employee_id_card_no_format_check" CHECK ((("id_card_no" ~ '^[0-9]{15}$'::"text") OR ("id_card_no" ~ '^[0-9]{17}[0-9Xx]$'::"text"))),
    CONSTRAINT "hr_employee_id_card_no_required_check" CHECK (("btrim"("id_card_no") <> ''::"text")),
    CONSTRAINT "hr_employee_phone_format_check" CHECK (("phone" ~ '^1[3-9][0-9]{9}$'::"text")),
    CONSTRAINT "hr_employee_phone_required_check" CHECK (("btrim"("phone") <> ''::"text")),
    CONSTRAINT "hr_employee_status_check" CHECK (("employment_status" = ANY (ARRAY['probation'::"text", 'active'::"text", 'leave'::"text", 'terminated'::"text"]))),
    CONSTRAINT "hr_employee_type_check" CHECK (("employment_type" = ANY (ARRAY['full_time'::"text", 'part_time'::"text", 'intern'::"text", 'contractor'::"text"])))
);


