    "grade_id" "uuid",
    "business_title" "text",
    "assignment_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "primary_assignment" boolean DEFAULT true NOT NULL,
    "fte" numeric(5,4) DEFAULT 1 NOT NULL,
    "effective_start" "date" NOT NULL,
    "effective_end" "date",
    "source_type" "text" DEFAULT 'employee_profile'::"text" NOT NULL,
    "source_change_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_employee_assignment_dates_check" CHECK ((("effective_end" IS NULL) OR ("effective_end" >= "effective_start"))),
    CONSTRAINT "hr_employee_assignment_fte_check" CHECK ((("fte" > (0)::numeric) AND ("fte" <= (1)::numeric))),
    CONSTRAINT "hr_employee_assignment_status_check" CHECK (("assignment_status" = ANY (ARRAY['active'::"text", 'suspended'::"text", 'ended'::"text"]))),
    CONSTRAINT "hr_employee_assignment_version_positive" CHECK (("version" > 0))
);


