CREATE TABLE IF NOT EXISTS "public"."mdm_equipment" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "category_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "using_organization_id" "uuid" NOT NULL,
    "managing_organization_id" "uuid" NOT NULL,
    "responsible_employee_id" "uuid",
    "supplier_id" "uuid",
    "equipment_code" "text" NOT NULL,
    "equipment_name" "text" NOT NULL,
    "equipment_short_name" "text",
    "equipment_kind" "text" DEFAULT 'general'::"text" NOT NULL,
    "specification" "text",
    "model" "text",
    "manufacturer" "text",
    "factory_no" "text",
    "manufacture_date" "date",
    "installation_date" "date",
    "commissioning_date" "date",
    "enable_date" "date",
    "use_status" "text" DEFAULT 'in_use'::"text" NOT NULL,
    "operation_status" "text" DEFAULT 'normal'::"text" NOT NULL,
    "asset_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "importance_level" "text" DEFAULT 'general'::"text" NOT NULL,
    "asset_original_value" numeric(18,2),
    "service_life_years" numeric(8,2),
    "net_value" numeric(18,2),
    "fixed_asset_no" "text",
    "erp_code" "text",
    "electronic_tag_code" "text",
    "qr_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "is_major_hazard_source" boolean DEFAULT false NOT NULL,
    "is_special_equipment" boolean DEFAULT false NOT NULL,
    "remark" "text",
    "status" "text" DEFAULT 'enabled'::"text" NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sort" integer DEFAULT 10 NOT NULL,
    "registration_code" "text",
    "internal_no" "text",
    "use_certificate_no" "text",
    "detail_location" "text",
    "maintenance_organization" "text",
    "installation_organization" "text",
    "design_organization" "text",
    "maintenance_qualification_url" "text",
    "use_registration_certificate_url" "text",
    "nameplate_url" "text",
    "photo_url" "text",
    "special_parameters" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "production_department_id" "uuid",
    "work_center_id" "uuid",
    "equipment_brand" "text",
    "acceptance_date" "date",
    "traffic_light_card_no" "text",
    "andon_box_no" "text",
    "pulse_interval_seconds" integer,
    "standard_utilization" numeric(5,2),
    "sync_work_center" boolean DEFAULT false NOT NULL,
    CONSTRAINT "mdm_equipment_pulse_interval_check" CHECK ((("pulse_interval_seconds" IS NULL) OR (("pulse_interval_seconds" >= 1) AND ("pulse_interval_seconds" <= 86400)))),
    CONSTRAINT "mdm_equipment_standard_utilization_check" CHECK ((("standard_utilization" IS NULL) OR (("standard_utilization" >= (0)::numeric) AND ("standard_utilization" <= (100)::numeric)))),
    CONSTRAINT "smis_equipment_asset_original_value_check" CHECK ((("asset_original_value" IS NULL) OR ("asset_original_value" >= (0)::numeric))),
    CONSTRAINT "smis_equipment_asset_status_check" CHECK (("asset_status" = ANY (ARRAY['active'::"text", 'pending_disposal'::"text", 'disposed'::"text"]))),
    CONSTRAINT "smis_equipment_code_length" CHECK (("char_length"("equipment_code") <= 60)),
    CONSTRAINT "smis_equipment_code_not_blank" CHECK (("btrim"("equipment_code") <> ''::"text")),
    CONSTRAINT "smis_equipment_kind_check" CHECK (("equipment_kind" = ANY (ARRAY['general'::"text", 'boiler'::"text", 'pressure_gauge'::"text", 'safety_valve'::"text"]))),
    CONSTRAINT "smis_equipment_name_length" CHECK (("char_length"("equipment_name") <= 120)),
    CONSTRAINT "smis_equipment_name_not_blank" CHECK (("btrim"("equipment_name") <> ''::"text")),
    CONSTRAINT "smis_equipment_net_value_check" CHECK ((("net_value" IS NULL) OR ("net_value" >= (0)::numeric))),
    CONSTRAINT "smis_equipment_operation_status_check" CHECK (("operation_status" = ANY (ARRAY['normal'::"text", 'maintenance'::"text", 'fault'::"text", 'idle'::"text"]))),
    CONSTRAINT "smis_equipment_remark_length" CHECK ((("remark" IS NULL) OR ("char_length"("remark") <= 1000))),
    CONSTRAINT "smis_equipment_service_life_check" CHECK ((("service_life_years" IS NULL) OR ("service_life_years" > (0)::numeric))),
    CONSTRAINT "smis_equipment_short_name_length" CHECK ((("equipment_short_name" IS NULL) OR ("char_length"("equipment_short_name") <= 60))),
    CONSTRAINT "smis_equipment_sort_range_check" CHECK ((("sort" >= 0) AND ("sort" <= 999999))),
    CONSTRAINT "smis_equipment_special_parameters_object" CHECK (("jsonb_typeof"("special_parameters") = 'object'::"text")),
    CONSTRAINT "smis_equipment_status_check" CHECK (("status" = ANY (ARRAY['enabled'::"text", 'disabled'::"text"]))),
    CONSTRAINT "smis_equipment_use_status_check" CHECK (("use_status" = ANY (ARRAY['in_use'::"text", 'stopped'::"text", 'scrapped'::"text", 'dismantled'::"text", 'installing'::"text"])))
);


