    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "smis_site_address_length_check" CHECK (("char_length"(COALESCE("address_detail", ''::"text")) <= 300)),
    CONSTRAINT "smis_site_category_not_blank" CHECK (("btrim"("category_code") <> ''::"text")),
    CONSTRAINT "smis_site_coordinate_pair_check" CHECK ((("longitude" IS NULL) = ("latitude" IS NULL))),
    CONSTRAINT "smis_site_image_urls_array_check" CHECK (("jsonb_typeof"("image_urls") = 'array'::"text")),
    CONSTRAINT "smis_site_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "smis_site_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "smis_site_name_length_check" CHECK (("char_length"("site_name") <= 120)),
    CONSTRAINT "smis_site_name_not_blank" CHECK (("btrim"("site_name") <> ''::"text")),
    CONSTRAINT "smis_site_parent_self_check" CHECK ((("parent_id" IS NULL) OR ("parent_id" <> "id"))),
    CONSTRAINT "smis_site_remark_length_check" CHECK (("char_length"(COALESCE("remark", ''::"text")) <= 500)),
    CONSTRAINT "smis_site_sort_check" CHECK ((("sort" >= 0) AND ("sort" <= 999999)))
);


ALTER TABLE "public"."mdm_site" OWNER TO "postgres";

--

--
-- Name: TABLE "mdm_site"; Type: COMMENT; Schema: public
--

--

COMMENT ON TABLE "public"."mdm_site" IS 'MDM 场所主数据；连接组织、负责人、行政区域和空间坐标。';


--

--
-- Name: mdm_storage_location; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."mdm_storage_location" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "parent_id" "uuid",
    "organization_id" "uuid" NOT NULL,
    "responsible_employee_id" "uuid",
    "location_code" "text" NOT NULL,
    "location_name" "text" NOT NULL,
    "location_short_name" "text",
    "detail_location" "text",
    "remark" "text",
    "status" "text" DEFAULT 'enabled'::"text" NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "smis_storage_location_code_length" CHECK (("char_length"("location_code") <= 40)),
    CONSTRAINT "smis_storage_location_code_not_blank" CHECK (("btrim"("location_code") <> ''::"text")),
    CONSTRAINT "smis_storage_location_detail_length" CHECK ((("detail_location" IS NULL) OR ("char_length"("detail_location") <= 300))),
    CONSTRAINT "smis_storage_location_name_length" CHECK (("char_length"("location_name") <= 100)),
    CONSTRAINT "smis_storage_location_name_not_blank" CHECK (("btrim"("location_name") <> ''::"text")),
    CONSTRAINT "smis_storage_location_not_self_parent" CHECK ((("parent_id" IS NULL) OR ("parent_id" <> "id"))),
    CONSTRAINT "smis_storage_location_remark_length" CHECK ((("remark" IS NULL) OR ("char_length"("remark") <= 500))),
    CONSTRAINT "smis_storage_location_short_name_length" CHECK ((("location_short_name" IS NULL) OR ("char_length"("location_short_name") <= 50))),
    CONSTRAINT "smis_storage_location_status_check" CHECK (("status" = ANY (ARRAY['enabled'::"text", 'disabled'::"text"])))
);


ALTER TABLE "public"."mdm_storage_location" OWNER TO "postgres";

