--
-- Name: mdm_catalog_projection; Type: VIEW; Schema: app_private
--

--

CREATE OR REPLACE VIEW "app_private"."mdm_catalog_projection" AS
 SELECT "mdm_organization"."tenant_id",
    'organization'::"text" AS "domain_key",
    'organization'::"text" AS "scope_key",
    'organization'::"text" AS "source_type",
    '组织机构'::"text" AS "source_label",
    'platform'::"text" AS "source_app",
    "mdm_organization"."id",
    "mdm_organization"."organization_code" AS "code",
    "mdm_organization"."organization_name" AS "name",
    "mdm_organization"."status",
    ("lower"("mdm_organization"."status") <> ALL (ARRAY['0'::"text", 'disabled'::"text", 'inactive'::"text"])) AS "is_active",
    COALESCE("mdm_organization"."organization_type", '组织类型待补充'::"text") AS "subtitle",
    "jsonb_build_array"("jsonb_build_object"('label', '组织类型', 'value', "mdm_organization"."organization_type"), "jsonb_build_object"('label', '系统组织', 'value',
        CASE
            WHEN "mdm_organization"."is_system" THEN '是'::"text"
            ELSE '否'::"text"
        END), "jsonb_build_object"('label', '地址', 'value', "mdm_organization"."address"), "jsonb_build_object"('label', '说明', 'value', "mdm_organization"."description")) AS "attributes",
    (100 -
        CASE
            WHEN (NULLIF("btrim"("mdm_organization"."organization_type"), ''::"text") IS NULL) THEN 15
            ELSE 0
        END) AS "quality_score",
    "array_remove"(ARRAY[
        CASE
            WHEN (NULLIF("btrim"("mdm_organization"."organization_type"), ''::"text") IS NULL) THEN '组织类型待补充'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "quality_issues",
    "mdm_organization"."create_time",
    "mdm_organization"."update_time"
   FROM "public"."mdm_organization"
UNION ALL
 SELECT "mdm_job_family"."tenant_id",
