    "mdm_site"."update_time"
   FROM "public"."mdm_site"
UNION ALL
 SELECT "mdm_storage_location"."tenant_id",
    'material'::"text" AS "domain_key",
    'material'::"text" AS "scope_key",
    'storage_location'::"text" AS "source_type",
    '存放位置'::"text" AS "source_label",
    'smis'::"text" AS "source_app",
    "mdm_storage_location"."id",
    "mdm_storage_location"."location_code" AS "code",
    "mdm_storage_location"."location_name" AS "name",
    "mdm_storage_location"."status",
    ("lower"("mdm_storage_location"."status") <> ALL (ARRAY['0'::"text", 'disabled'::"text", 'inactive'::"text"])) AS "is_active",
    COALESCE("mdm_storage_location"."location_short_name", "mdm_storage_location"."detail_location", '位置说明待补充'::"text") AS "subtitle",
    "jsonb_build_array"("jsonb_build_object"('label', '位置简称', 'value', "mdm_storage_location"."location_short_name"), "jsonb_build_object"('label', '详细位置', 'value', "mdm_storage_location"."detail_location"), "jsonb_build_object"('label', '说明', 'value', "mdm_storage_location"."remark")) AS "attributes",
    (100 -
        CASE
            WHEN (NULLIF("btrim"("mdm_storage_location"."detail_location"), ''::"text") IS NULL) THEN 10
            ELSE 0
        END) AS "quality_score",
    "array_remove"(ARRAY[
        CASE
            WHEN (NULLIF("btrim"("mdm_storage_location"."detail_location"), ''::"text") IS NULL) THEN '详细位置待补充'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "quality_issues",
    "mdm_storage_location"."create_time",
    "mdm_storage_location"."update_time"
   FROM "public"."mdm_storage_location"
UNION ALL
 SELECT "a"."tenant_id",
    'organization'::"text" AS "domain_key",
    'employee'::"text" AS "scope_key",
    'employee_assignment'::"text" AS "source_type",
    '员工任职'::"text" AS "source_label",
    'hr'::"text" AS "source_app",
    "a"."id",
    "e"."employee_no" AS "code",
    "e"."employee_name" AS "name",
    "a"."assignment_status" AS "status",
    (("a"."assignment_status" = 'active'::"text") AND ("a"."effective_start" <= CURRENT_DATE) AND (("a"."effective_end" IS NULL) OR ("a"."effective_end" >= CURRENT_DATE))) AS "is_active",
    "concat_ws"(' · '::"text", "o"."organization_name", "p"."position_name", "a"."business_title") AS "subtitle",
    "jsonb_build_array"("jsonb_build_object"('label', '员工编号', 'value', "e"."employee_no"), "jsonb_build_object"('label', '所属组织', 'value', "o"."organization_name"), "jsonb_build_object"('label', '岗位', 'value', "p"."position_name"), "jsonb_build_object"('label', '主要任职', 'value', "a"."primary_assignment"), "jsonb_build_object"('label', '生效日期', 'value', "a"."effective_start"), "jsonb_build_object"('label', '结束日期', 'value', "a"."effective_end")) AS "attributes",
    ((100 -
        CASE
            WHEN ("o"."id" IS NULL) THEN 25
            ELSE 0
        END) -
        CASE
            WHEN ("p"."id" IS NULL) THEN 15
            ELSE 0
        END) AS "quality_score",
    "array_remove"(ARRAY[
        CASE
            WHEN ("o"."id" IS NULL) THEN '所属组织待关联'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("p"."id" IS NULL) THEN '岗位待关联'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "quality_issues",
    "a"."create_time",
    "a"."update_time"
   FROM ((("public"."mdm_employee_assignment" "a"
     JOIN "public"."mdm_employee" "e" ON ((("e"."id" = "a"."employee_id") AND ("e"."tenant_id" = "a"."tenant_id"))))
     LEFT JOIN "public"."mdm_organization" "o" ON ((("o"."id" = "a"."organization_id") AND ("o"."tenant_id" = "a"."tenant_id"))))
     LEFT JOIN "public"."mdm_position" "p" ON ((("p"."id" = "a"."position_id") AND ("p"."tenant_id" = "a"."tenant_id"))))
UNION ALL
 SELECT "a"."tenant_id",
    'logistics'::"text" AS "domain_key",
    'logistics'::"text" AS "scope_key",
    'customer_address'::"text" AS "source_type",
    '客户地址'::"text" AS "source_label",
    'tms'::"text" AS "source_app",
    "a"."id",
    "c"."customer_code" AS "code",
    "concat_ws"(' · '::"text", "c"."customer_name", NULLIF("a"."address_detail", ''::"text")) AS "name",
        CASE
            WHEN "c"."enabled" THEN 'enabled'::"text"
            ELSE 'disabled'::"text"
        END AS "status",
    "c"."enabled" AS "is_active",
    "concat_ws"(' · '::"text", "a"."region", "a"."address_detail") AS "subtitle",
    "jsonb_build_array"("jsonb_build_object"('label', '所属客户', 'value', "c"."customer_name"), "jsonb_build_object"('label', '客户编码', 'value', "c"."customer_code"), "jsonb_build_object"('label', '所在地区', 'value', "a"."region"), "jsonb_build_object"('label', '详细地址', 'value', "a"."address_detail"), "jsonb_build_object"('label', '默认地址', 'value', "a"."is_default"), "jsonb_build_object"('label', '已定位', 'value', (("a"."longitude" IS NOT NULL) AND ("a"."latitude" IS NOT NULL)))) AS "attributes",
    (((100 -
        CASE
            WHEN (NULLIF("btrim"("a"."region"), ''::"text") IS NULL) THEN 15
            ELSE 0
        END) -
        CASE
            WHEN (NULLIF("btrim"("a"."address_detail"), ''::"text") IS NULL) THEN 25
            ELSE 0
        END) -
        CASE
            WHEN (("a"."longitude" IS NULL) OR ("a"."latitude" IS NULL)) THEN 10
            ELSE 0
        END) AS "quality_score",
    "array_remove"(ARRAY[
        CASE
            WHEN (NULLIF("btrim"("a"."region"), ''::"text") IS NULL) THEN '所在地区待补充'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NULLIF("btrim"("a"."address_detail"), ''::"text") IS NULL) THEN '详细地址待补充'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("a"."longitude" IS NULL) OR ("a"."latitude" IS NULL)) THEN '地理坐标待补充'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "quality_issues",
    "a"."create_time",
    "a"."update_time"
   FROM ("public"."mdm_customer_address" "a"
     JOIN "public"."mdm_customer" "c" ON ((("c"."id" = "a"."customer_id") AND ("c"."tenant_id" = "a"."tenant_id"))));


