CREATE TABLE IF NOT EXISTS "public"."ai_artifact_review" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ai_run_id" "uuid" NOT NULL,
    "auth_user_id" "uuid" NOT NULL,
    "feature" "text" NOT NULL,
    "artifact_type" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "proposed_payload" "jsonb" NOT NULL,
    "final_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "confidence" numeric(5,4),
    "field_confidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "warnings" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "accepted_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "corrected_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "entity_type" "text",
    "entity_id" "uuid",
    "review_note" "text",
    "reviewed_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "raw_ocr_text" "text" DEFAULT ''::"text" NOT NULL,
    CONSTRAINT "ai_artifact_review_applied_entity_check" CHECK ((("status" <> 'applied'::"text") OR (("entity_type" IS NOT NULL) AND ("entity_id" IS NOT NULL) AND ("final_payload" <> '{}'::"jsonb")))),
    CONSTRAINT "ai_artifact_review_confidence_check" CHECK ((("confidence" IS NULL) OR (("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric)))),
    CONSTRAINT "ai_artifact_review_feature_check" CHECK (("feature" <> ''::"text")),
    CONSTRAINT "ai_artifact_review_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'applied'::"text", 'rejected'::"text", 'superseded'::"text"]))),
    CONSTRAINT "ai_artifact_review_type_check" CHECK (("artifact_type" <> ''::"text"))
);


