    CONSTRAINT "ai_feature_config_feature_not_blank" CHECK (("btrim"("feature") <> ''::"text")),
    CONSTRAINT "ai_feature_config_max_tokens_range" CHECK ((("max_tokens" >= 100) AND ("max_tokens" <= 4096))),
