    CONSTRAINT "ai_feature_config_retry_range" CHECK ((("max_retries" >= 0) AND ("max_retries" <= 2))),
    CONSTRAINT "ai_feature_config_temperature_range" CHECK ((("temperature" >= (0)::numeric) AND ("temperature" <= (2)::numeric))),
    CONSTRAINT "ai_feature_config_timeout_range" CHECK ((("timeout_ms" >= 5000) AND ("timeout_ms" <= 120000)))
);


