CREATE TABLE IF NOT EXISTS "public"."ai_security_event" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "run_id" "uuid",
    "tool_call_id" bigint,
    "feedback_id" bigint,
    "event_type" "text" NOT NULL,
    "severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "decision" "text" DEFAULT 'observed'::"text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "detail" "text",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "detected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_security_event_decision_check" CHECK (("decision" = ANY (ARRAY['observed'::"text", 'blocked'::"text", 'allowed'::"text"]))),
    CONSTRAINT "ai_security_event_event_type_check" CHECK (("event_type" = ANY (ARRAY['unsafe_output'::"text", 'access_denied'::"text", 'prompt_injection'::"text", 'sensitive_data'::"text", 'tool_failure'::"text", 'model_failure'::"text"]))),
    CONSTRAINT "ai_security_event_evidence_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "ai_security_event_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "ai_security_event_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'investigating'::"text", 'blocked'::"text", 'resolved'::"text", 'false_positive'::"text"])))
);


