    "risk" "text" NOT NULL,
    "prompt" "text" NOT NULL,
    "acceptance_criteria" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
