    CONSTRAINT "ai_suggestion_category_check" CHECK (("category" = ANY (ARRAY['product'::"text", 'business'::"text", 'ui_ux'::"text", 'security'::"text", 'performance'::"text", 'quality'::"text", 'developer_experience'::"text"]))),
    CONSTRAINT "ai_suggestion_confidence_check" CHECK ((("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric))),
    CONSTRAINT "ai_suggestion_effort_check" CHECK (("effort" = ANY (ARRAY['small'::"text", 'medium'::"text", 'large'::"text"]))),
    CONSTRAINT "ai_suggestion_impact_check" CHECK ((("impact" >= 1) AND ("impact" <= 5))),
    CONSTRAINT "ai_suggestion_position_check" CHECK ((("position" >= 1) AND ("position" <= 20))),
    CONSTRAINT "ai_suggestion_prompt_not_blank" CHECK (("btrim"("prompt") <> ''::"text")),
    CONSTRAINT "ai_suggestion_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'accepted'::"text", 'completed'::"text", 'dismissed'::"text", 'expired'::"text"]))),
    CONSTRAINT "ai_suggestion_title_not_blank" CHECK (("btrim"("title") <> ''::"text"))
);


