--

--
-- Name: ai_suggestion_event_id_seq; Type: SEQUENCE; Schema: public
--

DO $identity_column$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_attribute a
     WHERE a.attrelid = 'public.ai_suggestion_event'::regclass
       AND a.attname = 'id'
       AND a.attidentity <> ''
  ) THEN
--

ALTER TABLE "public"."ai_suggestion_event" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."ai_suggestion_event_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
  END IF;
END
$identity_column$;

