--

--
-- Name: mes_work_order; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."mes_work_order" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "work_order_no" "text" NOT NULL,
    "work_order_type_id" "uuid",
    "project_id" "uuid",
    "construction_no" "text",
    "material_id" "uuid" NOT NULL,
    "order_quantity" numeric(18,4) NOT NULL,
    "production_unit_id" "uuid",
    "planned_start_date" "date",
    "planned_end_date" "date" NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "status_reason" "text",
    "remark" "text" DEFAULT ''::"text" NOT NULL,
    "special_requirement" "text",
    "tracking_no" "text",
    "follow_no" "text",
    "merchandiser_id" "uuid",
    "salesperson_id" "uuid",
    "customer_code" "text",
    "custom_process_code" "text",
    "specification_quantity" "text",
    "sales_order_no" "text",
    "sales_order_quantity" numeric(18,4),
    "completed_quantity" numeric(18,4) DEFAULT 0 NOT NULL,
    "warehoused_quantity" numeric(18,4) DEFAULT 0 NOT NULL,
    "print_count" integer DEFAULT 0 NOT NULL,
    "material_code_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "material_name_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "specification_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "unit_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "project_name_snapshot" "text",
    "bom_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "route_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "confirmed_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "deleted_by" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_initial_document" boolean DEFAULT false NOT NULL,
    "drawing_no_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "work_order_type_name_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "planner_id" "uuid",
    "planner_name_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "dispatcher_id" "uuid",
    "dispatcher_name_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "inbound_warehouse_id" "uuid",
    "inbound_warehouse_name_snapshot" "text" DEFAULT ''::"text" NOT NULL,
    "production_fixed_lead_days_snapshot" integer DEFAULT 0 NOT NULL,
    "production_preprocess_days_snapshot" integer DEFAULT 0 NOT NULL,
    "self_made_production_days_snapshot" integer DEFAULT 0 NOT NULL,
    "production_postprocess_days_snapshot" integer DEFAULT 0 NOT NULL,
    "production_days_snapshot" integer DEFAULT 0 NOT NULL,
    "scheduling_rule_id" "uuid",
    "scheduling_priority" integer DEFAULT 50 NOT NULL,
    "scheduling_strategy_snapshot" "text" DEFAULT 'forward'::"text" NOT NULL,
    "planning_time_fence_days_snapshot" integer DEFAULT 0 NOT NULL,
    "batch_rounding_quantity_snapshot" numeric,
    "schedule_locked" boolean DEFAULT false NOT NULL,
    "last_scheduled_at" timestamp with time zone,
    "financially_closed_at" timestamp with time zone,
    "order_status" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("status" = 'abnormal'::"text") THEN 'ABNORMAL'::"text"
    WHEN ("financially_closed_at" IS NOT NULL) THEN 'CLSD'::"text"
    WHEN ("status" = 'closed'::"text") THEN 'TECO'::"text"
    WHEN ("status" = 'pending'::"text") THEN 'CRTD'::"text"
    WHEN ("warehoused_quantity" >= "order_quantity") THEN 'DLV'::"text"
    WHEN ("warehoused_quantity" > (0)::numeric) THEN 'PDLV'::"text"
    WHEN ("completed_quantity" >= "order_quantity") THEN 'CNF'::"text"
    WHEN ("completed_quantity" > (0)::numeric) THEN 'PCNF'::"text"
    ELSE 'REL'::"text"
END) STORED,
    "extension_values" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "extension_schema_snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "packing_enabled_snapshot" boolean DEFAULT false NOT NULL,
    "packing_thickness_field_key_snapshot" "text",
    "packing_published_at" timestamp with time zone,
    "packing_published_by" "text",
    "packing_rule_id" "uuid",
    "accessory_item_id" "uuid",
    CONSTRAINT "mes_work_order_extension_schema_ck" CHECK (("jsonb_typeof"("extension_schema_snapshot") = 'array'::"text")),
    CONSTRAINT "mes_work_order_extension_values_ck" CHECK (("jsonb_typeof"("extension_values") = 'object'::"text")),
    CONSTRAINT "mes_work_order_financial_close_ck" CHECK ((("financially_closed_at" IS NULL) OR ("status" = 'closed'::"text"))),
    CONSTRAINT "mes_work_order_production_days_check" CHECK ((("production_fixed_lead_days_snapshot" >= 0) AND ("production_preprocess_days_snapshot" >= 0) AND ("self_made_production_days_snapshot" >= 0) AND ("production_postprocess_days_snapshot" >= 0) AND ("production_days_snapshot" = ((("production_fixed_lead_days_snapshot" + "production_preprocess_days_snapshot") + "self_made_production_days_snapshot") + "production_postprocess_days_snapshot")))),
    CONSTRAINT "mes_work_order_qty_check" CHECK ((("order_quantity" > (0)::numeric) AND ("completed_quantity" >= (0)::numeric) AND ("warehoused_quantity" >= (0)::numeric))),
    CONSTRAINT "mes_work_order_scheduling_ck" CHECK ((("scheduling_priority" >= 1) AND ("scheduling_priority" <= 100) AND ("scheduling_strategy_snapshot" = ANY (ARRAY['forward'::"text", 'backward'::"text"])) AND (("planning_time_fence_days_snapshot" >= 0) AND ("planning_time_fence_days_snapshot" <= 365)) AND (("batch_rounding_quantity_snapshot" IS NULL) OR ("batch_rounding_quantity_snapshot" > (0)::numeric)))),
    CONSTRAINT "mes_work_order_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'abnormal'::"text", 'confirmed'::"text", 'closed'::"text"]))),
    CONSTRAINT "mes_work_order_urgency_check" CHECK (("urgency" = ANY (ARRAY['normal'::"text", 'urgent1'::"text", 'urgent2'::"text", 'urgent3'::"text"])))
);


ALTER TABLE "public"."mes_work_order" OWNER TO "postgres";

