--

--

CREATE TABLE IF NOT EXISTS "public"."sys_document_number_scene" (
    "rule_key" "text" NOT NULL,
    "rule_name" "text" NOT NULL,
    "field_label" "text" NOT NULL,
    "category" "text" NOT NULL,
