    WHEN 'sales_order'::"text" THEN ("app_private"."has_permission"('ScmSalesOrder:Add'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Copy'::"text"))
    WHEN 'shipping_notice'::"text" THEN ("app_private"."has_permission"('ScmShippingNotice:Add'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Copy'::"text"))
    WHEN 'loading'::"text" THEN ("app_private"."has_permission"('ScmLoading:Add'::"text") OR "app_private"."has_permission"('ScmLoading:Copy'::"text"))
    ELSE false
END));


