--

CREATE POLICY "scm_sales_document_update" ON "public"."scm_sales_document" FOR UPDATE TO "authenticated" USING ((("tenant_id" = "app_private"."current_user_tenant_id"()) AND
CASE "kind"
    WHEN 'sales_quotation'::"text" THEN ("app_private"."has_permission"('ScmSalesQuotationDoc:Edit'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Activate'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Expire'::"text"))
    WHEN 'project_quotation'::"text" THEN ("app_private"."has_permission"('ScmProjectQuotation:Edit'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Activate'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Complete'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Close'::"text"))
    WHEN 'sales_contract'::"text" THEN ("app_private"."has_permission"('ScmSalesContract:Edit'::"text") OR "app_private"."has_permission"('ScmSalesContract:Submit'::"text") OR "app_private"."has_permission"('ScmSalesContract:Withdraw'::"text") OR "app_private"."has_permission"('ScmSalesContract:Approve'::"text") OR "app_private"."has_permission"('ScmSalesContract:Activate'::"text") OR "app_private"."has_permission"('ScmSalesContract:Terminate'::"text") OR "app_private"."has_permission"('ScmSalesContract:Archive'::"text"))
    WHEN 'sales_order'::"text" THEN ("app_private"."has_permission"('ScmSalesOrder:Edit'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Submit'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Withdraw'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Approve'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Fulfill'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Complete'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Cancel'::"text"))
    WHEN 'shipping_notice'::"text" THEN ("app_private"."has_permission"('ScmShippingNotice:Edit'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Submit'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Withdraw'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Ship'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Complete'::"text"))
    WHEN 'loading'::"text" THEN ("app_private"."has_permission"('ScmLoading:Edit'::"text") OR "app_private"."has_permission"('ScmLoading:Load'::"text") OR "app_private"."has_permission"('ScmLoading:Complete'::"text"))
    ELSE false
END)) WITH CHECK ((("tenant_id" = "app_private"."current_user_tenant_id"()) AND
CASE "kind"
    WHEN 'sales_quotation'::"text" THEN ("app_private"."has_permission"('ScmSalesQuotationDoc:Edit'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Activate'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Expire'::"text"))
    WHEN 'project_quotation'::"text" THEN ("app_private"."has_permission"('ScmProjectQuotation:Edit'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Activate'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Complete'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Close'::"text"))
    WHEN 'sales_contract'::"text" THEN ("app_private"."has_permission"('ScmSalesContract:Edit'::"text") OR "app_private"."has_permission"('ScmSalesContract:Submit'::"text") OR "app_private"."has_permission"('ScmSalesContract:Withdraw'::"text") OR "app_private"."has_permission"('ScmSalesContract:Approve'::"text") OR "app_private"."has_permission"('ScmSalesContract:Activate'::"text") OR "app_private"."has_permission"('ScmSalesContract:Terminate'::"text") OR "app_private"."has_permission"('ScmSalesContract:Archive'::"text"))
    WHEN 'sales_order'::"text" THEN ("app_private"."has_permission"('ScmSalesOrder:Edit'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Submit'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Withdraw'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Approve'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Fulfill'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Complete'::"text") OR "app_private"."has_permission"('ScmSalesOrder:Cancel'::"text"))
    WHEN 'shipping_notice'::"text" THEN ("app_private"."has_permission"('ScmShippingNotice:Edit'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Submit'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Withdraw'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Ship'::"text") OR "app_private"."has_permission"('ScmShippingNotice:Complete'::"text"))
    WHEN 'loading'::"text" THEN ("app_private"."has_permission"('ScmLoading:Edit'::"text") OR "app_private"."has_permission"('ScmLoading:Load'::"text") OR "app_private"."has_permission"('ScmLoading:Complete'::"text"))
    ELSE false
END));


