--
-- Name: mdm_master_group tenant_insert; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "tenant_insert" ON "public"."mdm_master_group";
--

CREATE POLICY "tenant_insert" ON "public"."mdm_master_group" FOR INSERT TO "authenticated" WITH CHECK ((("tenant_id" = ( SELECT "app_private"."current_user_tenant_id"() AS "current_user_tenant_id")) AND
CASE "domain"
    WHEN 'customer'::"text" THEN ( SELECT "app_private"."has_permission"('MdmSalesCustomer:ManageGroup'::"text") AS "has_permission")
    WHEN 'project'::"text" THEN ( SELECT "app_private"."has_permission"('MdmSalesProject:ManageGroup'::"text") AS "has_permission")
    WHEN 'operation'::"text" THEN ( SELECT "app_private"."has_permission"('MdmOperationSet:ManageGroup'::"text") AS "has_permission")
    WHEN 'process-route'::"text" THEN ( SELECT "app_private"."has_permission"('MdmProcessRoute:ManageGroup'::"text") AS "has_permission")
    WHEN 'warehouse'::"text" THEN ( SELECT "app_private"."has_permission"('MdmWarehouseDefinition:ManageGroup'::"text") AS "has_permission")
    ELSE false
END));


