-- Name: sys_user_tenant tenant_insert; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "tenant_insert" ON "public"."sys_user_tenant";
--

CREATE POLICY "tenant_insert" ON "public"."sys_user_tenant" FOR INSERT WITH CHECK (("app_private"."is_platform_super"() OR (("tenant_id" = "app_private"."current_user_tenant_id"()) AND "app_private"."is_tenant_admin"())));


--

--
-- Name: tms_order tenant_insert; Type: POLICY; Schema: public
--

DROP POLICY IF EXISTS "tenant_insert" ON "public"."tms_order";
--

CREATE POLICY "tenant_insert" ON "public"."tms_order" FOR INSERT TO "authenticated" WITH CHECK ((( SELECT "app_private"."can_manage_tms"() AS "can_manage_tms") AND (( SELECT "app_private"."is_platform_super"() AS "is_platform_super") OR ("tenant_id" = ( SELECT "app_private"."current_user_tenant_id"() AS "current_user_tenant_id"))) AND (("shipping_customer_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."mdm_customer" "customer"
  WHERE (("customer"."id" = "tms_order"."shipping_customer_id") AND (( SELECT "app_private"."is_platform_super"() AS "is_platform_super") OR ("customer"."tenant_id" = ( SELECT "app_private"."current_user_tenant_id"() AS "current_user_tenant_id"))))))) AND (("receiving_customer_id" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."mdm_customer" "customer"
  WHERE (("customer"."id" = "tms_order"."receiving_customer_id") AND (( SELECT "app_private"."is_platform_super"() AS "is_platform_super") OR ("customer"."tenant_id" = ( SELECT "app_private"."current_user_tenant_id"() AS "current_user_tenant_id")))))))));


